import type { Scan } from "@/lib/watchTypes";

const label = (value: string) => value.replaceAll("_", " ").replace(/^./, (letter) => letter.toUpperCase());
const state = (value: string) => value === "failed" ? "state-failure" : value === "success" ? "state-healthy" : value === "running" ? "state-agent" : "state-attention";

function count(total: number, noun: string) { return `${total} ${noun}${total === 1 ? "" : "s"}`; }

export default function WatchScanPreview({ scan }: { scan: Scan | null }) {
  if (!scan) return null;
  const samples = scan.provider_results.flatMap((result) => result.candidates.map((candidate) => ({ ...candidate, provider: result.provider_id })));
  return <section className="agent-note" aria-labelledby="scan-preview-heading">
    <div className="agent-label"><span className="agent-mark" />Durable scan preview</div>
    <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", marginTop: 10 }}><h2 id="scan-preview-heading">Scan results</h2><span className={`state-label ${state(scan.status)}`}>{label(scan.status)}</span></div>
    <p className="muted" style={{ margin: "8px 0 0" }}>{count(scan.development_count, "development")} · {count(scan.briefing_item_count, "Briefing item")} · {count(scan.review_packet_count, "review connection")}</p>
    <h3 style={{ marginTop: 20 }}>Provider outcomes</h3>
    <div className="stack-list" style={{ marginTop: 10 }}>{scan.provider_results.map((result) => <div className="card card-pad" key={result.provider_id}>
      <div style={{ display: "flex", justifyContent: "space-between", gap: 12 }}><strong>{label(result.provider_id)}</strong><span className={`state-label ${state(result.status)}`}>{label(result.status)}</span></div>
      {result.warnings.length ? <ul>{result.warnings.map((warning) => <li key={warning}>{warning}</li>)}</ul> : <p className="small muted" style={{ margin: "8px 0 0" }}>No provider warnings.</p>}
    </div>)}</div>
    <h3 style={{ marginTop: 20 }}>Source coverage</h3>
    {scan.source_coverage.length ? <ul>{scan.source_coverage.map((coverage, index) => <li key={`${coverage.source_id ?? coverage.url}-${index}`}><strong>{label(coverage.status)}:</strong> {coverage.message || coverage.url || coverage.source_id}</li>)}</ul> : <p className="muted">No source coverage was reported.</p>}
    {scan.warnings.length ? <div className="warning-callout"><strong>Warnings</strong><ul>{scan.warnings.map((warning) => <li key={warning}>{warning}</li>)}</ul></div> : null}
    <h3 style={{ marginTop: 20 }}>Sample items</h3>
    {samples.length ? <div className="stack-list" style={{ marginTop: 10 }}>{samples.slice(0, 5).map((item, index) => <article className="card card-pad" key={`${item.provider}-${item.canonical_url}-${index}`}><div className="record-meta">{label(item.provider)}</div><strong>{item.title}</strong><p className="muted" style={{ margin: "6px 0 0" }}>{item.summary}</p>{item.canonical_url ? <a className="auto-link" href={item.canonical_url} rel="noreferrer" target="_blank">Read source</a> : null}</article>)}</div> : <p className="muted">No sample items were returned.</p>}
  </section>;
}

frontend/components/WatchBuilder.tsx:
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import DataLoadStatus from "@/components/DataLoadStatus";
import SourceRoleEditor from "@/components/SourceRoleEditor";
import WatchScanPreview from "@/components/WatchScanPreview";
import { formatDateTime } from "@/lib/design";
import { activateWatch, createWatchDraft, getProviderCapabilities, getWatch, getWatchRuns, pauseWatch, scanWatch, updateWatch } from "@/lib/watchApi";
import type { AttentionState, InternalScope, ProviderCapability, ProviderSelection, Scan, ScheduleRecurrence, Watch, WatchPurpose } from "@/lib/watchTypes";

type EditableWatch = Pick<Watch, "title" | "standing_question" | "public_query" | "purposes" | "sources" | "internal_scope" | "provider" | "recurrence" | "briefing" | "review">;
const purposes: { id: WatchPurpose; label: string }[] = [{ id: "awareness", label: "Awareness" }, { id: "company_impact", label: "Company impact" }, { id: "decision_maintenance", label: "Decision maintenance" }];
const weekdays: ScheduleRecurrence["weekdays"] = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
const empty: EditableWatch = {
  title: "", standing_question: "", purposes: ["awareness"], provider: "native", sources: [],
  public_query: { standing_question: "", keywords: [], topics: [], jurisdictions: [], regulators: [], courts: [], industries: [], public_source_urls: [], public_entities: [] },
  internal_scope: { product_ids: [], company_paths: [], matter_ids: [], decision_ids: [], mitigation_ids: [], lookback_days: 90 },
  recurrence: { kind: "daily", interval_seconds: null, local_time: "08:00", time_zone: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC", weekdays: [] },
  briefing: { create_items: true, create_digest: false, saved_view_id: null }, review: { enabled: true, default_attention: "monitor" },
};
const split = (value: string) => value.split(/[,\n]/).map((item) => item.trim()).filter(Boolean);
const join = (value: string[]) => value.join(", ");
const titleCase = (value: string) => value.replaceAll("_", " ").replace(/^./, (letter) => letter.toUpperCase());
function editableWatch(watch: Watch): EditableWatch {
  return {
    title: watch.title,
    standing_question: watch.standing_question,
    public_query: watch.public_query,
    purposes: watch.purposes,
    sources: watch.sources,
    internal_scope: watch.internal_scope,
    provider: watch.provider,
    recurrence: watch.recurrence,
    briefing: watch.briefing,
    review: watch.review,
  };
}

export default function WatchBuilder({ watchId }: { watchId?: string }) {
  const router = useRouter();
  const [record, setRecord] = useState<Watch | null>(null);
  const [draft, setDraft] = useState<EditableWatch>(empty);
  const [runs, setRuns] = useState<Scan[]>([]);
  const [providers, setProviders] = useState<ProviderCapability[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  const load = useCallback(async () => {
    setLoading(true); setLoadError("");
    try {
      const [capabilities, watch, history] = await Promise.all([
        getProviderCapabilities(), watchId ? getWatch(watchId) : Promise.resolve(null), watchId ? getWatchRuns(watchId, { limit: 20 }) : Promise.resolve({ items: [], next_cursor: null, total: 0 }),
      ]);
      setProviders(capabilities.items);
      if (watch) { setRecord(watch); setDraft(editableWatch(watch)); setRuns(history.items); }
      setLoaded(true);
    } catch { setLoadError("This Watch is unavailable because its current data could not be loaded."); }
    finally { setLoading(false); }
  }, [watchId]);
  useEffect(() => { void load(); }, [load]);

  function patch(change: Partial<EditableWatch>) { setDraft((current) => ({ ...current, ...change })); setNotice(""); }
  function patchQuery(key: keyof EditableWatch["public_query"], value: unknown) { patch({ public_query: { ...draft.public_query, [key]: value } }); }
  function patchScope(key: keyof InternalScope, value: string[] | number) { patch({ internal_scope: { ...draft.internal_scope, [key]: value } }); }

  function normalized(): EditableWatch {
    const standing = draft.standing_question.trim();
    return {
      title: draft.title.trim(),
      standing_question: standing,
      public_query: { ...draft.public_query, standing_question: draft.public_query.standing_question.trim() || standing, public_source_urls: draft.sources.filter((source) => source.role !== "excluded").map((source) => source.canonical_url).filter((url) => /^https:\/\//.test(url)) },
      purposes: draft.purposes,
      sources: draft.sources,
      internal_scope: draft.internal_scope,
      provider: draft.provider,
      recurrence: draft.recurrence,
      briefing: draft.briefing,
      review: draft.review,
    };
  }

  async function save(): Promise<Watch> {
    const payload = normalized();
    if (!payload.title || !payload.standing_question || !payload.public_query.standing_question) throw new Error("Add a title, standing question, and public query before saving.");
    if (!payload.purposes.length) throw new Error("Select at least one purpose.");
    if (payload.sources.some((source) => !source.name.trim() || !/^https:\/\//.test(source.canonical_url))) throw new Error("Each named source needs a name and a public HTTPS URL.");
    if (!record) {
      const created = await createWatchDraft({ title: payload.title, standing_question: payload.standing_question, public_query: payload.public_query, purposes: payload.purposes, provider: payload.provider });
      const updated = await updateWatch(created.watch_id, { expected_revision: created.revision, sources: payload.sources, internal_scope: payload.internal_scope, recurrence: payload.recurrence, briefing: payload.briefing, review: payload.review });
      setRecord(updated); setDraft(editableWatch(updated)); return updated;
    }
    const updated = await updateWatch(record.watch_id, { expected_revision: record.revision, ...payload });
    setRecord(updated); setDraft(editableWatch(updated)); return updated;
  }

  async function act(action: "save" | "scan" | "start" | "pause") {
    setBusy(action); setError(""); setNotice("");
    try {
      const saved = await save();
      if (action === "save") { setNotice("Draft saved. The Watch remains disabled."); if (!watchId) router.push(`/watches/${encodeURIComponent(saved.watch_id)}`); return; }
      if (action === "scan") {
        const result = await scanWatch(saved.watch_id, { mode: saved.enabled ? "manual" : "draft" });
        const refreshed = await getWatch(saved.watch_id); setRecord(refreshed); setDraft(editableWatch(refreshed));
        setRuns((current) => [result.scan, ...current.filter((run) => run.scan_id !== result.scan.scan_id)]);
        setNotice("Scan saved. The schedule state did not change."); if (!watchId) router.push(`/watches/${encodeURIComponent(saved.watch_id)}`); return;
      }
      if (action === "start") { const result = await activateWatch(saved.watch_id, { expected_revision: saved.revision }); setRecord(result.watch); setDraft(editableWatch(result.watch)); setNotice("Watch started. Its schedule is active."); if (!watchId) router.push(`/watches/${encodeURIComponent(saved.watch_id)}`); return; }
      const paused = await pauseWatch(saved.watch_id, { expected_revision: saved.revision }); setRecord(paused); setDraft(editableWatch(paused)); setNotice("Watch paused. Saved settings are unchanged.");
    } catch (caught) { setError(caught instanceof Error ? caught.message : "The Watch action failed."); }
    finally { setBusy(""); }
  }

  if (!loaded) return <DataLoadStatus error={loadError} loading={loading} loadingLabel="Loading Watch…" onRetry={load} />;
  const status = record?.status ?? "draft";
  const statusClass = status === "failed" ? "state-failure" : status === "healthy" ? "state-healthy" : status === "draft" || status === "scanning" ? "state-agent" : "state-attention";

  return <>
    <DataLoadStatus error={loadError} loading={loading} loadingLabel="Refreshing Watch…" onRetry={load} />
    <div className="page-header"><div><div className="record-meta">Briefing · Watch Builder</div><h1>{record ? draft.title || "Edit Watch" : "New Watch"}</h1><p>Define one public monitoring assignment. You can save or scan it without starting a schedule.</p></div><div className="btn-row"><span className={`state-label ${statusClass}`}>{titleCase(status)}</span><Link className="btn quiet" href="/watches">All Watches</Link></div></div>
    {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <div className="warning-callout" role="status" style={{ marginTop: 16 }}>{notice}</div> : null}
    <div className="stack-list" style={{ marginTop: 24 }}>
      <section className="card card-pad"><h2>Assignment</h2><p className="muted">State what to watch and why it matters.</p>
        <div style={{ display: "grid", gap: 14 }}>
          <label className="field-label">
            Watch title
            <input autoFocus={!watchId} className="text-input" onChange={(event) => patch({ title: event.target.value })} value={draft.title} />
          </label>
          <label className="field-label">
            Standing question
            <textarea
              className="text-input watch-question-input"
              onChange={(event) => { patch({ standing_question: event.target.value }); if (!draft.public_query.standing_question || draft.public_query.standing_question === draft.standing_question) patchQuery("standing_question", event.target.value); }}
              placeholder="The internal goal: what should this Watch answer, and why does it matter to your company?"
              rows={3}
              value={draft.standing_question}
            />
          </label>
          <label className="field-label">
            Public query
            <textarea
              className="text-input watch-question-input"
              onChange={(event) => patchQuery("standing_question", event.target.value)}
              placeholder="The public-only question sent to the provider. Do not include private company or matter details."
              rows={3}
              value={draft.public_query.standing_question}
            />
            <span className="small muted">Only public collection terms and public entities belong here.</span>
          </label>
        </div>
        <fieldset style={{ border: 0, padding: 0, margin: "18px 0 0" }}><legend className="field-label">Purpose</legend>{purposes.map((purpose) => <label className="checkbox-row" key={purpose.id}><input checked={draft.purposes.includes(purpose.id)} onChange={() => patch({ purposes: draft.purposes.includes(purpose.id) ? draft.purposes.filter((item) => item !== purpose.id) : [...draft.purposes, purpose.id] })} type="checkbox" />{purpose.label}</label>)}</fieldset>
      </section>
      <section className="card card-pad"><h2>Public topics and scope</h2><p className="muted">Use commas to separate values.</p><div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: 14 }}>{(["keywords", "topics", "jurisdictions", "regulators", "courts", "industries"] as const).map((key) => <label className="field-label" key={key}>{titleCase(key)}<input className="text-input" onChange={(event) => patchQuery(key, split(event.target.value))} value={join(draft.public_query[key])} /></label>)}</div></section>
      <section className="card card-pad"><h2>Named sources and roles</h2><p className="muted">Source type states what a source is. Role states how this Watch uses it.</p><SourceRoleEditor onChange={(sources) => patch({ sources })} sources={draft.sources} /></section>
      <section className="card card-pad"><h2>Provider</h2><p className="muted">The choice is saved on this Watch. A provider failure does not change it.</p><div className="btn-row">{(["native", "polaris", "both"] as ProviderSelection[]).map((provider) => <button aria-pressed={draft.provider === provider} className={`btn ${draft.provider === provider ? "primary" : ""}`} key={provider} onClick={() => patch({ provider })} type="button">{provider === "native" ? "Themis.ai native" : titleCase(provider)}</button>)}</div>{providers.filter((provider) => !provider.available || provider.warning).map((provider) => <p className="warning-callout" key={provider.provider_id}><strong>{provider.label}:</strong> {provider.warning || "Not available."}</p>)}</section>
      <section className="card card-pad"><h2>Internal matching scope</h2><p className="muted">This private scope stays inside Themis.ai. Use commas to separate record IDs or paths.</p><div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: 14 }}>{(["product_ids", "company_paths", "matter_ids", "decision_ids", "mitigation_ids"] as const).map((key) => <label className="field-label" key={key}>{titleCase(key)}<input className="text-input" onChange={(event) => patchScope(key, split(event.target.value))} value={join(draft.internal_scope[key])} /></label>)}<label className="field-label">Lookback days<input className="text-input" min={1} onChange={(event) => patchScope("lookback_days", Number(event.target.value))} type="number" value={draft.internal_scope.lookback_days} /></label></div></section>
      <ScheduleSection draft={draft} patch={patch} />
      <section className="card card-pad"><h2>Briefing and review behavior</h2><label className="checkbox-row"><input checked={draft.briefing.create_items} onChange={(event) => patch({ briefing: { ...draft.briefing, create_items: event.target.checked } })} type="checkbox" />Create Briefing items</label><label className="checkbox-row"><input checked={draft.briefing.create_digest} onChange={(event) => patch({ briefing: { ...draft.briefing, create_digest: event.target.checked } })} type="checkbox" />Create a digest</label><label className="checkbox-row"><input checked={draft.review.enabled} onChange={(event) => patch({ review: { ...draft.review, enabled: event.target.checked } })} type="checkbox" />Create review connections when company work may be affected</label><label className="field-label" style={{ marginTop: 12 }}>Default attention<select className="select-input" disabled={!draft.review.enabled} onChange={(event) => patch({ review: { ...draft.review, default_attention: event.target.value as AttentionState } })} value={draft.review.default_attention}><option value="briefing_only">Briefing only</option><option value="monitor">Monitor</option><option value="this_week">This week</option><option value="required">Required</option></select></label></section>
      <div className="card card-pad"><div className="btn-row"><button className="btn" disabled={!!busy} onClick={() => void act("save")} type="button">{busy === "save" ? "Saving…" : "Save draft"}</button><button className="btn agent" disabled={!!busy} onClick={() => void act("scan")} type="button">{busy === "scan" ? "Scanning…" : "Scan now"}</button>{record?.enabled ? <button className="btn review" disabled={!!busy} onClick={() => void act("pause")} type="button">{busy === "pause" ? "Pausing…" : "Pause schedule"}</button> : <button className="btn primary" disabled={!!busy} onClick={() => void act("start")} type="button">{busy === "start" ? "Starting…" : "Start Watch"}</button>}</div><p className="small muted" style={{ margin: "12px 0 0" }}>Start Watch is the only action that enables a schedule. Scan now saves first and does not activate one.</p></div>
      <WatchScanPreview scan={runs[0] ?? null} />
      {record ? <section className="card card-pad"><h2>Run history</h2>{runs.length ? <div className="row-list" style={{ margin: "12px -20px -18px" }}>{runs.map((run) => <div className="row" key={run.scan_id}><div style={{ flex: 1 }}><strong>{titleCase(run.mode)} scan</strong><div className="record-meta" style={{ marginTop: 6 }}>{formatDateTime(run.started_at)} · {run.scan_id}</div></div><span className={`state-label ${run.status === "success" ? "state-healthy" : run.status === "failed" ? "state-failure" : run.status === "running" ? "state-agent" : "state-attention"}`}>{titleCase(run.status)}</span></div>)}</div> : <p className="muted">No scans yet.</p>}</section> : null}
    </div>
  </>;
}

function ScheduleSection({ draft, patch }: { draft: EditableWatch; patch: (change: Partial<EditableWatch>) => void }) {
  const recurrence = draft.recurrence;
  function set(change: Partial<ScheduleRecurrence>) { patch({ recurrence: { ...recurrence, ...change } }); }
  function kind(value: ScheduleRecurrence["kind"]) {
    if (value === "manual") set({ kind: value, interval_seconds: null, local_time: null, time_zone: null, weekdays: [] });
    else if (value === "interval") set({ kind: value, interval_seconds: recurrence.interval_seconds || 86400, local_time: null, time_zone: null, weekdays: [] });
    else set({ kind: value, interval_seconds: null, local_time: recurrence.local_time || "08:00", time_zone: recurrence.time_zone || "UTC", weekdays: value === "weekday" ? recurrence.weekdays.length ? recurrence.weekdays : ["monday"] : [] });
  }
  return <section className="card card-pad"><h2>Cadence and time zone</h2><div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: 14 }}><label className="field-label">Cadence<select className="select-input" onChange={(event) => kind(event.target.value as ScheduleRecurrence["kind"])} value={recurrence.kind}><option value="manual">Manual only</option><option value="interval">Interval</option><option value="daily">Daily</option><option value="weekday">Selected weekdays</option></select></label>{recurrence.kind === "interval" ? <label className="field-label">Every (hours)<input className="text-input" min={1} onChange={(event) => set({ interval_seconds: Number(event.target.value) * 3600 })} type="number" value={(recurrence.interval_seconds || 3600) / 3600} /></label> : null}{recurrence.kind === "daily" || recurrence.kind === "weekday" ? <><label className="field-label">Local time<input className="text-input" onChange={(event) => set({ local_time: event.target.value })} type="time" value={recurrence.local_time || "08:00"} /></label><label className="field-label">IANA time zone<input className="text-input" onChange={(event) => set({ time_zone: event.target.value })} value={recurrence.time_zone || "UTC"} /></label></> : null}</div>{recurrence.kind === "weekday" ? <fieldset style={{ border: 0, padding: 0, margin: "16px 0 0" }}><legend className="field-label">Run on</legend><div className="btn-row">{weekdays.map((day) => <label className="checkbox-row" key={day}><input checked={recurrence.weekdays.includes(day)} onChange={() => set({ weekdays: recurrence.weekdays.includes(day) ? recurrence.weekdays.filter((item) => item !== day) : [...recurrence.weekdays, day] })} type="checkbox" />{titleCase(day)}</label>)}</div></fieldset> : null}</section>;
}

frontend/components/SkillBuilder.tsx:
"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import DataLoadStatus from "@/components/DataLoadStatus";
import {
  createSkill,
  draftSkill,
  getSkillQuestions,
  getSkills,
  getSkillSuggestions,
  updateSkill,
} from "@/lib/api";
import type { SkillDefinition, SkillDraft, SkillQuestion, SkillSuggestion } from "@/lib/types";

type View = "home" | "goal" | "question" | "draft" | "edit" | "saved";
export default function SkillBuilder({ initialGoal, initialDraft, onSaveDraft }: { initialGoal: string; initialDraft?: SkillDraft; onSaveDraft?: (draft: SkillDraft) => Promise<SkillDefinition> }) {
  const [skills, setSkills] = useState<SkillDefinition[]>([]);
  const [questions, setQuestions] = useState<SkillQuestion[]>([]);
  const [view, setView] = useState<View>(initialDraft ? "draft" : initialGoal ? "goal" : "home");
  const [goal, setGoal] = useState(initialGoal);
  const [answers, setAnswers] = useState<Record<string, string | string[]>>({});
  const [questionIndex, setQuestionIndex] = useState(0);
  const [customAnswer, setCustomAnswer] = useState("");
  const [draft, setDraft] = useState<SkillDraft | null>(initialDraft ?? null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [savedPath, setSavedPath] = useState("");
  const [suggestions, setSuggestions] = useState<SkillSuggestion[]>([]);
  const [reviewNote, setReviewNote] = useState("");
  const [warning, setWarning] = useState("");
  const [error, setError] = useState("");
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [busy, setBusy] = useState(false);
  const [findingSuggestions, setFindingSuggestions] = useState(false);
  const focusRef = useRef<HTMLDivElement>(null);

  const load = useCallback(async () => {
    setLoading(true); setLoadError("");
    try {
      const [{ skills: saved }, { questions: fixed }] = await Promise.all([getSkills(), getSkillQuestions()]);
      setSkills(saved);
      setQuestions(fixed);
      setLoaded(true);
    } catch { setLoadError("Skills are unavailable because their current data could not be loaded."); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (view === "question") focusRef.current?.focus(); }, [questionIndex, view]);

  function startGuided(nextGoal = "") {
    setGoal(nextGoal); setAnswers({}); setQuestionIndex(0); setCustomAnswer("");
    setDraft(null); setEditingId(null); setSavedPath(""); setSuggestions([]); setReviewNote(""); setWarning(""); setError(""); setView("goal");
  }

  function goHome() {
    setDraft(null); setEditingId(null); setSavedPath(""); setSuggestions([]); setReviewNote(""); setWarning(""); setError(""); setView("home");
  }

  function advance(answer?: string | string[]) {
    const question = questions[questionIndex];
    if (question && answer !== undefined) setAnswers((current) => ({ ...current, [question.question_id]: answer }));
    setCustomAnswer("");
    if (questionIndex >= 4) setQuestionIndex(5);
    else setQuestionIndex((current) => current + 1);
  }

  async function build(extra?: string) {
    setBusy(true); setError("");
    const nextAnswers = extra?.trim() ? { ...answers, anything_else: extra.trim() } : answers;
    try {
      const result = await draftSkill({ goal: goal.trim(), answers: nextAnswers });
      setDraft(result.draft); setWarning(result.warning ?? ""); setEditingId(null); setView("draft");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not build the draft.");
    } finally { setBusy(false); }
  }

  async function save() {
    if (!draft) return;
    setBusy(true); setError("");
    try {
      const saved = onSaveDraft ? await onSaveDraft(draft) : editingId
        ? await updateSkill(editingId, draft)
        : await createSkill(draft);
      await load(); setDraft(saved); setSavedPath(saved.path); setEditingId(saved.skill_id); setView("saved");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not save the skill.");
    } finally { setBusy(false); }
  }

  async function findRepeatedWork() {
    setBusy(true); setFindingSuggestions(true); setError(""); setWarning(""); setReviewNote("");
    try {
      const result = await getSkillSuggestions();
      const nextSuggestions = result.suggestions.slice(0, 3);
      setSuggestions(nextSuggestions); setWarning(result.warning ?? "");
      setReviewNote(!nextSuggestions.length && !result.warning ? "No repeated work found in recent messages." : "");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not review recent work.");
    } finally { setBusy(false); setFindingSuggestions(false); }
  }

  function editSkill(skill: SkillDefinition) {
    setEditingId(skill.skill_id);
    setDraft({ skill_id: skill.skill_id, name: skill.name, description: skill.description, instructions: skill.instructions });
    setSavedPath(skill.path); setSuggestions([]); setReviewNote(""); setWarning(""); setError(""); setView("edit");
  }

  const question = questions[questionIndex];
  const multiple = question?.selection_mode === "multiple";
  const selected = (answers[question?.question_id] ?? []) as string | string[];
  const selectedValues = Array.isArray(selected) ? selected : selected ? [selected] : [];
  const anythingElse = question?.question_id === "anything_else";

  if (!loaded) {
    return <main className="page"><DataLoadStatus error={loadError} loading={loading} loadingLabel="Loading skills…" onRetry={load} /></main>;
  }

  return (
    <div className="admin-shell">
      <aside className="admin-rail admin-rail-wide">
        <div className="skill-rail-head">
          <span className="admin-rail-title" style={{ padding: 0 }}>Your skills</span>
          <span>{skills.length}</span>
        </div>
        <button className={`admin-rail-link ${view === "home" ? "active" : ""}`} onClick={goHome} type="button">Overview</button>
        <div className="skill-rail-list">
          {skills.length === 0 ? <p className="tree-group-help">No skill saved yet.</p> : null}
          {skills.map((skill) => (
            <button className={`agent-rail-item ${editingId === skill.skill_id ? "active" : ""}`} key={skill.skill_id} onClick={() => editSkill(skill)} type="button">
              <span className="agent-rail-name">{skill.name}</span>
              <span className="agent-rail-role">{skill.description}</span>
              <span className="mono skill-command">/{skill.skill_id}</span>
            </button>
          ))}
        </div>
      </aside>

      <div className="admin-main">
        <div className="admin-scroll">
          <div className="admin-body wide">
            <DataLoadStatus error={loadError} loading={loading} loadingLabel="Refreshing skills…" onRetry={load} />
            {view === "home" ? (
              <>
                <div className="eyebrow">Reusable guidance</div>
                <h1>Skills</h1>
                <p className="skill-intro">
                  A skill is reusable guidance for one chat request. Save the way you want a recurring
                  kind of work handled once, then type its command in chat and Themis.ai follows that
                  guidance for that one message.
                </p>

                <div className="skill-start-grid">
                  <div className="skill-start-card lead">
                    <h2>Start from work you repeat</h2>
                    <p>Say what you want to make easier. Themis.ai asks five short questions, writes the guidance, and lets you edit every word before it is saved.</p>
                    <div className="btn-row"><button className="btn primary" onClick={() => startGuided()} type="button">Build a skill</button></div>
                  </div>
                  <div className="skill-start-card">
                    <h2>Let Themis.ai spot the pattern</h2>
                    <p>Themis.ai reads your recent chat messages and proposes up to three skills worth saving, each with the messages that suggested it. Nothing is created until you choose to build it.</p>
                    <div className="btn-row"><button className="btn" disabled={busy} onClick={() => void findRepeatedWork()} type="button">{findingSuggestions ? "Reviewing…" : "Find repeated work"}</button></div>
                  </div>
                </div>

                <div className="skill-example">
                  <strong>How you use one:</strong> in any chat, type <span className="mono">/product-launch-review</span> and
                  your request. The skill shapes that answer only. It never changes what Themis.ai is allowed to do.
                </div>

                <section className="skill-section">
                  <div className="skill-section-head">
                    <h2>Saved skills</h2>
                    <span>{skills.length === 1 ? "1 skill" : `${skills.length} skills`} · select one to read or edit it</span>
                  </div>
                  {skills.length === 0 ? (
                    <div className="empty-state" style={{ marginTop: 14 }}>
                      No skill yet. Build one above and it becomes a chat command you can use everywhere.
                    </div>
                  ) : (
                    <div className="skill-grid">
                      {skills.map((skill) => (
                        <button className="skill-card" key={skill.skill_id} onClick={() => editSkill(skill)} type="button">
                          <span className="skill-card-name">{skill.name}</span>
                          <span className="skill-card-purpose">{skill.description}</span>
                          <span className="skill-card-command">/{skill.skill_id}</span>
                        </button>
                      ))}
                    </div>
                  )}
                </section>
              </>
            ) : view === "goal" ? (
              <>
                <div className="eyebrow">Step 1 of 3 · the work</div>
                <h1>What do you want to make easier?</h1>
                <p className="skill-step-help">Describe the kind of request you handle again and again. One or two sentences is enough — the next five questions fill in the detail.</p>
                <label className="field-block"><span className="field-label">The work you repeat</span>
                  <textarea autoFocus className="text-input prose" rows={4} value={goal} onChange={(event) => setGoal(event.target.value)} placeholder="I often review product launch requests." />
                </label>
                <div className="btn-row"><button className="btn primary" disabled={!goal.trim() || questions.length === 0} onClick={() => { setQuestionIndex(0); setView("question"); }} type="button">Continue</button><button className="btn" onClick={goHome} type="button">Cancel</button></div>
              </>
            ) : view === "question" && question ? (
              <div ref={focusRef} tabIndex={-1} className="skill-question-panel">
                <div className="skill-progress">
                  <span className="skill-progress-track"><span className="skill-progress-fill" style={{ width: `${Math.min(100, ((questionIndex + 1) / 6) * 100)}%` }} /></span>
                  <span>{anythingElse ? "Last question — optional" : `Question ${questionIndex + 1} of 5`}</span>
                </div>
                <h1>{question.text}</h1>
                <p className="skill-step-help">
                  {anythingElse
                    ? "Add anything the questions missed, or build the skill as it stands. You can edit the result before saving."
                    : multiple ? "Choose as many as apply, then continue. You can skip any question." : "Choose the closest answer. You can skip any question."}
                </p>
                {anythingElse ? <textarea aria-label={question.text} autoFocus className="text-input prose" rows={5} value={customAnswer} onChange={(event) => setCustomAnswer(event.target.value)} /> : (
                  <div className="question-choices skill-choices">
                    {question.choices.map((choice) => {
                      const active = selectedValues.includes(choice);
                      return <button aria-pressed={active} className={`question-choice ${active ? "active" : ""}`} key={choice} type="button" onClick={() => {
                        if (choice === "Something else") { setAnswers((current) => ({ ...current, [question.question_id]: multiple ? (active ? selectedValues.filter((item) => item !== choice) : [...selectedValues, choice]) : choice })); return; }
                        if (multiple) setAnswers((current) => ({ ...current, [question.question_id]: active ? selectedValues.filter((item) => item !== choice) : [...selectedValues, choice] }));
                        else advance(choice);
                      }}>{choice}</button>;
                    })}
                  </div>
                )}
                {!anythingElse && selectedValues.includes("Something else") ? <input aria-label="Something else" autoFocus className="text-input" placeholder="Say it in your own words" value={customAnswer} onChange={(event) => setCustomAnswer(event.target.value)} /> : null}
                <div className="btn-row skill-question-actions">
                  {anythingElse ? <><button className="btn primary" disabled={busy || !customAnswer.trim()} onClick={() => void build(customAnswer)} type="button">{busy ? "Building…" : "Add this and build it"}</button><button className="btn" disabled={busy} onClick={() => void build()} type="button">{busy ? "Building…" : "No, build it"}</button></> : <>
                    {multiple || selectedValues.includes("Something else") ? <button className="btn primary" disabled={selectedValues.includes("Something else") && !customAnswer.trim()} onClick={() => advance(selectedValues.includes("Something else") ? [...selectedValues.filter((item) => item !== "Something else"), customAnswer.trim()] : selectedValues)} type="button">Continue</button> : null}
                    <button className="btn" onClick={() => advance()} type="button">Skip</button><button className="btn agent" onClick={() => setQuestionIndex(5)} type="button">Build it now</button>
                  </>}
                </div>
              </div>
            ) : draft ? (
              <>
                <div className="eyebrow">{view === "edit" ? "Editing a saved skill" : view === "saved" ? "Saved" : "Step 3 of 3 · read it before you save"}</div>
                <div className="skill-draft-head"><h1>{draft.name || "New skill"}</h1><span className="mono skill-card-command">/{draft.skill_id}</span></div>
                <p className="skill-step-help">
                  {view === "saved"
                    ? "This skill is saved. Type its command in any chat to apply it to one request."
                    : view === "edit"
                      ? "Change anything here, then save. Existing chats that already used this skill are unchanged."
                      : "Themis.ai wrote this from your answers. Nothing is saved until you choose Create skill."}
                </p>
                {warning ? <p className="skill-warning">{warning}</p> : null}
                {view === "saved" ? <div className="agent-note" style={{ marginTop: 18, borderStyle: "solid", background: "var(--healthy-wash)", borderColor: "var(--line)" }}>
                  <span className="state-label state-healthy">Saved</span>
                  <p style={{ margin: "10px 0 0" }}><strong>{draft.name}</strong></p>
                  <p style={{ margin: "5px 0 0" }}>{draft.description}</p>
                  <p style={{ margin: "5px 0 0" }}>Use <span className="mono">/{draft.skill_id}</span> before one chat request.</p>
                </div> : null}
                {savedPath ? <p className="skill-field-help" style={{ marginTop: 12 }}>Stored in <span className="mono">{savedPath}</span></p> : null}
                <div className="skill-form-grid">
                  <label><span className="field-label">Name</span><input className="text-input" value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} /><span className="skill-field-help">What you will see in the list.</span></label>
                  <label><span className="field-label">Chat command</span><input aria-label="Skill command" className="text-input mono" disabled={!!editingId} value={draft.skill_id} onChange={(event) => setDraft({ ...draft, skill_id: event.target.value })} /><span className="skill-field-help">{editingId ? "The command cannot change once the skill is saved." : "What you type in chat, after a slash."}</span></label>
                </div>
                <label className="field-block"><span className="field-label">Purpose</span><input className="text-input" value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} /><span className="skill-field-help">One line saying when to reach for this skill.</span></label>
                <details className="field-block" open={view !== "saved"}>
                  <summary className="section-heading" style={{ cursor: "pointer" }}>Requested guidance (Markdown)</summary>
                  <p>This is the full guidance created from your request. It is what Themis.ai reads when you use the command. You can edit it before or after saving.</p>
                  <textarea aria-label="Requested guidance" className="text-input prose" rows={12} value={draft.instructions} onChange={(event) => setDraft({ ...draft, instructions: event.target.value })} />
                </details>
              </>
            ) : null}

            {error ? <p className="error">{error}</p> : null}
            {warning && view !== "draft" && view !== "saved" ? <p className="skill-warning">{warning}</p> : null}
            {reviewNote ? <p className="stub-note" style={{ marginTop: 16 }}>{reviewNote}</p> : null}
            {suggestions.length ? <section className="skill-section">
              <div className="skill-section-head">
                <h2>Work you seem to repeat</h2>
                <span>Drawn from your stored chat messages. Nothing is saved until you build one.</span>
              </div>
              <div className="skill-grid">{suggestions.map((suggestion) => <div className="chat-card skill-suggestion" key={`${suggestion.name}-${suggestion.goal}`}>
                <div className="chat-card-summary">{suggestion.name}</div>
                <div className="chat-card-detail">{suggestion.description}</div>
                {suggestion.evidence.map((item) => <blockquote key={item.message_id}>{item.content}</blockquote>)}
                <button className="btn compact" onClick={() => startGuided(suggestion.goal)} type="button">Build this skill</button>
              </div>)}</div>
            </section> : null}
          </div>
        </div>
        {(view === "draft" || view === "edit" || view === "saved") && draft ? <div className="admin-foot"><span className="stub-note">A skill guides one chat request. It cannot change what Themis.ai is allowed to do.</span><div className="btn-row"><button className="btn" onClick={() => startGuided()} type="button">Start over</button><button className="btn primary" disabled={busy || !draft.skill_id || !draft.name || !draft.description || !draft.instructions} onClick={() => void save()} type="button">{busy ? "Saving…" : editingId ? "Save changes" : "Create skill"}</button></div></div> : null}
      </div>
    </div>
  );
}

frontend/components/MatterTree.tsx:
"use client";

import { ChangeEvent, DragEvent, useState } from "react";
import { userFacingMatterTree } from "@/lib/matterBrief";
import type { FileNode } from "@/lib/types";

function TreeNode({
  node,
  activePath,
  onNewChat,
  onSelect,
  depth = 0,
}: {
  node: FileNode;
  activePath: string | null;
  onNewChat: () => void;
  onSelect: (path: string) => void;
  depth?: number;
}) {
  const [open, setOpen] = useState(depth === 0 && isCoreFolder(node.name));
  if (node.type === "folder") {
    const folderLabel = treeLabel(node);
    return (
      <div>
        <div className="tree-folder-row">
          <button
            aria-expanded={open}
            aria-label={`${open ? "Collapse" : "Expand"} ${folderLabel}`}
            className="tree-row"
            onClick={() => setOpen((value) => !value)}
            type="button"
          >
            <span className="tree-folder">{open ? "▾" : "▸"} {folderLabel}</span>
          </button>
          {node.name === "conversations" ? (
            <button aria-label="New chat" className="tree-add" onClick={onNewChat} title="New chat" type="button">+</button>
          ) : null}
        </div>
        {open && node.children ? (
          <div className="tree-indent">
            {node.name === "matter-records" ? (
              <p className="tree-group-help">Structured records captured from intake, documents, chat, lawyer edits, and system actions.</p>
            ) : null}
            {node.children.map((child) => (
              <TreeNode key={child.path} node={child} activePath={activePath} onNewChat={onNewChat} onSelect={onSelect} depth={depth + 1} />
            ))}
            {node.name === "conversations" && !node.children.length ? <div className="tree-empty">No saved chats</div> : null}
          </div>
        ) : null}
      </div>
    );
  }
  const kind = node.record_type === "chat_transcript"
    ? "conversation"
    : node.path.includes("/research/") || node.path.includes("/drafts/")
    ? "agent"
    : node.extension === ".md" ? "human" : "source";
  return (
    <button
      className={`tree-row ${activePath === node.path ? "active" : ""}`}
      onClick={() => onSelect(node.path)}
      title={node.label ?? node.name}
      type="button"
    >
      <span className={`tree-dot ${kind}`} />
      <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{treeLabel(node)}</span>
    </button>
  );
}

function isCoreFolder(name: string): boolean {
  return ["documents", "research", "work-product"].includes(name);
}

function treeLabel(node: FileNode): string {
  if (node.name === "request.md") return "Original request";
  if (node.name === "documents") return "Documents";
  if (node.name === "research") return "Research";
  if (node.name === "work-product") return "Work product";
  if (node.name === "drafts") return "Legacy Drafts";
  if (node.name === "draft") return "Draft";
  if (node.name === "final") return "Final";
  if (node.name === "dossier.md") return "Dossier";
  if (node.name === "conversations") return "Chats";
  if (node.name === "matter-records") return "Matter Records";
  return node.label ?? node.name;
}

const RECORD_LABELS: Record<string, string> = {
  "matter.md": "Matter details",
  "facts.md": "Facts, sources & assumptions",
  "issues.md": "Issue map",
  "participants.md": "People & roles",
  "recommendations.md": "Working recommendations",
  "work-items": "Work to do",
  "decisions": "Recorded decisions",
  "events": "Activity history",
  "dossier-revisions": "Dossier revisions",
};

const DIRECT_ORDER = ["request.md", "documents", "conversations", "research", "work-product", "dossier.md", "drafts"];

function presentMatterTree(tree: FileNode[]): FileNode[] {
  const conversations: FileNode = tree.find((node) => node.type === "folder" && node.name === "conversations")
    ?? { name: "conversations", label: "Chats", path: "", type: "folder" as const, children: [] };
  const nodes: FileNode[] = tree.includes(conversations) ? tree : [conversations, ...tree];
  const byName = new Map(nodes.map((node) => [node.name, node]));
  const direct = DIRECT_ORDER.flatMap((name) => {
    const node = byName.get(name);
    return node ? [{ ...node, label: treeLabel(node) }] : [];
  });
  const records = Object.entries(RECORD_LABELS).flatMap(([name, label]) => {
    const node = byName.get(name);
    return node ? [{ ...node, label }] : [];
  });
  const groupedNames = new Set([...DIRECT_ORDER, ...Object.keys(RECORD_LABELS)]);
  const remaining = nodes.filter((node) => !groupedNames.has(node.name));
  const matterRecords: FileNode = {
    name: "matter-records",
    label: "Matter Records",
    path: "virtual:matter-records",
    type: "folder",
    children: records,
  };
  return [...direct, matterRecords, ...remaining];
}

export default function MatterTree({
  tree,
  activePath,
  onNewChat,
  onSelect,
  onUpload,
  uploading,
}: {
  tree: FileNode[];
  activePath: string | null;
  onNewChat: () => void;
  onSelect: (path: string) => void;
  onUpload: (file: File) => Promise<void>;
  uploading: boolean;
}) {
  const [dragging, setDragging] = useState(false);
  const visibleTree = presentMatterTree(userFacingMatterTree(tree));

  async function uploadFromInput(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (file) await onUpload(file);
    event.target.value = "";
  }

  async function drop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault();
    setDragging(false);
    const file = event.dataTransfer.files?.[0];
    if (file) await onUpload(file);
  }

  return (
    <>
      <div className="tree">
        {visibleTree.map((node) => (
          <TreeNode key={node.path || node.name} node={node} activePath={activePath} onNewChat={onNewChat} onSelect={onSelect} />
        ))}
      </div>
      <div
        className={`drop-zone ${dragging ? "active" : ""}`}
        onDragEnter={(event) => { event.preventDefault(); setDragging(true); }}
        onDragOver={(event) => event.preventDefault()}
        onDragLeave={() => setDragging(false)}
        onDrop={drop}
      >
        {uploading ? "Uploading and extracting…" : "Drop a PDF, Word file, Markdown or text here"}
        <div style={{ marginTop: 10 }}>
          <label className="btn compact" style={{ display: "inline-block" }}>
            Choose a file
            <input hidden type="file" onChange={uploadFromInput} accept=".md,.txt,.pdf,.docx" />
          </label>
        </div>
      </div>
    </>
  );
}

frontend/components/ResearchQueuePanel.t:
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { researchQueueAggregate, researchSupportLabel } from "@/lib/researchQueue";
import type { ResearchRun } from "@/lib/types";
import styles from "@/components/workspace/MatterWork.module.css";

type SavedQuestion = { id: string; text: string };

type ResearchQueuePanelProps = {
  items: ResearchRun[];
  mode?: "controls" | "summary";
  busy?: boolean;
  enteredQuestion?: string;
  savedQuestions?: SavedQuestion[];
  selectedQuestion?: string;
  packetHref?: (path: string) => string;
  onEnteredQuestion?: (value: string) => void;
  onMove?: (runId: string, direction: -1 | 1) => Promise<void>;
  onResume?: () => Promise<void>;
  onStop?: () => Promise<void>;
  onRetry?: (runId: string) => Promise<void>;
  onRun?: () => Promise<void>;
  onContinueFromPartial?: (item: ResearchRun) => void;
  onUpdateDraftFromSavedResearch?: () => void;
  onSelectedQuestion?: (value: string) => void;
  showDraftSnapshotNotice?: boolean;
};

export default function ResearchQueuePanel({
  items,
  mode = "controls",
  busy = false,
  enteredQuestion = "",
  savedQuestions = [],
  selectedQuestion = "",
  packetHref = (path) => `?file=${encodeURIComponent(path)}`,
  onEnteredQuestion,
  onMove,
  onResume,
  onStop,
  onRetry,
  onRun,
  onContinueFromPartial,
  onUpdateDraftFromSavedResearch,
  onSelectedQuestion,
  showDraftSnapshotNotice = false,
}: ResearchQueuePanelProps) {
  const pending = items.filter((item) => item.state === "queued");
  const interrupted = items.some((item) => item.state === "interrupted");
  const active = items.some((item) => item.state === "queued" || item.state === "running");
  const canControl = mode === "controls";
  const aggregate = researchQueueAggregate(items);
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!items.some((item) => item.state === "running")) return;
    const timer = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(timer);
  }, [items]);

  return <section className={`agent-note ${styles.researchQueue}`} aria-label="Research queue">
    <div className={`field-label ${styles.panelLabel}`}>Research queue</div>
    <p className={`setting-help ${styles.queueSummary}`} role="status">
      {aggregate.runCount} {aggregate.runCount === 1 ? "run" : "runs"} · {aggregate.activeCount} active · {aggregate.savedPacketCount} saved {aggregate.savedPacketCount === 1 ? "packet" : "packets"} · {aggregate.supportCount} saved support {aggregate.supportCount === 1 ? "source" : "sources"}
    </p>
    {showDraftSnapshotNotice ? <div className={`matter-lifecycle-action ${styles.snapshotNotice}`}>
      <span>This draft is a saved snapshot</span>
      <p>New research does not change this draft automatically.</p>
      <button className="btn quiet compact" disabled={busy || !onUpdateDraftFromSavedResearch || aggregate.savedPacketCount === 0} onClick={onUpdateDraftFromSavedResearch} type="button">Update draft from saved research</button>
    </div> : null}
    {canControl ? <div className={`btn-row ${styles.queueControls}`}>
      <select className="select-input" onChange={(event) => onSelectedQuestion?.(event.target.value)} value={selectedQuestion}>
        <option value="">Select a saved question</option>
        {savedQuestions.map((item) => <option key={item.id} value={item.text}>{item.text}</option>)}
      </select>
      <input className="text-input" onChange={(event) => onEnteredQuestion?.(event.target.value)} placeholder="Or enter a research question" value={enteredQuestion} />
      <button className="btn agent compact" disabled={busy || !onRun} onClick={() => void onRun?.()}>Run research</button>
      {interrupted ? <button className="btn compact" disabled={busy || !onResume} onClick={() => void onResume?.()}>Resume research</button> : null}
      {active ? <button className="btn quiet compact" disabled={busy || !onStop} onClick={() => void onStop?.()}>Stop research</button> : null}
    </div> : null}
    <div className={styles.queueItems}>
      {items.map((item) => {
        const packetPath = item.results?.[0]?.path;
        const partial = item.state === "completed" && item.status.startsWith("Partial");
        return <div className={`setting-help ${styles.queueItem}`} key={item.run_id}>
          <span className={styles.queueItemTitle}><strong className={styles.queueState} data-state={partial ? "partial" : item.state}>{researchQueueStateWord(item)}</strong> <span className={styles.queueMetadata}>· order {item.queue_order ?? item.priority ?? "—"} · {item.run_id}</span> · {item.question ?? item.questions?.[0] ?? "Research question"}</span>
          <span className={styles.queueSupport}>Support: {researchSupportLabel(item)}</span>
          {item.state === "running" ? <span className={styles.queueNotice}>{researchElapsed(item, now)} elapsed{packetPath ? " · saved packet available" : ""} · You can continue elsewhere while research runs.</span> : null}
          {partial ? <span className={styles.queueNotice}>Partial research is saved. You can use the packet to continue drafting.</span> : null}
          {canControl && item.state === "queued" ? <>
            <button className="btn compact" disabled={busy || !onMove || pending[0]?.run_id === item.run_id} onClick={() => void onMove?.(item.run_id, -1)}>Up</button>
            <button className="btn compact" disabled={busy || !onMove || pending.at(-1)?.run_id === item.run_id} onClick={() => void onMove?.(item.run_id, 1)}>Down</button>
          </> : null}
          {packetPath ? <Link href={packetHref(packetPath)}>Open packet</Link> : null}
          {item.state === "failed" ? <button className="btn quiet compact" disabled={busy || !onRetry} onClick={() => void onRetry?.(item.run_id)} type="button">Retry</button> : null}
          {partial && onContinueFromPartial ? <button className="btn quiet compact" onClick={() => onContinueFromPartial(item)} type="button">Continue from saved research</button> : null}
        </div>;
      })}
    </div>
  </section>;
}

function researchElapsed(item: ResearchRun, now: number): string {
  const started = Date.parse(item.started_at || item.created_at || "");
  const seconds = Number.isFinite(started) ? Math.max(0, Math.floor((now - started) / 1000)) : 0;
  const minutes = Math.floor(seconds / 60);
  return minutes ? `${minutes}m ${seconds % 60}s` : `${seconds}s`;
}

function researchQueueStateWord(item: ResearchRun): string {
  if (item.state === "completed") return item.status.startsWith("Partial") ? "Partial" : "Complete";
  return { queued: "Queued", running: "Running", failed: "Failed", interrupted: "Stopped" }[item.state];
}

