import SkillCommandMenu from "@/components/SkillCommandMenu";
import LinkifiedText from "@/components/LinkifiedText";
import UploadIntentCard from "@/components/UploadIntentCard";
import { getDailyConversation, getDailyConversations, getSkills, sendChat, uploadWorkspaceDocuments } from "@/lib/api";
import { formatLongDate } from "@/lib/design";
import { skillBuilderGoal } from "@/lib/skills";
import type { AttachmentReference, CardAction, ChatHistoryMessage, DailyConversationSummary, SkillDefinition } from "@/lib/types";

const SUGGESTIONS = [
  "What needs my attention today?",
  "Summarize my active matters.",
  "Which decisions need review?",
];

function localDay(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function dayLabel(day: string, today: string): string {
  if (day === today) return `Today — ${formatLongDate(day)}`;
  return formatLongDate(day);
}

function savedReplyLabel(createdAt: string): string {
  if (!createdAt) return "Saved reply";
  const parsed = new Date(createdAt);
  if (Number.isNaN(parsed.getTime())) return "Saved reply";
  return `Saved reply · ${parsed.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`;
}

type Props = {
  onRefresh?: () => void | Promise<void>;
};

export default function TodayChat({ onRefresh }: Props) {
  const router = useRouter();
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const today = useMemo(localDay, []);
  const [days, setDays] = useState<DailyConversationSummary[]>([]);
  const [selectedDay, setSelectedDay] = useState(today);
  const [messages, setMessages] = useState<ChatHistoryMessage[]>([]);
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [error, setError] = useState("");
  const [attachments, setAttachments] = useState<AttachmentReference[]>([]);
  const [uploading, setUploading] = useState(false);
  const [skills, setSkills] = useState<SkillDefinition[]>([]);
  const isToday = selectedDay === today;

  useEffect(() => { void getSkills().then(({ skills: saved }) => setSkills(saved)).catch(() => setSkills([])); }, []);

  const loadDays = useCallback(async () => {
    const result = await getDailyConversations();
    setDays(result.conversations);
    return result.conversations;
  }, []);

  const loadConversation = useCallback(async (day: string, knownDays: DailyConversationSummary[]) => {
    setSelectedDay(day);
    setHistoryOpen(day !== today);
    setInput("");
    setError("");
    if (!knownDays.some((item) => item.day === day)) {
      setMessages([]);
      return;
    }
    const conversation = await getDailyConversation(day);
    setMessages(conversation.messages);
  }, [today]);

  useEffect(() => {
    let active = true;
    void (async () => {
      try {
        const availableDays = await loadDays();
        if (active) await loadConversation(today, availableDays);
      } catch (caught) {
        if (active) setError(caught instanceof Error ? caught.message : "Could not load saved daily chats.");
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [loadConversation, loadDays, today]);

  async function submit(text: string, cardAction?: CardAction, actionAttachments: AttachmentReference[] = attachments) {
    const message = text.trim();
    if ((!message && !cardAction && !actionAttachments.length) || busy || !isToday) return;
    const builderGoal = !cardAction ? skillBuilderGoal(text) : null;
    if (builderGoal) {
      router.push(`/skills?goal=${encodeURIComponent(builderGoal)}`);
      return;
    }
    const visibleText = message || cardActionText(cardAction) || `Attached ${actionAttachments.map((item) => item.name).join(", ")}`;
    const previousMessages = messages;
    setHistoryOpen(true);
    setMessages((current) => [
      ...current,
      { message_id: `pending-${Date.now()}`, role: "user", content: visibleText, created_at: "", trace: [], attachments: actionAttachments },
    ]);
    setInput("");
    setAttachments([]);
    setError("");
    setBusy(true);
    try {
      await sendChat({ message, agent_id: "counsel-copilot", workspace_day: today, card_action: cardAction, attachments: actionAttachments });
      const [conversation] = await Promise.all([
        getDailyConversation(today),
        loadDays(),
        onRefresh?.(),
      ]);
      setMessages(conversation.messages);
    } catch (caught) {
      setMessages(previousMessages);
      if (message) setInput(message);
      if (actionAttachments.length) setAttachments(actionAttachments);
      setError(caught instanceof Error ? caught.message : "The workspace chat failed.");
    } finally {
      setBusy(false);
    }
  }

  async function addFiles(files: File[]) {
    setUploading(true);
    setError("");
    try {
      const result = await uploadWorkspaceDocuments(files);
      setAttachments(result.attachments);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not upload the selected files.");
    } finally { setUploading(false); }
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void submit(input);
    }
  }

  return (
    <section className="card today-chat" aria-labelledby="today-chat-title">
      <div className="today-chat-head">
        <div>
          <div className="section-heading" id="today-chat-title">Ask about your work</div>
          <p>Themis.ai can search the workspace, compare matters, and take actions that you request.</p>
        </div>
        <span className="agent-label"><span className="agent-mark" />Themis.ai</span>
      </div>

      <div className="today-chat-day-row">
        <label htmlFor="today-chat-day">Conversation</label>
        <select
          id="today-chat-day"
          value={selectedDay}
          disabled={busy || loading}
          onChange={(event) => void loadConversation(event.target.value, days)}
        >
          <option value={today}>{dayLabel(today, today)}</option>
          {days.filter((item) => item.day !== today).map((item) => (
            <option key={item.day} value={item.day}>{dayLabel(item.day, today)}</option>
          ))}
        </select>
        {!isToday ? <span>Previous days are read-only.</span> : <span>Saved to today&apos;s Markdown file.</span>}
      </div>

      {error ? <p className="error today-chat-status">{error}</p> : null}
      {loading ? <p className="today-chat-status">Loading today&apos;s conversation…</p> : null}
      {messages.length ? (
        <details className="today-chat-history" open={historyOpen} onToggle={(event) => setHistoryOpen(event.currentTarget.open)}>
          <summary>Saved conversation · {messages.length} messages</summary>
          <p className="today-chat-history-note">Saved replies reflect the workspace when written. The attention list above is current.</p>
          <div className="today-chat-thread" aria-live="polite">
            {messages.map((message, index) => message.role === "user" ? (
              <div className="bubble-you" key={message.message_id ?? index}><LinkifiedText text={message.content} /></div>
            ) : (
              <div className="bubble-agent" key={message.message_id ?? index}>
                <div className="today-chat-saved-label">{savedReplyLabel(message.created_at)}</div>
                {message.applied_skills?.map((skill) => <div className="applied-skill-label" key={skill.skill_id}>Applied skill: {skill.name}</div>)}
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
                {message.trace?.length ? (
                  <div className="trace-list" style={{ marginTop: 10 }}>
                    {message.trace.map((item, traceIndex) => (
                      <div className="trace-item" key={traceIndex}>
                        <span>{item.status === "success" ? "✓" : "!"}</span>
                        <span><LinkifiedText text={item.summary} /></span>
                      </div>
                    ))}
                  </div>
                ) : null}
                <ChatCards cards={message.cards} disabled={busy} onAction={(action, answerText) => submit(answerText ?? "", action, [])} />
              </div>
            ))}
            {busy ? <div className="agent-label"><span className="agent-mark" />Working…</div> : null}
          </div>
        </details>
      ) : null}

      {isToday ? (
        <>
          <UploadIntentCard attachments={attachments} busy={busy} onClear={() => setAttachments([])} onSend={(intent) => submit(intent, undefined, attachments)} />
          <div className="today-chat-suggestions">
            {SUGGESTIONS.map((suggestion) => (
              <button className="suggestion" disabled={busy || loading} key={suggestion} onClick={() => void submit(suggestion)}>
                {suggestion}
              </button>
            ))}
          </div>
          <div className="composer-field">
            <AttachmentPicker disabled={busy || loading || uploading} onSelect={addFiles} />
            <textarea
              ref={inputRef}
              aria-label="Ask Themis.ai about your work"
              disabled={busy || loading}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Ask about your matters, decisions, deadlines, or what to work on next…"
              rows={1}
              value={input}
            />
            <button className="btn primary compact" disabled={busy || loading || !input.trim()} onClick={() => void submit(input)}>
              {uploading ? "Uploading…" : "Send"}
            </button>
          </div>
          <SkillCommandMenu input={input} skills={skills} onSelect={(skill) => { setInput(`/${skill.skill_id} `); requestAnimationFrame(() => inputRef.current?.focus()); }} />
          <div className="composer-note"><Link className="build-skill-link" href="/skills">Build a skill</Link></div>
        </>
      ) : null}
    </section>
  );
}

function cardActionText(action?: CardAction): string {
  if (!action) return "";
  if (action.action === "save_draft") return "Save this Watch as a draft";
  if (action.action === "scan_now") return "Scan this Watch now without starting its schedule";
  if (action.action === "scan_again") return "Scan this Watch again";
  if (action.action === "change_something") return "Change something in this Watch";
  if (action.action === "start_watch") return "Start this Watch and activate its schedule";
  if (action.action === "skip") return "Skip";
  if (action.action === "stop") return "No more questions";
  return action.values?.join(", ") ?? action.action;
}

frontend/components/DocumentReview.tsx:
"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import CommentRail from "@/components/CommentRail";
import type { ReviewDisplayMode } from "@/components/RevisionPlugin";
import { displayReviewAuthor, GENERATED_REVIEW_AUTHOR, REVIEW_AUTHOR_PALETTE } from "@/lib/reviewAuthor";
import type { DocumentReview as ReviewState, DocumentReviewAction, ReviewAuthor } from "@/lib/types";

type SelectionContext = { quote: string; anchorStart?: number; anchorEnd?: number; returnFocus: HTMLElement | null; rect: DOMRect | null };

export default function DocumentReview({ review, author, lawyerAuthor, lawyerAuthorId, busy, readOnly, onAuthorChange, onAction, children }: {
  review: ReviewState; author: ReviewAuthor; lawyerAuthor: string; lawyerAuthorId: string; busy: boolean; readOnly: boolean; onAuthorChange: (name: string) => void; onAction: (action: DocumentReviewAction) => Promise<void>;
  children: (props: { mode: ReviewDisplayMode; reviewers: Set<string>; onAddComment: (context: SelectionContext) => void; onOpenThread: (threadId: string, returnFocus: HTMLElement | null) => void; onSelectionContext: (context: SelectionContext) => void }) => React.ReactNode;
}) {
  const [mode, setMode] = useState<ReviewDisplayMode>("current");
  const [reviewers, setReviewers] = useState<Set<string>>(new Set());
  const [selection, setSelection] = useState<SelectionContext | null>(null);
  const [commentQuote, setCommentQuote] = useState("");
  const [comment, setComment] = useState("");
  const [openThread, setOpenThread] = useState<string | null>(null);
  const [customOpen, setCustomOpen] = useState(false);
  const [customName, setCustomName] = useState("");
  const [commentsOpen, setCommentsOpen] = useState(false);
  const [reviewingChanges, setReviewingChanges] = useState(false);
  const returnFocus = useRef<HTMLElement | null>(null);
  const reviewButton = useRef<HTMLButtonElement | null>(null);
  const knownChanges = useRef(new Set(review.changes.map((item) => item.change_id)));
  const visibleChanges = useMemo(() => review.changes.filter((item) => reviewers.size === 0 || reviewers.has(item.author_id)), [review.changes, reviewers]);
  const authorOptions = [...new Set([lawyerAuthor.trim(), GENERATED_REVIEW_AUTHOR, ...review.authors.map((item) => displayReviewAuthor(item.name, item.author_id))])].filter(Boolean);
  const selectedAuthor = displayReviewAuthor(author.name, author.author_id);
  const closePopover = useCallback(() => { setCommentQuote(""); setComment(""); setOpenThread(null); const target = returnFocus.current; returnFocus.current = null; requestAnimationFrame(() => target?.focus()); }, []);
  const popupStyle = selection?.rect ? { position: "fixed" as const, left: Math.min(selection.rect.left, window.innerWidth - 450), top: Math.min(selection.rect.bottom + 8, window.innerHeight - 260) } : undefined;
  function decide(action: "accept_change" | "reject_change", changeId: string, next: boolean) { void onAction({ action, change_id: changeId }).then(() => { if (!next) return; const index = visibleChanges.findIndex((item) => item.change_id === changeId); const nextId = visibleChanges[index + 1]?.change_id; if (nextId) requestAnimationFrame(() => document.querySelector<HTMLElement>(`[data-review-change="${nextId}"]`)?.focus()); }); }
  function closeReview() { setReviewingChanges(false); requestAnimationFrame(() => reviewButton.current?.focus()); }
  function openComposer(context: SelectionContext) { const exact = context.anchorStart !== undefined ? context : selection?.quote === context.quote ? { ...context, anchorStart: selection.anchorStart, anchorEnd: selection.anchorEnd } : context; setSelection(exact); returnFocus.current = exact.returnFocus; setCommentQuote(exact.quote); setOpenThread(null); }
  function openExisting(threadId: string, focus: HTMLElement | null) { returnFocus.current = focus; setCommentsOpen(true); setOpenThread(threadId); setCommentQuote(""); }
  const contextualThread = review.comments.find((item) => item.thread_id === openThread);
  const openCommentCount = review.comments.filter((item) => !item.resolved).length;

  useEffect(() => {
    const current = new Set(review.changes.map((item) => item.change_id));
    if (review.changes.some((item) => !knownChanges.current.has(item.change_id))) setMode("markup");
    knownChanges.current = current;
  }, [review.changes]);

  useEffect(() => {
    if (visibleChanges.length === 0) setReviewingChanges(false);
  }, [visibleChanges.length]);

  useEffect(() => {
    if (reviewingChanges) requestAnimationFrame(() => document.querySelector<HTMLElement>("[data-review-change]")?.focus());
  }, [reviewingChanges]);

  return <div className={`review-workspace ${commentsOpen || reviewingChanges ? "" : "comments-hidden"} ${reviewingChanges ? "changes-open" : ""}`}>
    <div className="review-main">
      <div className="review-toolbar" role="toolbar" aria-label="Document review">
        <div className="review-modes">{([['markup', 'All Markup'], ['current', 'No Markup'], ['original', 'Original']] as const).map(([value, label]) => <button className={mode === value ? "active" : ""} key={value} onClick={() => setMode(value)} type="button">{label}</button>)}</div>
        <div className="review-toolbar-actions">
          <button
            aria-pressed={review.tracking}
            className={`btn tiny redline-toggle ${review.tracking ? "active" : ""}`}
            disabled={busy || readOnly}
            onClick={() => {
              if (!review.tracking) setMode("markup");
              void onAction({ action: "set_tracking", enabled: !review.tracking });
            }}
            title={review.tracking ? "Stop recording new edits as redlines." : "Record new edits as redlines."}
            type="button"
          >Redline {review.tracking ? "on" : "off"}</button>
          {visibleChanges.length ? <button
            aria-expanded={reviewingChanges}
            className={`btn tiny ${reviewingChanges ? "quiet" : "review"}`}
            ref={reviewButton}
            onClick={() => {
              setMode("markup");
              if (reviewingChanges) closeReview();
              else setReviewingChanges(true);
            }}
            type="button"
          >{reviewingChanges ? "Continue editing" : `Review ${visibleChanges.length} ${visibleChanges.length === 1 ? "change" : "changes"}`}</button> : null}
          <div className="review-toolbar-secondary">
          {review.authors.length ? <details className="reviewer-menu"><summary>Reviewers ({review.authors.length})</summary><div className="reviewer-filters" aria-label="Reviewer filters">{review.authors.map((item) => { const count = review.changes.filter((change) => change.author_id === item.author_id).length; const selected = reviewers.size === 0 || reviewers.has(item.author_id); const displayName = displayReviewAuthor(item.name, item.author_id); return <label key={item.author_id}><input checked={selected} onChange={() => setReviewers((current) => { const next = new Set(current.size === 0 ? review.authors.map((entry) => entry.author_id) : current); if (next.has(item.author_id)) next.delete(item.author_id); else next.add(item.author_id); return next.size === review.authors.length ? new Set() : next; })} type="checkbox"/><span className="author-swatch" style={{ background: item.color }}/>{displayName} ({count})<select aria-label={`Color for ${displayName}`} onChange={(event) => void onAction({ action: "set_author_color", author_id: item.author_id, color: event.target.value })} value={item.color}>{REVIEW_AUTHOR_PALETTE.map((color) => <option key={color} value={color}>{color}</option>)}</select></label>; })}</div></details> : null}
          <button aria-pressed={commentsOpen} className="btn quiet tiny" onClick={() => setCommentsOpen((current) => !current)} type="button">Comments {commentsOpen ? "on" : "off"} ({openCommentCount})</button>
          <label>Author <select aria-label="Active review author" className="select-input" onChange={(event) => { if (event.target.value === "__custom") { setCustomName(""); setCustomOpen(true); } else onAuthorChange(event.target.value); }} value={selectedAuthor}>{authorOptions.map((name) => <option key={name}>{name}</option>)}{!authorOptions.includes(selectedAuthor) ? <option>{selectedAuthor}</option> : null}<option value="__custom">Custom name…</option></select></label>
          {customOpen ? <div className="author-popover"><input autoFocus aria-label="Custom author name" className="text-input" onChange={(event) => setCustomName(event.target.value)} onKeyDown={(event) => { if (event.key === "Escape") setCustomOpen(false); }} value={customName}/><button className="btn primary tiny" disabled={!customName.trim()} onClick={() => { onAuthorChange(customName); setCustomOpen(false); }} type="button">Use author</button></div> : null}
          </div>
        </div>
      </div>
      {children({ mode, reviewers, onAddComment: openComposer, onOpenThread: openExisting, onSelectionContext: setSelection })}
      {(commentQuote || contextualThread) ? <div className="comment-popover" onKeyDown={(event) => { if (event.key === "Escape") closePopover(); }} role="dialog" aria-label={commentQuote ? "Add comment" : "Comment thread"} style={popupStyle}>{commentQuote ? <><strong>Comment on “{commentQuote}”</strong>{selection?.anchorStart === undefined || selection.anchorEnd === undefined ? <p className="comment-note">Select text within one paragraph or list item to add a comment.</p> : <textarea autoFocus className="text-input" onChange={(event) => setComment(event.target.value)} value={comment}/>}<div className="btn-row"><button className="btn" onClick={closePopover} type="button">Cancel</button><button className="btn primary" disabled={!comment.trim() || busy || selection?.anchorStart === undefined || selection.anchorEnd === undefined} onClick={async () => { await onAction({ action: "add_comment", quote: commentQuote, body: comment.trim(), anchor_start: selection?.anchorStart, anchor_end: selection?.anchorEnd }); setCommentsOpen(true); closePopover(); }} type="button">Add comment</button></div></> : contextualThread ? <><blockquote>{contextualThread.quote}</blockquote>{contextualThread.entries.map((entry) => <p key={entry.comment_id}><strong>{displayReviewAuthor(entry.author_name, entry.author_id)}</strong><br/>{entry.body}</p>)}<button className="btn tiny" onClick={closePopover} type="button">Close</button></> : null}</div> : null}
    </div>
    {reviewingChanges && visibleChanges.length ? <section aria-label="Tracked changes" className="review-list" onKeyDown={(event) => { if (event.key === "Escape") closeReview(); }}><div className="review-list-head"><div><h3>Review tracked changes</h3><p>{visibleChanges.length} {visibleChanges.length === 1 ? "change" : "changes"} remaining</p></div><button className="btn quiet tiny" onClick={closeReview} type="button">Continue editing</button></div>{visibleChanges.map((change) => <article className="review-card" data-review-change={change.change_id} key={change.change_id} tabIndex={-1}><div><strong style={{ color: change.author_color }}>{displayReviewAuthor(change.author_name, change.author_id)}</strong><div className="review-change-text">{change.old_text ? <del style={{ color: change.author_color }}>{change.old_text}</del> : null}{change.new_text ? <ins style={{ color: change.author_color }}>{change.new_text}</ins> : null}</div></div><div className="btn-row"><button className="btn tiny" disabled={busy} onClick={() => decide("reject_change", change.change_id, false)} type="button">Reject</button><button className="btn tiny" disabled={busy} onClick={() => decide("reject_change", change.change_id, true)} type="button">Reject and next</button><button className="btn tiny" disabled={busy} onClick={() => decide("accept_change", change.change_id, false)} type="button">Accept</button><button className="btn primary tiny" disabled={busy} onClick={() => decide("accept_change", change.change_id, true)} type="button">Accept and next</button></div></article>)}</section> : commentsOpen ? <CommentRail busy={busy} comments={review.comments} lawyerAuthorId={lawyerAuthorId} onAction={onAction} onCollapse={() => setCommentsOpen(false)} onOpenThread={openExisting}/> : null}
  </div>;
}

frontend/components/BriefingItemList.tsx:
"use client";

import Link from "next/link";
import { formatShortDate } from "@/lib/design";
import type { BriefingGroup, BriefingItem } from "@/lib/watchTypes";

const IMPACT_WORD: Record<string, string> = { low: "Low impact", medium: "Medium impact", high: "High impact" };

function groupNames(item: BriefingItem, group: BriefingGroup, watchNames: Record<string, string>): string[] {
  if (group === "watch") return [watchNames[item.watch_id] ?? item.watch_id];
  if (group === "topic") return item.topics.length ? item.topics : ["No topic"];
  if (group === "source") return item.sources.length ? item.sources.map((source) => source.publisher || source.title) : ["No source"];
  if (group === "jurisdiction") return item.jurisdictions.length ? item.jurisdictions : ["No jurisdiction"];
  if (group === "date") return [formatShortDate(item.published_at || item.created_at)];
  if (group === "product") return item.company_connection?.products.length ? item.company_connection.products : ["No connected product"];
  if (group === "affected_decision") return item.company_connection?.decisions.length ? item.company_connection.decisions : ["No affected decision"];
  return [""];
}

/**
 * One row per development. Ochre is reserved for the items that actually need
 * the lawyer; unread is emphasis, not attention.
 */
export default function BriefingItemList({ items, group, queryString, watchNames }: {
  items: BriefingItem[];
  group: BriefingGroup;
  queryString: string;
  watchNames: Record<string, string>;
}) {
  if (!items.length) {
    return <div className="empty-state">
      No development matches this view. Widen the search, clear the filters, or check your Watches.
    </div>;
  }
  const grouped = new Map<string, BriefingItem[]>();
  for (const item of items) for (const name of groupNames(item, group, watchNames)) grouped.set(name, [...(grouped.get(name) ?? []), item]);

  return <div>{[...grouped].map(([name, entries]) => <section className="briefing-group" key={name || "all"} aria-label={name || "Developments"}>
    {name ? <div className="briefing-group-head">
      <h2>{name}</h2><span>{entries.length === 1 ? "1 development" : `${entries.length} developments`}</span>
    </div> : null}
    <div className="card">{entries.map((item) => {
      const needsReview = item.attention_state === "required" && Boolean(item.review_packet_id);
      const watch = watchNames[item.watch_id] ?? item.watch_id;
      return <Link
        className={`briefing-item ${item.read ? "read" : "unread"}${needsReview ? " review" : ""}`}
        href={`/briefing/${encodeURIComponent(item.item_id)}${queryString ? `?${queryString}` : ""}`}
        key={item.item_id}
      >
        <div className="briefing-item-meta">
          {formatShortDate(item.published_at || item.created_at)} · {watch}
          {item.jurisdictions.length ? ` · ${item.jurisdictions[0]}` : ""}
        </div>
        <div className="briefing-item-title">{item.title}</div>
        <p className="briefing-item-summary">{item.summary}</p>
        <div className="briefing-item-foot">
          {needsReview ? <span className="state-label state-attention">Needs your review</span> : null}
          {item.read ? <span className="state-label state-quiet">Read</span> : <span className="state-label state-plain">Unread</span>}
          {item.saved ? <span className="state-label state-quiet">Saved</span> : null}
          {item.potential_impact ? <span className="state-label state-quiet">{IMPACT_WORD[item.potential_impact] ?? item.potential_impact}</span> : null}
          {item.legal_status ? <span className="briefing-item-status">{item.legal_status}</span> : null}
        </div>
      </Link>;
    })}</div>
  </section>)}</div>;
}

frontend/components/CompanyInterview.tsx:
"use client";

import { KeyboardEvent, useCallback, useEffect, useRef, useState } from "react";
import ConfirmationDialog from "@/components/ConfirmationDialog";
import { advanceCompanyInterview, getCompanyInterview, saveCompanyProfile } from "@/lib/api";
import type {
  CompanyInterview as Interview,
  CompanyInterviewQuestion,
  CompanyInterviewTurn,
  CompanyProfile,
} from "@/lib/types";

export type CompanyProfileField = Exclude<keyof CompanyProfile, "source_id" | "version">;

export function normalizeCompanyName(name: string): string {
  return name.trim().replace(/\s+/g, " ").toLowerCase();
}

export function companyReplacementMessage(savedName: string, draftName: string): string | null {
  const saved = savedName.trim().replace(/\s+/g, " ");
  const draft = draftName.trim().replace(/\s+/g, " ");
  if (!saved || !draft || normalizeCompanyName(saved) === normalizeCompanyName(draft)) return null;
  return `Replace the company profile for ${saved} with ${draft}?`;
}

export const COMPANY_PROFILE_FIELDS: { key: CompanyProfileField; label: string; help: string }[] = [
  { key: "company_name", label: "Company name", help: "The name used in the company profile." },
  { key: "website_url", label: "Website", help: "The company website used as background context." },
  { key: "summary", label: "Company summary", help: "A short description that gives agents the right company context." },
  { key: "business_model", label: "Business model", help: "How the company makes money and who its customers are." },
  { key: "products_services", label: "Products and services", help: "The products, services, and main product areas." },
  { key: "jurisdictions", label: "Jurisdictions", help: "The countries, states, or regions where the company operates." },
  { key: "regulatory_context", label: "Regulatory context", help: "The main licenses, regulators, and legal frameworks." },
  { key: "data_practices", label: "Data practices", help: "The main types of data and how the company uses them." },
  { key: "risk_posture", label: "Risk posture", help: "The company’s practical approach to legal and business risk." },
];

type Exchange = { question: CompanyInterviewQuestion; answer: string; reply: string; websiteUsed: boolean; warning: string };
type Props = { profile: CompanyProfile; onSaved: (profile: CompanyProfile) => void };
type SaveState = "clean" | "dirty" | "saved";
type CompanyProfileWithSavedAt = CompanyProfile & { saved_at?: string };

function hasProfileContent(profile: CompanyProfile): boolean {
  return Boolean(profile.version || COMPANY_PROFILE_FIELDS.some((field) => profile[field.key].trim()));
}

function emptyReplacementDraft(profile: CompanyProfile): CompanyProfile {
  return {
    ...Object.fromEntries(COMPANY_PROFILE_FIELDS.map((field) => [field.key, ""])),
    source_id: profile.source_id,
    version: profile.version,
  } as CompanyProfile;
}

function savedAt(profile: CompanyProfile): string {
  const value = (profile as CompanyProfileWithSavedAt).saved_at;
  if (!value) return "Save time unavailable";
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleString();
}

export default function CompanyInterview({ profile, onSaved }: Props) {
  const existingProfile = hasProfileContent(profile);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const websiteRef = useRef<HTMLInputElement>(null);
  const [interview, setInterview] = useState<Interview | null>(null);
  const [question, setQuestion] = useState<CompanyInterviewQuestion | null>(null);
  const [history, setHistory] = useState<CompanyInterviewTurn[]>([]);
  const [exchanges, setExchanges] = useState<Exchange[]>([]);
  const [input, setInput] = useState("");
  const [websiteInput, setWebsiteInput] = useState("");
  const [draft, setDraft] = useState<CompanyProfile>(profile);
  const [generatedDraft, setGeneratedDraft] = useState(!existingProfile);
  const [draftEditedByLawyer, setDraftEditedByLawyer] = useState(false);
  const [reviewing, setReviewing] = useState(existingProfile);
  const [warning, setWarning] = useState("");
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [saving, setSaving] = useState(false);
  const [saveState, setSaveState] = useState<SaveState>(existingProfile ? "clean" : "dirty");
  const [error, setError] = useState("");
  const [replacementConfirmation, setReplacementConfirmation] = useState<string | null>(null);
  const [discardConfirmation, setDiscardConfirmation] = useState(false);
  const [replacementInProgress, setReplacementInProgress] = useState(false);

  const loadInterview = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const next = await getCompanyInterview();
      setInterview(next);
      setQuestion(next.question);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not start the company interview.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void loadInterview(); }, [loadInterview]);

  useEffect(() => {
    if (!working) {
      setElapsedSeconds(0);
      return;
    }
    const startedAt = Date.now();
    const timer = window.setInterval(() => setElapsedSeconds(Math.floor((Date.now() - startedAt) / 1000)), 1000);
    return () => window.clearInterval(timer);
  }, [working]);

  async function advance(finish = false, leaveWebsiteBlank = false) {
    const websiteQuestion = question?.question_id === "website_url";
    const answer = websiteQuestion ? (leaveWebsiteBlank ? "Leave blank" : websiteInput.trim()) : input.trim();
    if (!question || working || (!finish && !answer)) return;
    setWorking(true);
    setError("");
    setWarning("");
    try {
      const result = await advanceCompanyInterview({
        message: finish ? "" : answer,
        history,
        current_profile: draft,
        question_id: question.question_id,
        finish,
        ...(!finish && websiteQuestion ? { website_url: leaveWebsiteBlank ? "" : websiteInput.trim() } : {}),
      });
      setDraft(result.draft);
      setGeneratedDraft(true);
      setDraftEditedByLawyer(false);
      setWarning(result.warning ?? "");
      if (!finish) {
        setExchanges((current) => [...current, {
          question,
          answer,
          reply: result.reply,
          websiteUsed: result.website_used,
          warning: result.warning ?? "",
        }]);
        setHistory((current) => [
          ...current,
          { role: "assistant", content: question.text },
          { role: "user", content: answer },
        ]);
      }
      setInput("");
      setWebsiteInput("");
      setQuestion(result.question ?? null);
      setReviewing(result.complete || finish);
      requestAnimationFrame(() => (websiteRef.current ?? inputRef.current)?.focus());
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Could not continue the company interview.");
    } finally {
      setWorking(false);
    }
  }

  function startAgain() {
    if (!interview) return;
    setQuestion(interview.question);
    setHistory([]);
    setExchanges([]);
    setInput("");
    setWebsiteInput("");
    setDraft(emptyReplacementDraft(profile));
    setGeneratedDraft(true);
    setDraftEditedByLawyer(false);
    setReviewing(false);
    setWarning("");
    setError("");
    setSaveState("dirty");
    setReplacementInProgress(existingProfile);
    requestAnimationFrame(() => (websiteRef.current ?? inputRef.current)?.focus());
  }

  function requestStartAgain() {
    if (saveState === "dirty") {
      setDiscardConfirmation(true);
      return;
    }
    startAgain();
  }

  async function persistDraft(replacementMessage: string | null) {
    if (saving || saveState !== "dirty") return;
    setSaving(true);
    setError("");
    try {
      const payload = replacementMessage
        ? ({ ...draft, replacement_confirmation: replacementMessage } as CompanyProfile)
        : draft;
      const nextProfile = await saveCompanyProfile(payload);
      setDraft(nextProfile);
      setSaveState("saved");
      setReplacementInProgress(false);
      onSaved(nextProfile);
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : "Could not save the company profile.";
      setError(message);
      throw new Error(message);
    } finally {
      setSaving(false);
    }
  }

  function saveDraft() {
    if (saving || saveState !== "dirty") return;
    const replacementMessage = companyReplacementMessage(profile.company_name, draft.company_name);
    if (replacementMessage) {
      setReplacementConfirmation(replacementMessage);
      return;
    }
    void persistDraft(null).catch(() => undefined);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void advance();
    }
  }

  if (loading) return <div className="company-interview-status">Starting the company interview…</div>;
  if (!interview) return (
    <div className="company-interview-status">
      <p className="error">{error || "The company interview is not available."}</p>
      <button className="btn compact" onClick={() => void loadInterview()} type="button">Try again</button>
    </div>
  );

  return (
    <section className="company-interview" aria-label="Company profile interview">
      <div className="company-interview-thread" aria-live="polite">
        {replacementInProgress && !reviewing ? <p className="company-interview-warning" role="status"><strong>Saved profile remains active.</strong> The replacement will not be used until you save it.</p> : null}
        {!reviewing ? <AssistantTurn>{interview.opening}</AssistantTurn> : null}
        {exchanges.map((exchange, index) => (
          <div className="company-interview-exchange" key={`${exchange.question.question_id}-${index}`}>
            <QuestionTurn question={exchange.question} />
            <div className="bubble-you">{exchange.answer}</div>
            <AssistantTurn>{exchange.reply}</AssistantTurn>
            {exchange.websiteUsed ? <p className="company-interview-warning" role="status"><strong>Website read</strong> · Public website content was used as untrusted background.</p> : null}
            {exchange.warning ? <p className="company-interview-warning" role="status"><strong>Note:</strong> {exchange.warning}</p> : null}
          </div>
        ))}
        {question && !reviewing ? <QuestionTurn question={question} /> : null}
        {working ? <AssistantTurn>{elapsedSeconds < 5 ? "Working…" : `Still working… ${elapsedSeconds} seconds elapsed.`}</AssistantTurn> : null}
        {reviewing ? (
          <ReviewCard
            draft={draft}
            draftEditedByLawyer={draftEditedByLawyer}
            generatedDraft={generatedDraft}
            error={error}
            saveState={saveState}
            saving={saving}
            warning={warning}
            onChange={(nextDraft) => {
              setDraft(nextDraft);
              setDraftEditedByLawyer(true);
              setSaveState("dirty");
            }}
            onSave={() => void saveDraft()}
            onStartAgain={requestStartAgain}
          />
        ) : error ? <div className="company-interview-error"><p className="error">{error}</p></div> : null}
      </div>

      {question && !reviewing ? (
        <div className="company-interview-composer">
          <label className="field-label" htmlFor={question.question_id === "website_url" ? "company-interview-website" : "company-interview-answer"}>
            {question.question_id === "website_url" ? "Public HTTPS website (optional)" : "Your answer"}
          </label>
          <div className="composer-field">
            {question.question_id === "website_url" ? (
              <input
                className="text-input"
                id="company-interview-website"
                onChange={(event) => setWebsiteInput(event.target.value)}
                placeholder="https://example.com"
                ref={websiteRef}
                type="url"
                value={websiteInput}
              />
            ) : (
              <textarea
                id="company-interview-answer"
                onChange={(event) => setInput(event.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Answer in your own words…"
                ref={inputRef}
                rows={3}
                value={input}
              />
            )}
            <button className="btn primary compact" disabled={question.question_id === "website_url" ? !websiteInput.trim() || working : !input.trim() || working} onClick={() => void advance()} type="button">Send</button>
          </div>
          <div className="company-interview-composer-foot">
            <span>{question.question_id === "website_url" ? "Only a public HTTPS address can be read. Its content is untrusted background." : "Enter sends. Shift+Enter adds a new line."}</span>
            {question.question_id === "website_url" ? <button className="btn tiny quiet" disabled={working} onClick={() => void advance(false, true)} type="button">Leave blank</button> : null}
            {exchanges.length ? <button className="btn tiny quiet" disabled={working} onClick={() => void advance(true)} type="button">Review draft now</button> : null}
          </div>
        </div>
      ) : null}
      {replacementConfirmation ? <ConfirmationDialog
        confirmLabel="Replace company profile"
        description={replacementConfirmation}
        onCancel={() => setReplacementConfirmation(null)}
        onConfirm={() => persistDraft(replacementConfirmation)}
        title="Replace company profile?"
      /> : null}
      {discardConfirmation ? <ConfirmationDialog
        confirmLabel="Discard draft and start replacement"
        description="Discard the unsaved company profile draft? The saved company profile stays active until you save its replacement."
        onCancel={() => setDiscardConfirmation(false)}
        onConfirm={() => { setDiscardConfirmation(false); startAgain(); }}
        title="Start replacement interview?"
      /> : null}
    </section>
  );
}

function AssistantTurn({ children }: { children: string }) {
  return <div className="assistant-message"><div className="agent-label">Themis.ai</div><div className="bubble-agent"><p>{children}</p></div></div>;
}

function QuestionTurn({ question }: { question: CompanyInterviewQuestion }) {
  return (
    <div className="assistant-message company-question">
      <div className="agent-label">Themis.ai</div>
      <div className="bubble-agent"><p>{question.text}</p></div>
      {question.reason ? <p className="company-question-reason">Why I ask: {question.reason}</p> : null}
    </div>
  );
}

function ReviewCard({ draft, draftEditedByLawyer, error, generatedDraft, saveState, saving, warning, onChange, onSave, onStartAgain }: {
  draft: CompanyProfile;
  draftEditedByLawyer: boolean;
  error: string;
  generatedDraft: boolean;
  saveState: SaveState;
  saving: boolean;
  warning: string;
  onChange: (profile: CompanyProfile) => void;
  onSave: () => void;
  onStartAgain: () => void;
}) {
  const unchanged = saveState !== "dirty";
  return (
    <section className={`company-review-card ${unchanged ? "saved" : ""}`} aria-label={saveState === "dirty" ? "Company profile draft" : "Saved company profile"}>
      <div className="agent-label">{saveState === "dirty"
        ? generatedDraft && !draftEditedByLawyer
          ? "Company profile draft · Themis.ai · Not yet reviewed by an attorney"
          : generatedDraft
            ? "Company profile draft · Unsaved lawyer edits to a Themis.ai draft"
            : "Company profile draft · Unsaved lawyer edits"
        : "Company profile · Saved"}</div>
      <h2>{draft.company_name || "Review the company profile"}</h2>
      <p className="company-review-state">
        {saveState === "clean"
          ? "Saved and in use. No unsaved changes."
          : saveState === "saved"
            ? "Saved and in use. No unsaved changes."
            : "Review and edit this profile. Nothing changes until you choose Save company profile."}
      </p>
      {draft.version ? (
        <p className="record-meta">Version {draft.version} · Saved {savedAt(draft)}</p>
      ) : null}
      <dl className="company-review-fields">
        {COMPANY_PROFILE_FIELDS.map((field) => (
          <div key={field.key}>
            <dt><label htmlFor={`company-draft-${field.key}`}>{field.label}</label></dt>
            <dd>{field.key === "company_name" || field.key === "website_url" ? (
              <input className="text-input" id={`company-draft-${field.key}`} onChange={(event) => onChange({ ...draft, [field.key]: event.target.value })} type={field.key === "website_url" ? "url" : "text"} value={draft[field.key]} />
            ) : (
              <textarea
                className="text-input"
                id={`company-draft-${field.key}`}
                onChange={(event) => onChange({ ...draft, [field.key]: event.target.value })}
                rows={field.key === "summary" || field.key === "regulatory_context" || field.key === "data_practices" ? 7 : 5}
                value={draft[field.key]}
              />
            )}</dd>
          </div>
        ))}
      </dl>
      {warning ? <p className="company-interview-warning" role="status"><strong>Note:</strong> {warning}</p> : null}
      {error ? <p className="error">{error}</p> : null}
      <div className="company-interview-actions">
        <button className="btn primary" disabled={saving || unchanged} onClick={onSave} type="button">
          {saving ? "Saving…" : unchanged ? "No unsaved changes" : "Save company profile"}
        </button>
        <button className="btn" disabled={saving} onClick={onStartAgain} type="button">Start replacement interview</button>
      </div>
    </section>
  );
}

