"use client";

import { FormEvent, useState } from "react";
import type { PriorWorkPanelProps } from "@/lib/workspaceTypes";
import styles from "./MatterExplore.module.css";

const titleCase = (value: string) => value.replaceAll("_", " ").replaceAll("-", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());

export default function PriorWorkPanel({ candidates, busy = false, onSearch, onInclude, onOpenArtifact }: PriorWorkPanelProps) {
  const [query, setQuery] = useState("");
  const [searched, setSearched] = useState(false);
  const [searching, setSearching] = useState(false);
  const [pendingPath, setPendingPath] = useState<string | null>(null);
  const [includedPaths, setIncludedPaths] = useState<Set<string>>(new Set());
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  async function search(event: FormEvent) {
    event.preventDefault();
    if (!query.trim()) return;
    setSearching(true); setError(""); setNotice("");
    try {
      await onSearch(query.trim());
      setSearched(true);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Prior work could not be searched. Your query is retained.");
    } finally { setSearching(false); }
  }

  async function include(path: string) {
    const candidate = candidates.find((item) => item.path === path);
    if (!candidate) return;
    setPendingPath(path); setError(""); setNotice("");
    try {
      await onInclude(candidate);
      setIncludedPaths((current) => new Set(current).add(`${path}:${candidate.revision}`));
      setNotice(`Included ${candidate.title} in the next inquiry context.`);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Prior work was not included. You can retry.");
    } finally { setPendingPath(null); }
  }

  return <section aria-labelledby="prior-work-title" className={`${styles.priorWorkPanel} reuse-panel`}>
    <div className="reuse-panel__head"><div><h2 id="prior-work-title">Similar prior work</h2><p>Search when it is useful. A result affects the next inquiry only after you include it.</p></div></div>
    <form className="reuse-search" onSubmit={(event) => void search(event)}>
      <label className="label" htmlFor="prior-work-query">What work should match?</label>
      <div className="reuse-search__row"><input className="text-input" id="prior-work-query" onChange={(event) => setQuery(event.target.value)} placeholder="Settlement structure, custody, or a key fact" value={query} /><button className="btn" disabled={busy || searching || !query.trim()} type="submit">{searching ? "Searching…" : "Search prior work"}</button></div>
    </form>
    {error ? <p className="error" role="alert">{error}</p> : null}
    {notice ? <p className="reuse-notice" role="status"><span className="state-label state-healthy">Included</span>{notice}</p> : null}
    {searched && candidates.length === 0 ? <p className="empty-state">No matching prior work was found.</p> : null}
    {candidates.length ? <div className="reuse-list" aria-live="polite">{candidates.map((candidate) => {
      const included = includedPaths.has(`${candidate.path}:${candidate.revision}`);
      return <article className="reuse-item" key={`${candidate.path}:${candidate.revision}`}>
        <div className="reuse-item__head"><div><h3>{candidate.title}</h3><p className="reuse-source">{titleCase(candidate.kind || "prior matter")} · {candidate.date || "Date not recorded"} · {candidate.status || "Status not recorded"}</p></div><span className={`state-label ${included ? "state-healthy" : "state-attention"}`}>{included ? "Included" : "Review first"}</span></div>
        <p className="reading reuse-reading">{candidate.relevance}</p>
        {candidate.snippet ? <blockquote className="reuse-snippet">{candidate.snippet}</blockquote> : null}
        <div className="reuse-differences"><strong>Important differences</strong><ul>{candidate.differences.length ? candidate.differences.map((difference) => <li key={difference}>{difference}</li>) : <li>No difference was supplied. Inspect the source before use.</li>}</ul></div>
        <details className="reuse-source-detail"><summary>Source details</summary><p>Matter: {candidate.matter_id || "Not recorded"}</p><p>File: <span className="mono">{candidate.path}</span></p><p>Version: <span className="mono">{candidate.revision || "Not recorded"}</span></p></details>
        <div className="btn-row"><button className="btn quiet" onClick={() => onOpenArtifact(candidate.path)} type="button">Open source</button><button className="btn primary" disabled={busy || pendingPath === candidate.path || included} onClick={() => void include(candidate.path)} type="button">{pendingPath === candidate.path ? "Including…" : included ? "Included" : "Include in next inquiry"}</button></div>
      </article>;
    })}</div> : null}
  </section>;
}

frontend/components/workspace/IssueNavig:
"use client";

import { useState } from "react";
import type { IssueNavigatorProps, IssueNode, IssueUpdate } from "@/lib/workspaceTypes";
import styles from "./MatterReview.module.css";

type IssueDraft = { changes: Omit<IssueUpdate, "expected_revision">; baseRevision: string };

function issueDepths(issues: IssueNode[]) {
  const byId = new Map(issues.map((issue) => [issue.issue_id, issue]));
  const depth = (issue: IssueNode, visited = new Set<string>()): number => {
    if (!issue.parent_issue_id || visited.has(issue.issue_id)) return 0;
    const parent = byId.get(issue.parent_issue_id);
    return parent ? 1 + depth(parent, new Set([...visited, issue.issue_id])) : 0;
  };
  return new Map(issues.map((issue) => [issue.issue_id, Math.min(depth(issue), 4)]));
}

function stateLabel(state: IssueNode["lawyer_state"]) {
  if (state === "explored") return "Explored";
  if (state === "set_aside") return "Set aside";
  return "Open";
}

function dispositionLabel(issue: IssueNode) {
  if (issue.disposition === "mitigation_in_progress") return "Mitigation in progress";
  if (issue.disposition === "resolved") return "Resolved";
  if (issue.disposition === "risk_accepted") return "Risk accepted";
  if (issue.disposition === "not_applicable") return "Not applicable";
  return issue.disposition === "unresolved" ? "Unresolved" : "No disposition recorded";
}

function dispositionClass(issue: IssueNode) {
  if (issue.disposition === "resolved" || issue.disposition === "not_applicable") return "state-healthy";
  if (issue.lawyer_state === "set_aside") return "state-attention";
  return issue.disposition === "mitigation_in_progress" ? "state-agent" : "state-attention";
}

export function compactIssueTitle(title: string, limit = 110) {
  const clean = title.replace(/\s+/g, " ").trim();
  if (clean.length <= limit) return clean;
  const boundary = clean.lastIndexOf(" ", limit - 1);
  return `${clean.slice(0, boundary > 0 ? boundary : limit).trimEnd()}…`;
}

export default function IssueNavigator({ issues, issuesRevision, selectedIssueId, onSelect, onIssueUpdate }: IssueNavigatorProps) {
  const [drafts, setDrafts] = useState<Record<string, IssueDraft>>({});
  const [savingIds, setSavingIds] = useState<string[]>([]);
  const [error, setError] = useState<Record<string, string>>({});
  const canEdit = Boolean(onIssueUpdate && issuesRevision);
  const depths = issueDepths(issues);

  const change = (issueId: string, next: Omit<IssueUpdate, "expected_revision">) => setDrafts((current) => {
    const draft = current[issueId] ?? { changes: {}, baseRevision: issuesRevision ?? "" };
    return { ...current, [issueId]: { ...draft, changes: { ...draft.changes, ...next } } };
  });
  const draftFor = (issue: IssueNode) => drafts[issue.issue_id];
  const field = (issue: IssueNode, key: Exclude<keyof IssueUpdate, "expected_revision">) => {
    const changes = draftFor(issue)?.changes;
    return changes && Object.prototype.hasOwnProperty.call(changes, key) ? changes[key] : issue[key as keyof IssueNode] ?? "";
  };

  async function save(issue: IssueNode) {
    if (!onIssueUpdate || !issuesRevision) return;
    const draft = drafts[issue.issue_id];
    if (!draft || !Object.keys(draft.changes).length) return;
    if (draft.baseRevision !== issuesRevision) {
      setError((current) => ({ ...current, [issue.issue_id]: "This issue changed after you began editing. Rebase your edits or use the latest saved issue before saving." }));
      return;
    }
    setSavingIds((current) => current.includes(issue.issue_id) ? current : [...current, issue.issue_id]);
    setError((current) => ({ ...current, [issue.issue_id]: "" }));
    try {
      await onIssueUpdate(issue.issue_id, { ...draft.changes, expected_revision: draft.baseRevision });
      setDrafts((current) => { const next = { ...current }; delete next[issue.issue_id]; return next; });
    } catch (cause) {
      setError((current) => ({ ...current, [issue.issue_id]: cause instanceof Error ? cause.message : "Issue change was not saved. Your edits are retained." }));
    } finally { setSavingIds((current) => current.filter((issueId) => issueId !== issue.issue_id)); }
  }

  return <section aria-label="Issue navigator" className={`${styles.card} ${styles.issueNav}`}>
    <div className={styles.between}>
      <h2 className={styles.sectionTitle}>All issues</h2>
      <span className="record-meta">{issues.length} {issues.length === 1 ? "issue" : "issues"}</span>
    </div>
    {!issues.length ? <p className={styles.muted}>No issues are saved yet.</p> : <div className={styles.issueList}>
      {issues.map((issue) => {
        const selected = issue.issue_id === selectedIssueId;
        const draft = draftFor(issue);
        const saving = savingIds.includes(issue.issue_id);
        const revisionChanged = Boolean(draft && draft.baseRevision !== issuesRevision);
        const title = String(field(issue, "title"));
        const shortTitle = compactIssueTitle(issue.title || "Untitled issue");
        const parent = field(issue, "parent_issue_id") as string | null;
        const state = field(issue, "lawyer_state") as IssueNode["lawyer_state"];
        return <article aria-current={selected ? "true" : undefined} className={`${styles.issueRow} ${selected ? styles.issueRowSelected : ""}`} key={issue.issue_id} style={{ marginLeft: (depths.get(issue.issue_id) ?? 0) * 10 }}>
          <button className={styles.issueButton} onClick={() => onSelect(selected ? null : issue.issue_id)} type="button">
            <span className={styles.issueName} title={shortTitle !== issue.title ? issue.title : undefined}>{shortTitle}</span>
            <span className={`state-label ${dispositionClass(issue)}`}>{dispositionLabel(issue)}</span>
            <span className="record-meta">{stateLabel(issue.lawyer_state)}</span>
          </button>
          {issue.why_it_matters ? <p className={styles.muted}>{issue.why_it_matters}</p> : null}
          {selected && onIssueUpdate ? <div className={styles.issueEdit}>
            <label className="field-block"><span className="field-label">Issue title</span><input className="text-input" disabled={!canEdit || saving} onChange={(event) => change(issue.issue_id, { title: event.target.value })} value={title} /></label>
            <label className="field-block"><span className="field-label">Parent issue</span><select className="select-input" disabled={!canEdit || saving} onChange={(event) => change(issue.issue_id, { parent_issue_id: event.target.value || null })} value={parent ?? ""}><option value="">No parent issue</option>{issues.filter((candidate) => candidate.issue_id !== issue.issue_id).map((candidate) => <option key={candidate.issue_id} value={candidate.issue_id}>{candidate.title}</option>)}</select></label>
            <label className="field-block"><span className="field-label">Lawyer state</span><select className="select-input" disabled={!canEdit || saving} onChange={(event) => change(issue.issue_id, { lawyer_state: event.target.value as IssueNode["lawyer_state"] })} value={state ?? "open"}><option value="open">Open</option><option value="explored">Explored</option><option value="set_aside">Set aside</option></select></label>
            {revisionChanged ? <div className="warning-callout" role="status"><strong>This issue changed while you were editing.</strong><div className="btn-row" style={{ marginTop: 8 }}><button className="btn quiet tiny" disabled={saving} onClick={() => setDrafts((current) => { const next = { ...current }; delete next[issue.issue_id]; return next; })} type="button">Use latest issue</button><button className="btn tiny" disabled={saving} onClick={() => setDrafts((current) => ({ ...current, [issue.issue_id]: { ...current[issue.issue_id], baseRevision: issuesRevision ?? "" } }))} type="button">Rebase my edits</button></div></div> : null}
            {canEdit ? <div className="btn-row"><button className="btn tiny" disabled={saving || revisionChanged || !Object.keys(draft?.changes ?? {}).length || !title.trim()} onClick={() => void save(issue)} type="button">{saving ? "Saving…" : "Save issue"}</button><button className="btn quiet tiny" disabled={saving || !Object.keys(draft?.changes ?? {}).length} onClick={() => setDrafts((current) => { const next = { ...current }; delete next[issue.issue_id]; return next; })} type="button">Reset</button></div> : <p className={styles.muted}>Issue editing is not available in this view.</p>}
            {error[issue.issue_id] ? <p className="warning-callout" role="status" style={{ margin: 0 }}>{error[issue.issue_id]}</p> : null}
          </div> : null}
        </article>;
      })}
    </div>}
  </section>;
}

frontend/components/workspace/Assumption:
"use client";

import { useState } from "react";
import type { AssumptionWatchPanelProps } from "@/lib/workspaceTypes";
import styles from "./MatterExplore.module.css";

export default function AssumptionWatchPanel({ assumptions = [], links, busy = false, builder, onDraft, onOpen }: AssumptionWatchPanelProps) {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [showBuilder, setShowBuilder] = useState(false);
  const [drafting, setDrafting] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const allSelected = assumptions.filter((assumption) => selected.has(assumption.assumption_id)).map((assumption) => assumption.assumption_id);

  function toggle(id: string) { setSelected((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; }); setNotice(""); }
  async function draft() {
    if (!allSelected.length) return;
    setDrafting(true); setError(""); setNotice("");
    try { await onDraft(allSelected); setShowBuilder(true); setNotice("Watch draft created. Review its scope. Saving or scanning it does not start a schedule."); }
    catch (caught) { setError(caught instanceof Error ? caught.message : "The Watch draft could not be created. Your selection is retained."); }
    finally { setDrafting(false); }
  }

  return <section aria-labelledby="assumption-watch-title" className={`${styles.assumptionWatchPanel} watch-panel`}>
    <h2 id="assumption-watch-title">Watch an assumption</h2><p className="watch-help">Link a Watch to named assumptions. Open a linked Watch to inspect its current state and impact review.</p>
    {assumptions.length ? <fieldset className="watch-options"><legend className="label">Assumptions to watch</legend>{assumptions.map((assumption) => <label className="checkbox-row" key={assumption.assumption_id}><input checked={selected.has(assumption.assumption_id)} onChange={() => toggle(assumption.assumption_id)} type="checkbox" /><span>{assumption.text}</span></label>)}</fieldset> : <p className="empty-state">No named assumption is available to watch.</p>}
    <button className="btn agent" disabled={busy || drafting || !allSelected.length} onClick={() => void draft()} type="button">{drafting ? "Creating draft…" : "Create linked Watch draft"}</button>
    {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <p className="watch-status" role="status">{notice}</p> : null}
    {showBuilder && builder ? <div className="watch-builder"><div className="watch-builder__label"><span className="state-label state-agent">Draft only</span><span>Start Watch is a separate action inside the builder.</span></div>{builder}</div> : null}
    <div className="watch-links"><h3>Linked Watches</h3>{links.length === 0 ? <p className="empty-state">No Watch is linked to this matter.</p> : links.map((link) => <article className="watch-link" key={link.watch_id}><div><strong>{link.title || "Unnamed Watch"}</strong><p><span>Status: {link.state || "Inspect the Watch"}</span><span>Assumptions: {link.assumption_labels?.join(", ") || "No labels supplied"}</span><span>Linked decisions: {link.decision_titles?.join(", ") || "None"}</span></p></div><button className="btn quiet" onClick={() => onOpen(link.watch_id)} type="button">Inspect status and impact</button></article>)}</div>
  </section>;
}

frontend/components/workspace/FactReques:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { ContinuityRunCommand, FactReply, FactRequestPanelProps, FactRequestResult } from "@/lib/continuityTypes";
import { factRequestStateLabel, newActionKey, preparationNotice, receiptNotice, recoverRetryCommand, retryDraftKey, type PresentationNotice } from "@/lib/teamPresentation";
import styles from "./MatterContinuity.module.css";

type RetryableCommand = { source_action_key: string };

export default function FactRequestPanel(props: FactRequestPanelProps) {
  const { actor, question, requests, selectedRequestId, drafts, busy = false, error, onDraftChange } = props;
  const [pending, setPending] = useState("");
  const [notice, setNotice] = useState<PresentationNotice | null>(null);
  const [localError, setLocalError] = useState("");
  const [reassessment, setReassessment] = useState<FactRequestResult["reassessment"]>(null);
  const frozen = useRef<Record<string, string>>({});
  const activeContext = useRef(props.contextKey); activeContext.current = props.contextKey;
  useEffect(() => {
    frozen.current = {};
    setPending(""); setNotice(null); setLocalError(""); setReassessment(null);
  }, [props.contextKey]);
  const selected = useMemo(() => requests.find((request) => request.request_id === selectedRequestId) ?? null, [requests, selectedRequestId]);
  const locked = busy || Boolean(pending);
  const value = (field: string, fallback = "") => Object.hasOwn(drafts, field) ? drafts[field] : fallback;

  function commandFor<T extends RetryableCommand>(slot: string, intent: unknown, base: Omit<T, "source_action_key">): T {
    const field = retryDraftKey("fact-request", slot);
    const recovered = recoverRetryCommand<T>(frozen.current[field] ?? drafts[field], intent, base, () => newActionKey(slot));
    frozen.current[field] = recovered.serialized;
    if (!recovered.reused) onDraftChange(field, recovered.serialized);
    return recovered.command;
  }
  function clear(fields: string[], slot: string) { fields.forEach((field) => onDraftChange(field, "")); const retryField = retryDraftKey("fact-request", slot); onDraftChange(retryField, ""); delete frozen.current[retryField]; }
  function fail(cause: unknown, fallback: string) { setLocalError(cause instanceof Error ? cause.message : fallback); }
  async function perform(label: string, work: () => Promise<FactRequestResult>, success: string, clearFields: string[] = []) {
    const startedIn = props.contextKey;
    setPending(label); setLocalError(""); setNotice(null);
    try {
      const result = await work();
      if (activeContext.current !== startedIn) return;
      setNotice(receiptNotice(result.receipt, success));
      setReassessment(result.reassessment ?? null);
      if (result.receipt.state === "applied") clear(clearFields, label);
    } catch (cause) { if (activeContext.current === startedIn) fail(cause, "The action did not finish. Your input is retained for retry."); }
    finally { if (activeContext.current === startedIn) setPending(""); }
  }

  async function copyWording() {
    const wording = value("request.wording", selected?.wording ?? "").trim();
    if (!wording) { setLocalError("Add request wording before you copy it."); return; }
    try { await navigator.clipboard.writeText(wording); setNotice({ tone: "agent", word: "Copied", detail: "The request was copied. The app has not marked it as sent." }); setLocalError(""); }
    catch { setLocalError("Copy failed. Select the request text and copy it manually."); }
  }

  async function prepareWording() {
    if (!question || !props.onPrepareWording) return;
    const slot = `prepare-wording:${question.question_id}`;
    const instruction = "Draft concise, editable wording for this fact request. Do not mark it as sent.";
    const startedIn = props.contextKey;
    setPending(slot); setLocalError(""); setNotice(null);
    try {
      const result = await props.onPrepareWording(question.question_id, commandFor<ContinuityRunCommand>(slot, { question_id: question.question_id, instruction }, { instruction }));
      if (activeContext.current !== startedIn) return;
      setNotice(preparationNotice(result.state, "Request wording", "No external request was recorded."));
      if (result.state === "completed") clear([], slot);
    } catch (cause) { if (activeContext.current === startedIn) fail(cause, "Wording preparation failed. Retry will use the same saved action."); }
    finally { if (activeContext.current === startedIn) setPending(""); }
  }

  const wording = value("request.wording", selected?.wording ?? "");
  const person = value("request.person", selected?.requested_person ?? "");
  const due = value("request.due", selected?.due_at?.slice(0, 10) ?? "");

  return <section className={`${styles.factRequest} fact-request`} aria-labelledby="fact-request-title">
    <header><div><p className="eyebrow">Supporting fact</p><h2 id="fact-request-title">Request and record an answer</h2></div><span className="fact-request__actor">Entering lawyer: {actor.display_name}</span></header>
    <p className="fact-request__intro">Prepare text here, then copy it. Only “Record external request” changes its state.</p>
    {error ? <Notice tone="failure" word="Failed" detail={error} /> : null}{notice ? <Notice {...notice} /> : null}{localError ? <Notice tone="failure" word="Failed" detail={localError} alert /> : null}
    {question ? <div className="fact-request__question"><span>Linked question</span><p>{question.text}</p></div> : <p className="muted">Choose a supporting question before you prepare a request.</p>}
    {requests.length ? <label className="label" htmlFor="fact-request-select">Saved request</label> : null}
    {requests.length ? <select id="fact-request-select" className="select-input" value={selectedRequestId ?? ""} onChange={(event) => props.onSelectRequest(event.target.value || null)} disabled={locked}><option value="">Prepare a new request</option>{requests.map((request) => <option value={request.request_id} key={request.request_id}>{factRequestStateLabel(request.state)} · {request.requested_person || "Recipient not specified"}</option>)}</select> : null}
    <div className="fact-request__form">
      <label className="label" htmlFor="fact-request-wording">Editable request</label><textarea id="fact-request-wording" className="text-input prose" value={wording} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.wording", event.target.value)} placeholder="Could you confirm…" />
      <div className="fact-request__grid"><label><span className="label">Requested person</span><input className="text-input" value={person} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.person", event.target.value)} /></label><label><span className="label">Requested date (optional)</span><input className="text-input" type="date" value={due} disabled={locked || Boolean(selected && selected.state !== "prepared")} onChange={(event) => onDraftChange("request.due", event.target.value)} /></label></div>
      <div className="btn-row"><button type="button" className="btn primary" disabled={locked || !question || !wording.trim() || Boolean(selected && selected.state !== "prepared")} onClick={() => { const slot = selected ? `request-edit:${selected.request_id}` : "request-create"; const intent = selected ? { request_id: selected.request_id, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null } : { question_id: question!.question_id, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null }; void perform(slot, () => selected ? props.onEdit(selected.request_id, commandFor(slot, intent, { expected_revision: selected.revision, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null })) : props.onCreate(commandFor(slot, intent, { question_id: question!.question_id, expected_question_revision: question!.source_revision, business_question_revision: question!.business_question_revision, wording: wording.trim(), requested_person: person.trim() || null, due_at: due || null })), selected ? "Request changes saved." : "Request prepared."); }}>{pending.startsWith("request-") ? "Saving…" : selected ? "Save request changes" : "Prepare request"}</button><button className="btn quiet" type="button" disabled={locked || !wording.trim()} onClick={() => void copyWording()}>Copy</button>{props.onPrepareWording && question ? <button className="btn agent" type="button" disabled={locked} onClick={() => void prepareWording()}>{pending.startsWith("prepare-wording:") ? "Preparing…" : "Draft wording"}</button> : null}</div>
    </div>
    {selected ? <SavedRequest request={selected} {...props} locked={locked} pending={pending} value={value} setPending={setPending} setNotice={setNotice} setError={setLocalError} perform={perform} commandFor={commandFor} /> : null}
    {reassessment ? <div className="fact-request__reassess"><p><strong>Answer saved.</strong> Reassess the current matter with the recorded fact.</p><button className="btn agent" type="button" disabled={locked} onClick={() => { setPending("reassess"); setLocalError(""); void props.onReassess(reassessment).then((result) => setNotice(result.state === "completed" ? { tone: "agent", word: "Complete", detail: "Saved analysis now uses the recorded fact. Drafts and decisions stay unchanged." } : { tone: "agent", word: result.state === "queued" ? "Queued" : "Working", detail: "Reassessment uses the saved fact. Drafts and decisions stay unchanged." })).catch((cause) => fail(cause, "Reassessment failed. The saved reply and fact remain recorded.")).finally(() => setPending("")); }}>Reassess current answer</button></div> : null}
  </section>;
}

function SavedRequest({ request, actor, locked, pending, value, onDraftChange, onAction, onSaveReply, onRecordReply, onOpenTarget, perform, commandFor }: any) {
  const replyText = value("reply.text"); const speaker = value("reply.speaker"); const date = value("reply.date");
  return <div className="fact-request__saved"><div className="fact-request__saved-head"><div><span className={`fact-state state-${request.state === "answer_recorded" ? "healthy" : "attention"}`}>{factRequestStateLabel(request.state)}</span><p className="small">Requested from: {request.requested_person || "Not specified"}</p></div><button className="btn quiet tiny" type="button" onClick={() => onOpenTarget({ matter_id: request.matter_id, kind: "fact_request", target_id: request.request_id, revision: request.revision })}>Open record</button></div>
    {request.remaining_question ? <p className="fact-request__remaining"><strong>Still open:</strong> {request.remaining_question}</p> : null}
    {(request.state ?? "prepared") === "prepared" ? <div className="btn-row"><button className="btn review" type="button" disabled={locked} onClick={() => { const slot = `request-external:${request.request_id}`; void perform(slot, () => onAction(request.request_id, commandFor(slot, { request_id: request.request_id, action: "requested_externally" }, { action: "requested_externally", expected_revision: request.revision })), "External request recorded."); }}>Record external request</button><button className="btn quiet" type="button" disabled={locked} onClick={() => { const slot = `request-open:${request.request_id}`; void perform(slot, () => onAction(request.request_id, commandFor(slot, { request_id: request.request_id, action: "leave_open" }, { action: "leave_open", expected_revision: request.revision })), "Request left open."); }}>Leave open</button></div> : null}
    <div className="fact-request__reply"><h3>Paste a reply</h3><p className="small muted">The exact reply is saved as supplied text. The speaker is separate from {actor.display_name}, who enters it.</p><label className="label" htmlFor="fact-reply-text">Exact reply text</label><textarea id="fact-reply-text" className="text-input prose" value={replyText} disabled={locked} onChange={(event) => onDraftChange("reply.text", event.target.value)} /><div className="fact-request__grid"><label><span className="label">Reported speaker (optional)</span><input className="text-input" value={speaker} disabled={locked} onChange={(event) => onDraftChange("reply.speaker", event.target.value)} /></label><label><span className="label">Reported date (optional)</span><input className="text-input" type="date" value={date} disabled={locked} onChange={(event) => onDraftChange("reply.date", event.target.value)} /></label></div><button className="btn primary" type="button" disabled={locked || !replyText.trim()} onClick={() => { const slot = `reply-save:${request.request_id}`; const intent = { request_id: request.request_id, text: replyText, reported_speaker: speaker.trim() || null, reported_at: date || null }; void perform(slot, () => onSaveReply(request.request_id, commandFor(slot, intent, { expected_revision: request.revision, text: replyText, reported_speaker: speaker.trim() || null, reported_at: date || null })), "Exact reply saved.", ["reply.text", "reply.speaker", "reply.date"]); }}>{pending.startsWith("reply-save:") ? "Saving reply…" : "Save reply"}</button></div>
    {(request.replies ?? []).map((reply: FactReply) => <ReplyRecord key={reply.reply_id} request={request} reply={reply} locked={locked} value={value} onDraftChange={onDraftChange} onRecordReply={onRecordReply} perform={perform} commandFor={commandFor} />)}
  </div>;
}

function ReplyRecord({ request, reply, locked, value, onDraftChange, onRecordReply, perform, commandFor }: any) {
  const answer = value(`answer.text:${reply.reply_id}`, reply.text); const coverage = value(`answer.coverage:${reply.reply_id}`, "full"); const remaining = value(`answer.remaining:${reply.reply_id}`); const supersedes = value(`answer.supersedes:${reply.reply_id}`);
  const answerInputId = `reported-fact-${reply.reply_id}`;
  const slot = `answer-record:${request.request_id}:${reply.reply_id}`;
  const intent = { request_id: request.request_id, reply_id: reply.reply_id, answer_text: answer.trim(), coverage, remaining_question: coverage === "partial" ? remaining.trim() : null, supersedes_fact_id: supersedes.trim() || null };
  return <details className="fact-request__answer"><summary>Record answer from {reply.reported_speaker || "speaker unknown"}</summary><blockquote>{reply.text}</blockquote><label className="label" htmlFor={answerInputId}>Reported fact</label><textarea id={answerInputId} className="text-input" value={answer} disabled={locked} onChange={(event) => onDraftChange(`answer.text:${reply.reply_id}`, event.target.value)} /><fieldset><legend className="label">Coverage</legend><label><input type="radio" name={`coverage-${reply.reply_id}`} checked={coverage === "full"} onChange={() => onDraftChange(`answer.coverage:${reply.reply_id}`, "full")} /> Full answer</label><label><input type="radio" name={`coverage-${reply.reply_id}`} checked={coverage === "partial"} onChange={() => onDraftChange(`answer.coverage:${reply.reply_id}`, "partial")} /> Partial answer</label></fieldset>{coverage === "partial" ? <label><span className="label">Question that remains</span><input className="text-input" value={remaining} onChange={(event) => onDraftChange(`answer.remaining:${reply.reply_id}`, event.target.value)} /></label> : null}<label><span className="label">Superseded fact ID (optional)</span><input className="text-input" value={supersedes} onChange={(event) => onDraftChange(`answer.supersedes:${reply.reply_id}`, event.target.value)} /></label><button className="btn primary" type="button" disabled={locked || !answer.trim() || (coverage === "partial" && !remaining.trim())} onClick={() => void perform(slot, () => onRecordReply(request.request_id, reply.reply_id, commandFor(slot, intent, { expected_revision: request.revision, expected_question_revision: request.question_revision, business_question_revision: request.business_question_revision, answer_text: answer.trim(), coverage, remaining_question: coverage === "partial" ? remaining.trim() : null, supersedes_fact_id: supersedes.trim() || null })), coverage === "partial" ? "Partial answer recorded. The remaining question stays open." : "Answer recorded.")}>Record this answer</button></details>;
}

function Notice({ tone, word, detail, alert = false }: PresentationNotice & { alert?: boolean }) { return <p className={`fact-request__notice ${tone}`} role={alert ? "alert" : "status"}><strong>{word}:</strong> {detail}</p>; }

frontend/components/workspace/MatterFile:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { DragEvent } from "react";
import ContextTray from "./ContextTray";
import type { ContextSelection, DocumentReferenceTarget, FileUploadBatch, FileUploadOutcome, MatterFileEntry, MatterFilesPanelProps } from "@/lib/workspaceTypes";
import { isSafeVaultPath } from "@/lib/research";
import styles from "./MatterTools.module.css";

type UploadOutcome = Omit<FileUploadOutcome, "state"> & { state: FileUploadOutcome["state"] | "pending" | "completed" | "unknown"; input: File };
type UploadBatch = { id: string; destination: "library" | "inquiry"; outcomes: UploadOutcome[] };
type ReferenceAwareMatterFilesPanelProps = MatterFilesPanelProps & {
  onOpenReference?: (target: DocumentReferenceTarget) => void;
};
function extractionLabel(state: MatterFileEntry["extraction_state"]) {
  return ({ pending: "Preparing", complete: "Text ready", partial: "Partial text", failed: "Preview failed", unsupported: "Unsupported type", not_applicable: "Saved output" })[state];
}
function stateClass(state: MatterFileEntry["extraction_state"]) {
  if (state === "complete" || state === "not_applicable") return "state-healthy";
  if (state === "failed" || state === "unsupported") return "state-failure";
  return state === "partial" ? "state-attention" : "state-agent";
}
export function uploadState(outcomes: UploadOutcome[]) {
  if (outcomes.some((outcome) => outcome.state === "pending")) return { word: "Preparing", tone: "state-agent" };
  const failed = outcomes.filter((outcome) => outcome.state === "failed").length;
  const partial = outcomes.filter((outcome) => outcome.state === "partial").length;
  if (failed === outcomes.length) return { word: "Failed", tone: "state-failure" };
  if (failed || partial) return { word: "Partial", tone: "state-attention" };
  if (outcomes.every((outcome) => outcome.state === "saved")) return { word: "Saved", tone: "state-healthy" };
  return { word: "Completed", tone: "state-agent" };
}
export function normalizeUpload(result: FileUploadBatch | void, inputs: File[]): UploadOutcome[] {
  if (!result) return inputs.map((input, index) => ({ input, name: input.name, state: "completed", retry_key: `legacy-${index}`, failure_detail: "Per-file result not supplied by this upload path." }));
  return inputs.map((input, index) => {
    const outcome = result.outcomes[index];
    return outcome ? { ...outcome, input } : { input, name: input.name, state: "unknown", retry_key: `missing-${index}`, failure_detail: "No result was returned for this file." };
  });
}

export function matterFileReferenceTarget(file: MatterFileEntry, path: string): DocumentReferenceTarget {
  return {
    document_id: file.source_id?.trim() || file.reference_id,
    path,
    revision: file.revision ?? null,
    origin: { surface: "document", record_id: file.reference_id, focus_id: `matter-file-${file.reference_id}` },
  };
}

export default function MatterFilesPanel(props: ReferenceAwareMatterFilesPanelProps) {
  const { open, files, onClose, onUpload, onOpenArtifact, onOpenReference, onRetryFile, manifest, busy = false } = props;
  const [view, setView] = useState<"files" | "context">("files");
  const [query, setQuery] = useState("");
  const [selections, setSelections] = useState(props.selections);
  const [selectionSaving, setSelectionSaving] = useState(false);
  const [selectionDirty, setSelectionDirty] = useState(false);
  const [selectionError, setSelectionError] = useState("");
  const [batches, setBatches] = useState<UploadBatch[]>([]);
  const [retrying, setRetrying] = useState<string | null>(null);
  const [retryError, setRetryError] = useState<Record<string, string>>({});
  const [pickerDestination, setPickerDestination] = useState<"library" | "inquiry">("library");
  const input = useRef<HTMLInputElement>(null);
  const drawer = useRef<HTMLElement>(null);
  const returnFocus = useRef<HTMLElement | null>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => { if (!selectionSaving && !selectionDirty) setSelections(props.selections); }, [props.selections, selectionSaving, selectionDirty]);
  useEffect(() => {
    if (!open) return;
    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const node = drawer.current;
    const focusable = () => Array.from(node?.querySelectorAll<HTMLElement>('button:not([disabled]), input:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])') ?? []);
    focusable()[0]?.focus();
    const keydown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; }
      if (event.key !== "Tab") return;
      const items = focusable(); if (!items.length) return;
      const first = items[0]; const last = items.at(-1)!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); returnFocus.current?.focus(); };
  }, [open]);

  const filtered = useMemo(() => {
    const needle = query.trim().toLocaleLowerCase();
    return needle ? files.filter((file) => `${file.name} ${file.path}`.toLocaleLowerCase().includes(needle)) : files;
  }, [files, query]);
  if (!open) return null;

  async function saveSelections(next: ContextSelection[]) {
    setSelections(next); setSelectionDirty(true); setSelectionSaving(true); setSelectionError("");
    try { await props.onChange(next); setSelectionDirty(false); }
    catch (cause) { setSelectionError(cause instanceof Error ? cause.message : "Selection was not saved. Your choice is retained so you can retry."); throw cause; }
    finally { setSelectionSaving(false); }
  }
  async function toggleFile(file: MatterFileEntry) {
    const existing = selections.find((item) => item.reference_id === file.reference_id);
    const selected = existing ? existing.selected !== false : file.selected;
    const next = existing
      ? selections.map((item) => item.reference_id === file.reference_id ? { ...item, selected: !selected } : item)
      : [...selections, { reference_id: file.reference_id, path: file.path, role: file.kind === "work_product" ? "generated_output" : "source_file", selected: !selected, mandatory: false, revision: file.revision }];
    try { await saveSelections(next); } catch { /* local selection is intentionally retained */ }
  }
  async function upload(batchFiles: File[], destination: "library" | "inquiry") {
    if (!batchFiles.length) return;
    const id = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`;
    setBatches((current) => [...current, { id, destination, outcomes: batchFiles.map((input, index) => ({ input, name: input.name, state: "pending", retry_key: `pending-${index}` })) }]);
    try {
      const result = await onUpload(batchFiles, destination);
      setBatches((current) => current.map((batch) => batch.id === id ? { ...batch, outcomes: normalizeUpload(result, batchFiles) } : batch));
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : "Upload failed. The batch is retained for retry.";
      setBatches((current) => current.map((batch) => batch.id === id ? { ...batch, outcomes: batch.outcomes.map((outcome) => ({ ...outcome, state: "failed", failure_detail: detail })) } : batch));
    }
  }
  async function retryUpload(batchId: string, retryKey: string) {
    const batch = batches.find((item) => item.id === batchId);
    const outcome = batch?.outcomes.find((item) => item.retry_key === retryKey);
    if (!batch || !outcome) return;
    setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? { ...candidate, state: "pending", failure_detail: null } : candidate) } : item));
    try {
      const result = await onUpload([outcome.input], batch.destination);
      const next = normalizeUpload(result, [outcome.input])[0];
      setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? next : candidate) } : item));
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : "Upload failed. The batch is retained for retry.";
      setBatches((current) => current.map((item) => item.id === batchId ? { ...item, outcomes: item.outcomes.map((candidate) => candidate.retry_key === retryKey ? { ...candidate, state: "failed", failure_detail: detail } : candidate) } : item));
    }
  }
  function chooseFiles(destination: "library" | "inquiry") { setPickerDestination(destination); input.current?.click(); }
  function drop(event: DragEvent<HTMLElement>) { event.preventDefault(); void upload(Array.from(event.dataTransfer.files ?? []), view === "context" ? "inquiry" : "library"); }
  async function retry(file: MatterFileEntry) {
    setRetrying(file.reference_id); setRetryError((current) => ({ ...current, [file.reference_id]: "" }));
    try { await onRetryFile(file.reference_id); }
    catch (cause) { setRetryError((current) => ({ ...current, [file.reference_id]: cause instanceof Error ? cause.message : "Retry failed. The saved file remains available." })); }
    finally { setRetrying(null); }
  }
  function openSource(file: MatterFileEntry, path: string) {
    if (onOpenReference) onOpenReference(matterFileReferenceTarget(file, path));
    else onOpenArtifact(path);
  }

  return <>
    <button aria-label="Close files and context" className={styles.filesBackdrop} onClick={onClose} type="button" />
    <aside aria-label="Files and context" aria-modal="true" className={styles.filesPanel} onDragOver={(event) => event.preventDefault()} onDrop={drop} ref={drawer} role="dialog">
      <header className={styles.filesHeader}><div><span className="record-meta">Matter workspace</span><h2 className={styles.filesTitle}>Files &amp; context</h2></div><button aria-label="Close files and context panel" className="btn quiet tiny" onClick={onClose} type="button">Close</button></header>
      <div aria-label="Files and context views" className={`btn-row ${styles.filesTabs}`} role="tablist"><button aria-selected={view === "files"} className={`btn tiny ${view === "files" ? "" : "quiet"}`} onClick={() => setView("files")} role="tab" type="button">Matter files</button><button aria-selected={view === "context"} className={`btn tiny ${view === "context" ? "" : "quiet"}`} onClick={() => setView("context")} role="tab" type="button">Inquiry context</button></div>
      <input hidden multiple onChange={(event) => { void upload(Array.from(event.target.files ?? []), pickerDestination); event.target.value = ""; }} ref={input} type="file" />

      <div className={`btn-row ${styles.filesActions}`}><button className="btn quiet tiny" disabled={busy} onClick={() => chooseFiles("library")} type="button">Add files to library</button><button className="btn agent tiny" disabled={busy} onClick={() => chooseFiles("inquiry")} type="button">Add files to inquiry</button></div>
      <p className={styles.filesCopy}>You can add several files now and add another batch while earlier files are preparing. Dropped files go to the current view.</p>
      {batches.length ? <section aria-label="Recent uploads" className={styles.uploadList}>{batches.map((batch) => {
        const summary = uploadState(batch.outcomes);
        return <div className={styles.uploadCard} key={batch.id}><div className={styles.uploadHeading}><span className={`state-label ${summary.tone}`}>{summary.word}</span><strong>{batch.destination === "inquiry" ? "Inquiry upload" : "Library upload"}</strong></div><div className={styles.uploadRows}>{batch.outcomes.map((outcome, index) => <div className={styles.uploadRow} key={`${outcome.retry_key}:${index}`}><div className={styles.uploadHeading}><span className={styles.fileName}>{outcome.name}</span><span className={`state-label ${outcome.state === "saved" ? "state-healthy" : outcome.state === "failed" ? "state-failure" : outcome.state === "partial" || outcome.state === "unknown" ? "state-attention" : "state-agent"}`}>{outcome.state === "saved" ? "Saved" : outcome.state === "partial" ? "Saved · Partial text" : outcome.state === "failed" ? "Not saved" : outcome.state === "pending" ? "Preparing" : outcome.state === "unknown" ? "Status unavailable" : "Completed"}</span></div>{outcome.failure_detail ? <p className={styles.filesCopy}>{outcome.failure_detail}</p> : null}{outcome.state === "failed" ? <button className="btn quiet tiny" onClick={() => void retryUpload(batch.id, outcome.retry_key)} type="button">Retry {outcome.name}</button> : null}</div>)}</div></div>;
      })}</section> : null}

      {view === "files" ? <section aria-label="Matter files" className={styles.filesContent}>
        <label className="field-block"><span className="field-label">Find by name or folder</span><input className="text-input" onChange={(event) => setQuery(event.target.value)} placeholder="Search matter files" type="search" value={query} /></label>
        {props.folderView ? <details className={styles.folderView}><summary className="btn quiet tiny">Folder view</summary><div className={styles.folderBody}>{props.folderView}</div></details> : null}
        {selectionError ? <div className="warning-callout" role="status"><strong>Selection not saved.</strong> {selectionError} <button className="btn quiet tiny" disabled={selectionSaving} onClick={() => void saveSelections(selections).catch(() => undefined)} type="button">Retry</button></div> : null}
        {filtered.length ? <div className={styles.filesList}>{filtered.map((file) => {
          const selected = selections.find((item) => item.reference_id === file.reference_id)?.selected ?? file.selected;
          const original = file.original_path && isSafeVaultPath(file.original_path) ? file.original_path : null;
          const extracted = file.extracted_path && isSafeVaultPath(file.extracted_path) ? file.extracted_path : null;
          const artifact = file.kind === "work_product" && isSafeVaultPath(file.path) ? file.path : null;
          return <article className={styles.fileCard} id={`matter-file-${file.reference_id}`} key={`${file.reference_id}:${file.path}`}><div className={styles.fileHeading}><div><strong className={styles.fileName}>{file.name}</strong><p className={styles.filesCopy}>{file.kind === "work_product" ? "Generated output" : file.kind === "source" ? "Supplied source" : "Matter file"} · {file.path}</p></div><span className={`state-label ${stateClass(file.extraction_state)}`}>{extractionLabel(file.extraction_state)}</span></div>
            <p className={styles.filesCopy}>Saved: {file.saved_at || "Unknown"}{file.source_id ? ` · Source ID: ${file.source_id}` : " · Source ID: Unknown"}</p>
            {file.failure_detail ? <p className="warning-callout" role="status">{file.failure_detail}</p> : null}
            <div className={`btn-row ${styles.fileActions}`}><button className={`btn tiny ${selected ? "" : "quiet"}`} disabled={busy || selectionSaving} onClick={() => void toggleFile(file)} type="button">{selected ? selectionDirty ? "Selected · Not saved" : "Selected for next inquiry" : selectionDirty ? "Available · Not saved" : "Add to next inquiry"}</button>{original ? <button className="btn quiet tiny" onClick={() => openSource(file, original)} type="button">Open original</button> : null}{extracted ? <button className="btn quiet tiny" onClick={() => openSource(file, extracted)} type="button">Open extracted text</button> : null}{artifact ? <button className="btn quiet tiny" onClick={() => onOpenArtifact(artifact)} type="button">Open generated output</button> : null}{["failed", "partial"].includes(file.extraction_state) ? <button className="btn quiet tiny" disabled={retrying === file.reference_id} onClick={() => void retry(file)} type="button">{retrying === file.reference_id ? "Retrying…" : "Retry preview"}</button> : null}</div>
            {retryError[file.reference_id] ? <p className="warning-callout" role="status">{retryError[file.reference_id]}</p> : null}
            {!original && file.original_path ? <p className="warning-callout" role="status">Unsafe original path blocked.</p> : null}
          </article>;
        })}</div> : <p className={styles.filesCopy}>No files match this search.</p>}
      </section> : <div className={styles.contextContent}><ContextTray busy={busy || selectionSaving} manifest={manifest} onChange={saveSelections} selections={selections} /></div>}
    </aside>
  </>;
}

