"use client";

import { useState } from "react";
import type { ContinuityChangeRecapProps, MeaningfulChange, WorkTarget } from "@/lib/continuityTypes";
import { isOpenableWorkTarget, visibleRecapChanges } from "@/lib/orientationPresentation";
import styles from "./MatterReview.module.css";

type RecapChange = MeaningfulChange | Record<string, unknown>;

function changeText(change: RecapChange) {
  const record = change as Record<string, unknown>;
  const title = typeof record.title === "string" ? record.title : typeof record.label === "string" ? record.label : typeof record.path === "string" ? record.path : "Matter record";
  const detail = typeof record.detail === "string" ? record.detail : typeof record.message === "string" ? record.message : typeof record.state === "string" ? record.state : "changed";
  return `${title}: ${detail}`;
}

function changeKey(change: RecapChange, index: number) {
  const record = change as Record<string, unknown>;
  return String(record.change_id ?? record.path ?? record.label ?? record.title ?? index);
}

function changeTarget(change: RecapChange): WorkTarget | null {
  const target = (change as { target?: unknown }).target;
  return isOpenableWorkTarget(target) ? target : null;
}

export default function ChangeRecap({ recap, onOpenArtifact, onMarkSeen, meaningfulChanges, firstVisit = false, onOpenTarget }: ContinuityChangeRecapProps) {
  const [saving, setSaving] = useState(false);
  const [savedRevision, setSavedRevision] = useState<string | null>(null);
  const [error, setError] = useState("");
  const [expanded, setExpanded] = useState(false);
  if (!recap) return null;
  const currentRecap = recap;
  const allChanges = (meaningfulChanges ?? currentRecap.changes ?? []) as RecapChange[];
  const changes = visibleRecapChanges(allChanges, expanded);
  const outputs = currentRecap.new_outputs ?? [];
  const failures = currentRecap.output_read_failures ?? [];
  const hasChanges = Boolean(allChanges.length || outputs.length || failures.length);
  const seen = savedRevision === currentRecap.current_revision;
  const recapState = seen ? "Seen" : hasChanges ? (firstVisit ? "First visit" : "Updated") : "Current";
  const recapStateClass = seen ? "state-label state-healthy" : hasChanges ? "state-label state-agent" : "record-meta";
  async function markSeen() {
    setSaving(true); setError("");
    try { await onMarkSeen(currentRecap.current_revision); setSavedRevision(currentRecap.current_revision); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Changes were not marked seen. You can retry."); }
    finally { setSaving(false); }
  }
  return <section aria-label="What changed" className={`${styles.card} ${styles.stack}`}>
    <div className={styles.between}><h2 className={styles.sectionTitle}>What changed</h2><span className={recapStateClass}>{recapState}</span></div>
    {!hasChanges ? <p className={styles.copy}>No new saved work since you last reviewed this matter.</p> : <>
      {changes.length ? <ul className={styles.recapList}>{changes.map((change, index) => { const target = changeTarget(change); return <li key={`${changeKey(change, index)}:${index}`}>{changeText(change)}{target && onOpenTarget ? <button className="btn quiet tiny" onClick={() => onOpenTarget(target)} style={{ marginLeft: 7 }} type="button">Open</button> : null}</li>; })}</ul> : null}
      {allChanges.length > 3 ? <button aria-expanded={expanded} className="btn quiet tiny" onClick={() => setExpanded(value => !value)} type="button">{expanded ? "Show fewer" : `Show all ${allChanges.length} changes`}</button> : null}
      {outputs.length ? <div style={{ marginTop: 10 }}><strong className="small">Saved outputs</strong><div className="btn-row" style={{ marginTop: 7 }}>{outputs.map((path) => <button className="btn quiet tiny" key={path} onClick={() => onOpenArtifact(path)} type="button">Open {path.split("/").at(-1) ?? path}</button>)}</div></div> : null}
      {failures.length ? <div className="warning-callout" role="status" style={{ marginTop: 10 }}><strong>Some optional output files could not be read.</strong><ul style={{ marginBottom: 0 }}>{failures.map((failure) => <li key={failure.path}>{failure.path.split("/").at(-1) ?? failure.path}: {failure.message}</li>)}</ul></div> : null}
      <div className="btn-row" style={{ marginTop: 12 }}><button className="btn tiny" disabled={saving || seen} onClick={() => void markSeen()} type="button">{saving ? "Saving…" : seen ? "Marked seen" : "Mark seen"}</button>{error ? <span className="warning-callout" role="status" style={{ padding: "5px 8px" }}>{error}</span> : null}</div>
    </>}
  </section>;
}

frontend/components/workspace/DocumentNa:
"use client";

import type { DocumentIdentity, DocumentKind, DocumentNavigatorProps } from "@/lib/workspaceTypes";
import styles from "./MatterDocuments.module.css";

export type DocumentGroup = { groupId: string; title: string; documents: DocumentIdentity[] };

export function groupDocuments(documents: readonly DocumentIdentity[], kind: DocumentKind): DocumentGroup[] {
  const groups = new Map<string, DocumentGroup>();
  for (const document of documents) {
    if (document.kind !== kind) continue;
    const identity = document.work_product_id?.trim() || document.document_id;
    const groupId = `${kind}:${identity}`;
    const group = groups.get(groupId);
    if (group) group.documents.push(document);
    else groups.set(groupId, { groupId, title: document.title, documents: [document] });
  }
  return [...groups.values()];
}

export function documentType(document: DocumentIdentity): string {
  const name = document.path.split("/").at(-1) || document.path;
  const extension = name.includes(".") ? name.split(".").at(-1) : "file";
  return (extension || "file").toUpperCase();
}

export function lifecycleLabel(document: DocumentIdentity): string {
  if (document.lifecycle_state === "editing_draft") return "Editing draft";
  if (document.lifecycle_state === "reading_source") return "Reading source";
  if (document.lifecycle_state === "final") return "Final";
  if (document.lifecycle_state === "approved") return "Approved";
  return "Matter record";
}

export function documentPickerValue(document: DocumentIdentity): string {
  return JSON.stringify([document.document_id, document.path, document.revision]);
}

function DocumentGroupList({ groups, duplicateTitles, activeDocumentId, activePickerValue, onOpen, onCreateWorkingCopy }: { groups: DocumentGroup[]; duplicateTitles: ReadonlySet<string>; activeDocumentId: string | null; activePickerValue?: string; onOpen: DocumentNavigatorProps["onOpen"]; onCreateWorkingCopy: DocumentNavigatorProps["onCreateWorkingCopy"] }) {
  return <ul className={styles.documentList}>{groups.map((group) => {
    const current = group.documents[0];
    const versions = group.documents.slice(1);
    return <li className={styles.documentItem} key={group.groupId}>
      <div className={styles.documentRow}>
        <button aria-current={current.document_id === activeDocumentId && (!activePickerValue || documentPickerValue(current) === activePickerValue) ? "page" : undefined} className={`btn quiet tiny ${styles.documentButton}`} type="button" onClick={() => onOpen(current)}>{group.title}</button>
        <span className={styles.documentMeta}>{documentType(current)} · {lifecycleLabel(current)} · Saved</span>
      </div>
      {duplicateTitles.has(current.title) ? <div className={styles.documentMeta}>{current.path}</div> : null}
      {current.kind === "source" && !current.editable ? <button className={`btn quiet tiny ${styles.documentButton}`} type="button" onClick={() => onCreateWorkingCopy(current)}>Create working copy</button> : null}
      {versions.length ? <details className={styles.versionDisclosure}><summary>Earlier versions ({versions.length})</summary><ul className={styles.versionList}>{versions.map((version) => <li className={styles.documentRow} key={`${version.document_id}:${version.revision}`}><button aria-current={activePickerValue === documentPickerValue(version) ? "page" : undefined} className={`btn quiet tiny ${styles.documentButton}`} type="button" onClick={() => onOpen(version)}>{version.version_id || version.revision}</button><span className={styles.documentMeta}>{documentType(version)} · {lifecycleLabel(version)} · Saved</span></li>)}</ul></details> : null}
    </li>;
  })}</ul>;
}

export default function DocumentNavigator({ documents, activeDocumentId, activeDocumentPath, activeDocumentRevision, matterRecordsExpanded = false, onOpen, onCreateWorkingCopy }: DocumentNavigatorProps) {
  const workProducts = groupDocuments(documents, "work_product");
  const sources = groupDocuments(documents, "source");
  const matterRecords = groupDocuments(documents, "matter_record");
  const activeDocument = documents.find((document) => document.document_id === activeDocumentId
    && (!activeDocumentPath || document.path === activeDocumentPath)
    && (!activeDocumentRevision || document.revision === activeDocumentRevision));
  const activeValue = activeDocument ? documentPickerValue(activeDocument) : "";
  const titleCounts = new Map<string, number>();
  for (const document of documents) titleCounts.set(document.title, (titleCounts.get(document.title) ?? 0) + 1);
  const duplicateTitles = new Set([...titleCounts].filter(([, count]) => count > 1).map(([title]) => title));

  return <nav aria-label="Documents" className={styles.navigator}>
    <h2 className={styles.navigatorTitle}>Documents</h2>
    <label className={`field-block ${styles.navigatorPicker}`}><span className="field-label">Document picker · Work products ({workProducts.length}) · Sources ({sources.length})</span><select className="text-input" value={activeValue} onChange={(event) => { const selected = documents.find((document) => documentPickerValue(document) === event.target.value); if (selected) onOpen(selected); }}><option value="">Choose a document</option>{documents.map((document) => <option key={documentPickerValue(document)} value={documentPickerValue(document)}>{document.title} · {lifecycleLabel(document)}{duplicateTitles.has(document.title) ? ` · ${document.path}` : ""}</option>)}</select></label>
    <div className={styles.navigatorGrid}>
    <section aria-labelledby="work-products-heading" className={styles.navigatorSection}><h3 className={styles.navigatorSectionTitle} id="work-products-heading">Work products ({workProducts.length})</h3><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={workProducts} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></section>
    <section aria-labelledby="sources-heading" className={styles.navigatorSection}><h3 className={styles.navigatorSectionTitle} id="sources-heading">Sources ({sources.length})</h3><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={sources} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></section>
    </div>
    <details className={styles.navigatorRecords} open={matterRecordsExpanded}><summary>Matter records ({matterRecords.length})</summary><DocumentGroupList activeDocumentId={activeDocumentId} activePickerValue={activeValue} duplicateTitles={duplicateTitles} groups={matterRecords} onCreateWorkingCopy={onCreateWorkingCopy} onOpen={onOpen} /></details>
  </nav>;
}

