"use client";

import { useEffect, useRef } from "react";
import type { EvidenceDrawerProps } from "@/lib/workspaceTypes";
import { isSafeSourceUrl, isSafeVaultPath } from "@/lib/research";
import styles from "./MatterDocuments.module.css";

function supportLabel(state: NonNullable<NonNullable<EvidenceDrawerProps["evidence"]>["support_state"]>) {
  return ({ supplied: "Supplied", retrieved: "Retrieved", verified: "Verified support", unverified_lead: "Unverified lead", unknown: "Status unknown" })[state];
}

export default function EvidenceDrawer({ evidence, open, onClose, onOpenArtifact }: EvidenceDrawerProps) {
  const drawer = useRef<HTMLElement>(null);
  const returnFocus = useRef<HTMLElement | null>(null);
  const closeRef = useRef(onClose);
  useEffect(() => { closeRef.current = onClose; }, [onClose]);
  useEffect(() => {
    if (!open) return;
    returnFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const node = drawer.current;
    const focusable = () => Array.from(node?.querySelectorAll<HTMLElement>('button:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])') ?? []);
    focusable()[0]?.focus();
    const keydown = (event: globalThis.KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; }
      if (event.key !== "Tab") return;
      const items = focusable(); if (!items.length) return;
      const first = items[0]; const last = items.at(-1)!;
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); returnFocus.current?.focus(); };
  }, [open]);
  if (!open) return null;

  const state = evidence?.support_state ?? "unknown";
  const safeUrl = evidence?.url && isSafeSourceUrl(evidence.url) ? evidence.url : null;
  const safePath = evidence?.path && isSafeVaultPath(evidence.path) ? evidence.path : null;
  return <>
    <button aria-label="Close evidence" className={styles.evidenceBackdrop} onClick={onClose} type="button" />
    <aside aria-label="Claim evidence" aria-modal="true" className={styles.evidenceDrawer} ref={drawer} role="dialog">
      <header className={styles.evidenceHeader}>
        <div><span className="record-meta">Evidence for claim</span><h2 className={styles.evidenceTitle}>{evidence?.source_label || "Source unavailable"}</h2></div>
        <button aria-label="Close evidence drawer" className="btn quiet tiny" onClick={onClose} type="button">Close</button>
      </header>
      {!evidence ? <div className="warning-callout" role="status"><strong>Evidence unavailable.</strong> The saved answer remains visible.</div> : <div className={styles.evidenceStack}>
        <section className={styles.evidenceCard}><span className={`state-label ${state === "verified" ? "state-healthy" : state === "unverified_lead" || state === "unknown" ? "state-attention" : "state-agent"}`}>{supportLabel(state)}</span><dl className={styles.evidenceDetails}><dt>Claim ID</dt><dd>{evidence.claim_id || "Unknown"}</dd><dt>Claim revision</dt><dd>{evidence.claim_revision || "Legacy or unavailable"}</dd><dt>Output revision</dt><dd>{evidence.output_revision || "Legacy or unavailable"}</dd><dt>Source ID</dt><dd>{evidence.source_id || "Unknown"}</dd><dt>Location</dt><dd>{evidence.locator || "Exact location unavailable"}</dd><dt>Retrieved</dt><dd>{evidence.retrieved_at || "Unknown"}</dd><dt>Version</dt><dd>{evidence.source_version || evidence.source_hash || "Unknown"}</dd></dl><p className="faint">Source support and legal applicability are separate. Supplied or Retrieved does not mean Verified, and no source status proves that the rule applies to this matter.</p></section>
        <section className={styles.evidenceCard}><span className="record-meta">Exact available passage</span>{evidence.available_excerpt ? <blockquote className={styles.evidenceReading}>{evidence.available_excerpt}</blockquote> : <p className={styles.evidenceReading}>No exact passage is available. Retrieval may have failed or the saved source reference may be missing.</p>}</section>
        {evidence.explanation ? <section className={`wash-agent ${styles.evidenceCard}`}><span className="record-meta">Generated explanation · How this source supports this claim</span><p className={styles.evidenceReading}>{evidence.explanation}</p></section> : <section className="warning-callout" role="status"><strong>Claim explanation unavailable.</strong> The source record remains available, but its support for this claim is not explained.</section>}
        <section className={styles.evidenceCard}><span className="record-meta">Open source</span><div className={`btn-row ${styles.evidenceActions}`}>{safeUrl ? <a className="btn quiet tiny" href={safeUrl} rel="noopener noreferrer" target="_blank">Open public source</a> : null}{safePath ? <button className="btn quiet tiny" onClick={() => onOpenArtifact(safePath)} type="button">Open saved source</button> : null}{!safeUrl && !safePath ? <span className="faint">No safe source link is available.</span> : null}</div>{(evidence.url && !safeUrl) || (evidence.path && !safePath) ? <p className="warning-callout" role="status">An unsafe source location was blocked.</p> : null}<p className="faint">Opening a link does not verify the source.</p></section>
      </div>}
    </aside>
  </>;
}

frontend/components/workspace/OutputTemp:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { DraftResult, OutputTemplate, OutputTemplateLibraryProps } from "@/lib/workspaceTypes";
import styles from "./MatterTools.module.css";

const titleCase = (value: string) => value.replaceAll("_", " ").replaceAll("-", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const isUnavailable = (template: OutputTemplate) => template.enabled === false || ["failed", "malformed", "unavailable"].includes(template.status ?? "");
const runningPreviewStates = new Set(["queued", "running", "pending", "started"]);
function previewState(result: DraftResult) {
  if (result.artifact) return { label: "Editable preview", className: "state-agent", detail: "This preview is editable work product. It is not approval and does not record a decision." };
  const state = result.state.trim().toLowerCase();
  if (runningPreviewStates.has(state)) return { label: "Preparing", className: "state-agent", detail: `No preview artifact is ready. Current state: ${result.state}.` };
  const label = state === "not_saved" ? "Not saved" : state === "cancelled" || state === "canceled" ? "Cancelled" : state === "failed" ? "Failed" : "No artifact";
  return { label, className: "state-failure", detail: result.receipt?.failure_detail || `No editable preview was created. Current state: ${result.state}.` };
}

export default function OutputTemplateLibrary({ templates, selectedTemplateId, busy = false, onSelect, onCreate, onEdit, onDuplicate, onSetDefault, onPreview, onOpenArtifact }: OutputTemplateLibraryProps) {
  const selected = templates.find((template) => template.template_id === selectedTemplateId) ?? null;
  const outputTypes = useMemo(() => Array.from(new Set(templates.map((template) => template.output_type || "unavailable"))).sort(), [templates]);
  const [pending, setPending] = useState<"copy" | "default" | "preview" | "">("");
  const [overrides, setOverrides] = useState<Record<string, string>>({});
  const [preview, setPreview] = useState<DraftResult | null>(null);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [noticeFailed, setNoticeFailed] = useState(false);
  const selectedIdentity = selected ? `${selected.template_id}:${selected.revision}` : "";
  const latestSelection = useRef(selectedIdentity);
  const selectionGeneration = useRef(0);
  if (latestSelection.current !== selectedIdentity) { latestSelection.current = selectedIdentity; selectionGeneration.current += 1; }
  useEffect(() => { setPending(""); setPreview(null); setError(""); setNotice(""); setNoticeFailed(false); setOverrides({}); }, [selectedIdentity]);

  function choose(template: OutputTemplate) { onSelect(template); setPreview(null); setError(""); setNotice(""); setNoticeFailed(false); setOverrides({}); }
  async function act(action: "copy" | "default" | "preview") {
    if (!selected) return;
    const actionIdentity = `${selected.template_id}:${selected.revision}`;
    const actionGeneration = selectionGeneration.current;
    const stillSelected = () => latestSelection.current === actionIdentity && selectionGeneration.current === actionGeneration;
    setPending(action); setError(""); setNotice(""); setNoticeFailed(false);
    try {
      if (action === "copy") { const copy = await onDuplicate(selected); if (!stillSelected()) return; setNotice(`${copy.name} was created. Open it to rename or edit it.`); }
      if (action === "default") { await onSetDefault(selected); if (!stillSelected()) return; setNotice(`${selected.name} is now the default for ${titleCase(selected.output_type)}.`); }
      if (action === "preview") {
        const result = await onPreview(selected, overrides); if (!stillSelected()) return; setPreview(result);
        const state = previewState(result);
        setNoticeFailed(state.className === "state-failure");
        setNotice(result.artifact ? "Editable preview created from the current matter." : state.detail);
      }
    } catch (caught) { if (stillSelected()) setError(caught instanceof Error ? caught.message : `The ${action} action failed. Your selection and preview instructions are retained.`); }
    finally { if (stillSelected()) setPending(""); }
  }

  return <section aria-labelledby="template-library-title" className={`${styles.library} template-library`}>
    <header className="template-library__head"><div><h2 id="template-library-title">Output templates</h2><p>Templates set reusable structure and guidance. Instructions below apply to one preview only.</p></div><button className="btn primary" disabled={busy} onClick={onCreate} type="button">Create blank template</button></header>
    {selectedTemplateId && !selected ? <div className="template-warning" role="alert"><span className="state-label state-failure">Unavailable</span><span>The selected template <span className="mono">{selectedTemplateId}</span> is missing. Choose another template.</span></div> : null}
    {templates.length === 0 ? <div className="empty-state">No output templates are available. Create one, or restore the starter templates.</div> : <div className="template-layout">
      <nav aria-label="Output template list" className="template-list">{outputTypes.map((outputType) => {
        const matching = templates.filter((template) => (template.output_type || "unavailable") === outputType);
        const defaultTemplate = matching.find((template) => template.is_default);
        return <section className="template-group" key={outputType}><div className="template-group__title"><h3>{titleCase(outputType)}</h3><span>{defaultTemplate ? `Default: ${defaultTemplate.name}` : "No selected default"}</span></div>{matching.map((template) => <button aria-pressed={template.template_id === selectedTemplateId} className={`template-row ${template.template_id === selectedTemplateId ? "selected" : ""}`} disabled={busy || !!pending} key={template.template_id} onClick={() => choose(template)} type="button"><span><strong>{template.name}</strong><small>{template.template_id} · version {template.revision || "unavailable"}</small></span><span className={`state-label ${isUnavailable(template) ? "state-failure" : template.is_default ? "state-healthy" : "state-agent"}`}>{isUnavailable(template) ? titleCase(template.status || "disabled") : template.is_default ? "Default" : "Available"}</span></button>)}</section>;
      })}</nav>
      <div className="template-detail">{selected ? <>
        <div className="template-detail__head"><div><div className="record-meta">{selected.output_type || "Output type unavailable"}</div><h3>{selected.name}</h3><p><span className="mono">{selected.template_id}</span> · version <span className="mono">{selected.revision || "unavailable"}</span></p></div><span className={`state-label ${isUnavailable(selected) ? "state-failure" : "state-healthy"}`}>{isUnavailable(selected) ? titleCase(selected.status || "unavailable") : "Available"}</span></div>
        {isUnavailable(selected) ? <p className="template-failure" role="alert">{selected.failure_detail || "This template is disabled or unavailable. Edit it before use."}</p> : null}
        <p className="reading template-summary">{selected.purpose || selected.instructions || "No purpose or instructions are saved."}</p>
        <details><summary>Current version and history</summary><p>Active file: <span className="mono">{selected.path}</span></p><p>Content hash: <span className="mono">{selected.content_hash || "unavailable"}</span></p><p>Immutable revision: <span className="mono">{selected.revision_path || "Created when this version is used or saved"}</span></p></details>
        <div className="btn-row template-actions"><button className="btn" disabled={busy} onClick={() => onEdit(selected)} type="button">Edit or rename</button><button className="btn" disabled={busy || !!pending || isUnavailable(selected)} onClick={() => void act("copy")} type="button">{pending === "copy" ? "Copying…" : "Make a copy"}</button><button className="btn" disabled={busy || !!pending || isUnavailable(selected) || selected.is_default} onClick={() => void act("default")} type="button">{pending === "default" ? "Saving default…" : selected.is_default ? "Current default" : "Set as default"}</button></div>
        <fieldset className="preview-overrides"><legend>Only for this preview</legend><p>These values do not change the reusable template.</p><div className="preview-grid">{(["audience", "purpose", "tone", "length"] as const).map((field) => <label key={field}><span>{titleCase(field)}</span><input className="text-input" onChange={(event) => setOverrides((current) => ({ ...current, [field]: event.target.value }))} value={overrides[field] ?? ""} /></label>)}</div><label><span>Extra instruction for this preview</span><textarea className="text-input prose" onChange={(event) => setOverrides((current) => ({ ...current, instruction: event.target.value }))} rows={3} value={overrides.instruction ?? ""} /></label><button className="btn agent" disabled={busy || !!pending || isUnavailable(selected)} onClick={() => void act("preview")} type="button">{pending === "preview" ? "Generating preview…" : "Preview with this matter"}</button></fieldset>
        {error ? <p className="error" role="alert">{error}</p> : null}{notice ? <p className={noticeFailed ? "template-action-failure" : "template-notice"} role="status">{notice}</p> : null}
        {preview ? (() => { const state = previewState(preview); return <div className="preview-result"><div><span className={`state-label ${state.className}`}>{state.label}</span><strong>{preview.artifact?.title || "Preview request"}</strong></div><p>Status: {preview.state}</p>{preview.artifact ? <><p>Version {preview.artifact.revision}</p>{onOpenArtifact ? <button className="btn quiet" onClick={() => onOpenArtifact(preview.artifact!.path)} type="button">Open editable preview</button> : null}</> : null}<p>{state.detail}</p></div>; })() : null}
      </> : <div className="empty-state">Select a template to inspect, copy, edit, set as a default, or preview.</div>}</div>
    </div>}
  </section>;
}

frontend/components/workspace/InquiryAct:
"use client";

import { useRef, useState } from "react";
import type { InquiryActionsProps, WorkspaceAction } from "@/lib/workspaceTypes";
import type { ContinuityInquiryActionsProps } from "@/lib/continuityTypes";
import styles from "./MatterExplore.module.css";

const labels: Record<WorkspaceAction, string> = {
  explain: "Explain",
  stress_test: "Stress-test",
  ask_business: "Ask the business",
  explore_question: "Explore question",
};

const descriptions: Record<WorkspaceAction, string> = {
  explain: "Explain the selected issue or source in the current matter.",
  stress_test: "Look for a material objection or condition that could change the view.",
  ask_business: "Draft a focused question for the business. It is not sent.",
  explore_question: "Explore an open question without changing facts or decisions.",
};
type Notice = { tone: "healthy" | "agent" | "attention" | "failure"; word: string; message: string };

function actionNotice(state: string): Notice {
  if (state === "saved") return { tone: "healthy", word: "Saved", message: "The inquiry was saved in the existing conversation." };
  if (state === "proposed") return { tone: "attention", word: "Proposed", message: "The inquiry is not applied." };
  if (state === "failed" || state === "not_saved") return { tone: "failure", word: "Not saved", message: `Inquiry ${state}.` };
  return { tone: "agent", word: state === "queued" ? "Queued" : "Working", message: `Inquiry ${state}.` };
}

function targetLabel(target: InquiryActionsProps["target"]) {
  if (target.scenario_id) return "Saved scenario";
  if (target.artifact_path) return target.artifact_path.split("/").at(-1) || "Selected document";
  if (target.source_id) return "Selected source";
  if (target.issue_id) return "Selected issue";
  return "This matter";
}

export default function InquiryActions({ target, busy = false, onAction, onFactRequest, onHandoff, onCompareSources }: ContinuityInquiryActionsProps) {
  const [instruction, setInstruction] = useState("");
  const [selectedAction, setSelectedAction] = useState<WorkspaceAction>("explain");
  const [pending, setPending] = useState<WorkspaceAction | null>(null);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [error, setError] = useState("");
  const actionKey = useRef({ signature: "", key: "" });
  const contextualAction = [
    onFactRequest ? { label: "Request a fact", onClick: onFactRequest } : null,
    onHandoff ? { label: "Hand off work", onClick: onHandoff } : null,
    onCompareSources ? { label: "Compare a source", onClick: onCompareSources } : null,
  ].find(Boolean);

  function stableKey(action: WorkspaceAction, text: string) {
    const signature = JSON.stringify({ action, text, target });
    if (actionKey.current.signature !== signature) actionKey.current = { signature, key: `workspace-action:${crypto.randomUUID()}` };
    return actionKey.current.key;
  }

  async function run(action: WorkspaceAction) {
    setSelectedAction(action); setPending(action); setError(""); setNotice(null);
    try {
      const result = await onAction({ action, instruction: instruction.trim(), target, source_action_key: stableKey(action, instruction.trim()) });
      setNotice(actionNotice(result.state));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The inquiry did not complete. Your question is retained for retry.");
    } finally { setPending(null); }
  }

  async function copyQuestion() {
    if (!instruction.trim()) { setError("Write a question before copying it."); return; }
    try {
      await navigator.clipboard.writeText(instruction.trim());
      setNotice({ tone: "agent", word: "Copied", message: "Question copied." }); setError("");
    } catch {
      setError("The question could not be copied. Select the text and copy it manually.");
    }
  }

  return <section aria-labelledby="inquiry-actions-title" className={`${styles.inquiryActions} inquiry-actions`}>
    <div className="inquiry-actions__header"><div><p className="eyebrow">Explore</p><h2 id="inquiry-actions-title">Ask about {targetLabel(target)}</h2></div><span className="state-agent">Agent work</span></div>
    <p className="inquiry-actions__intro">These shortcuts use the same saved conversation and matter context. They do not start a separate assistant or history.</p>
    {notice ? <p className={`inquiry-actions__state inquiry-actions__state--${notice.tone}`} role="status">{notice.word}: {notice.message}</p> : null}
    {error ? <p className="inquiry-actions__state inquiry-actions__state--failure" role="alert">Failed: {error}</p> : null}
    <fieldset className="inquiry-actions__choices" disabled={busy || pending !== null}>
      <legend className="sr-only">Inquiry type</legend>
      {(Object.keys(labels) as WorkspaceAction[]).map((action) => <label key={action}><input checked={selectedAction === action} name="inquiry-action" onChange={() => setSelectedAction(action)} type="radio" value={action} />{labels[action]}</label>)}
    </fieldset>
    <label className="label" htmlFor="inquiry-question">Question or instruction</label>
    <textarea id="inquiry-question" className="text-input prose" value={instruction} onChange={(event) => setInstruction(event.target.value)} placeholder="What would change if the funds remained in the account for two days?" />
    <div className="inquiry-actions__buttons" aria-label="Inquiry actions"><button className="btn agent" type="button" title={descriptions[selectedAction]} onClick={() => void run(selectedAction)} disabled={busy || pending !== null}>{pending === selectedAction ? `${labels[selectedAction]}…` : "Start inquiry"}</button><button className="btn quiet" type="button" onClick={() => void copyQuestion()} disabled={busy || pending !== null}>Copy question</button></div>
    {contextualAction ? <div className="inquiry-actions__context"><span className="small muted">More matter actions</span><button className="btn quiet tiny" onClick={contextualAction.onClick} type="button">{contextualAction.label}</button></div> : null}
    <p className="small muted">Selected action: {labels[selectedAction]}. {descriptions[selectedAction]}</p>
  </section>;
}

frontend/components/workspace/ClaimMarkd:
"use client";

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import type { MouseEvent, ReactNode } from "react";
import type { ClaimEvidence, DocumentIdentity, DocumentReferenceTarget, ReferenceOrigin, WorkspaceClaim } from "@/lib/workspaceTypes";
import { isSafeDocumentPath } from "@/lib/documentNavigation";
import styles from "./MatterDocuments.module.css";

const SOURCE_MARKER = /\[source:([^\]|;\s]+)(?:\|([^\]]+))?\]/g;
const TRANSPORT = /```claim-support[ \t]*\n([\s\S]*?)\n```[ \t]*(?:\n|$)/g;

export function visibleClaimProse(text: string): string {
  const visible = text.replace(TRANSPORT, (block, payload: string) => {
    try {
      const parsed = JSON.parse(payload);
      return parsed && typeof parsed === "object" && Array.isArray(parsed.claims) ? "" : block;
    } catch { return block; }
  }).trimEnd();
  return visible.trim() ? visible : text.trimEnd();
}

export function evidenceForSourceMarker(claims: WorkspaceClaim[], sourceId: string, locator?: string | null): ClaimEvidence | null {
  const normalizedLocator = locator?.trim() || null;
  const matches = claims.flatMap((claim) => claim.evidence.map((evidence) => ({ claim, evidence }))).filter(({ claim, evidence }) =>
    evidence.source_id === sourceId
    && (!normalizedLocator || evidence.locator?.trim() === normalizedLocator)
    && (!evidence.output_revision || !claim.output_revision || evidence.output_revision === claim.output_revision)
    && (!evidence.claim_revision || !claim.claim_revision || evidence.claim_revision === claim.claim_revision));
  return matches.length === 1 ? matches[0].evidence : null;
}

export function claimsForRenderedText(claims: WorkspaceClaim[], text: string): WorkspaceClaim[] {
  const prose = visibleClaimProse(text);
  return claims.filter((claim) => {
    const statement = claim.text?.trim();
    return Boolean(statement && prose.includes(statement));
  });
}

export function sourceForMarker(claims: WorkspaceClaim[], sourceId: string): ClaimEvidence | null {
  const matches = claims.flatMap((claim) => claim.evidence.map((evidence) => ({ claim, evidence }))).filter(({ claim, evidence }) =>
    evidence.source_id === sourceId
    && (!evidence.output_revision || !claim.output_revision || evidence.output_revision === claim.output_revision)
    && (!evidence.claim_revision || !claim.claim_revision || evidence.claim_revision === claim.claim_revision));
  const sources = new Map<string, ClaimEvidence[]>();
  for (const { evidence } of matches) {
    const key = `${evidence.source_id}\u0000${evidence.path ?? ""}\u0000${evidence.url ?? ""}`;
    sources.set(key, [...(sources.get(key) ?? []), evidence]);
  }
  if (sources.size !== 1) return null;
  const sourceEvidence = [...sources.values()][0];
  const evidence = sourceEvidence[0];
  const versions = new Set(sourceEvidence.map((item) => item.source_version).filter(Boolean));
  return {
      claim_id: `source:${evidence.source_id}`,
      source_id: evidence.source_id,
      source_label: evidence.source_label,
      path: evidence.path,
      url: evidence.url,
      source_version: versions.size === 1 ? evidence.source_version : null,
      support_state: evidence.support_state,
  };
}

function safeDecodePath(href: string): string | null {
  try { return decodeURIComponent(href.replace(/^\.\//, "")); }
  catch { return null; }
}

function safePublicUrl(value: string): boolean {
  try { return ["http:", "https:", "mailto:"].includes(new URL(value).protocol); }
  catch { return false; }
}

function origin(surface: ReferenceOrigin["surface"], recordId?: string | null): ReferenceOrigin {
  return { surface, record_id: recordId ?? null, focus_id: typeof document === "undefined" ? null : document.activeElement instanceof HTMLElement ? document.activeElement.id || null : null, scroll_offset: typeof window === "undefined" ? null : window.scrollY };
}

export interface ClaimMarkdownProps {
  text: string;
  claims?: WorkspaceClaim[];
  documents?: DocumentIdentity[];
  surface?: ReferenceOrigin["surface"];
  recordId?: string | null;
  className?: string;
  onOpenEvidence?: (evidence: ClaimEvidence) => void;
  onOpenDocument?: (target: DocumentReferenceTarget) => void;
}

/** Render saved prose and resolve each source marker by source, locator, and claim revision. */
export default function ClaimMarkdown({ text, claims = [], documents = [], surface = "document", recordId, className, onOpenEvidence, onOpenDocument }: ClaimMarkdownProps) {
  const markers: Array<{ label: string; evidence: ClaimEvidence | null; exact: boolean }> = [];
  const renderedClaims = claimsForRenderedText(claims, text);
  const markdown = visibleClaimProse(text).replace(SOURCE_MARKER, (_marker, sourceId: string, locator?: string) => {
    const normalizedLocator = locator?.trim() || null;
    const exact = evidenceForSourceMarker(renderedClaims, sourceId, normalizedLocator);
    const evidence = exact ?? sourceForMarker(claims, sourceId);
    const index = markers.push({ label: normalizedLocator ? `${sourceId} · ${normalizedLocator}` : sourceId, evidence, exact: Boolean(exact) }) - 1;
    return `[${normalizedLocator ? `Source: ${sourceId} · ${normalizedLocator}` : `Source: ${sourceId}`}](#themis-source-${index})`;
  });

  function openInternal(event: MouseEvent<HTMLAnchorElement>, href: string) {
    const decoded = safeDecodePath(href);
    if (!decoded) return;
    const match = documents.find((item) => item.path === decoded);
    if (!match || !onOpenDocument || !isSafeDocumentPath(match.path)) return;
    event.preventDefault();
    onOpenDocument({ document_id: match.document_id, path: match.path, revision: match.revision, origin: origin(surface, recordId) });
  }

  return <div className={[styles.claim, className].filter(Boolean).join(" ")}><ReactMarkdown remarkPlugins={[remarkGfm]} components={{
    a: ({ href = "", children }) => {
      const marker = href.match(/^#themis-source-(\d+)$/);
      if (marker) {
        const item = markers[Number(marker[1])];
        return <button className="claim-source-link" disabled={!item?.evidence || !onOpenEvidence} onClick={() => item?.evidence && onOpenEvidence?.(item.evidence)} title={item?.exact ? "Review this saved passage" : item?.evidence ? "Open the saved source; no unique passage is selected" : "The saved source is unavailable"} type="button">{children}{item?.exact ? null : item?.evidence ? " · source" : " · unavailable"}</button>;
      }
      if (safePublicUrl(href)) return <a href={href} rel="noreferrer" target="_blank">{children}</a>;
      const decoded = safeDecodePath(href);
      const internal = decoded !== null && documents.some((item) => item.path === decoded);
      if (internal) return <a href={href} onClick={(event) => openInternal(event, href)}>{children}</a>;
      return <span title="Unsafe or unavailable link">{children}</span>;
    },
    table: ({ children }: { children?: ReactNode }) => <div className="claim-table-scroll"><table>{children}</table></div>,
  }}>{markdown}</ReactMarkdown></div>;
}

frontend/components/workspace/DocumentTa:
"use client";

import type { DocumentIdentity, DocumentTabsProps, LocalEditorSnapshot } from "@/lib/workspaceTypes";
import { lifecycleLabel } from "./DocumentNavigator";
import styles from "./MatterDocuments.module.css";

const VISIBLE_TAB_LIMIT = 4;
export function visibleDocumentTabs(documents: readonly DocumentIdentity[], activeDocumentId: string | null, limit = VISIBLE_TAB_LIMIT): { visible: DocumentIdentity[]; overflow: DocumentIdentity[] } {
  if (documents.length <= limit) return { visible: [...documents], overflow: [] };
  const visible = documents.slice(0, limit);
  const active = documents.find((document) => document.document_id === activeDocumentId);
  if (active && !visible.some((document) => document.document_id === active.document_id)) visible[limit - 1] = active;
  const visibleIds = new Set(visible.map((document) => document.document_id));
  return { visible, overflow: documents.filter((document) => !visibleIds.has(document.document_id)) };
}

function hasDirtyEdit(document: DocumentIdentity, localEdits: Record<string, LocalEditorSnapshot>): boolean {
  return Boolean(localEdits[document.document_id]?.dirty);
}

function OpenTab({ document, activeDocumentId, localEdits, onSelect, onClose, onDiscardLocalEdit }: { document: DocumentIdentity; activeDocumentId: string | null; localEdits: Record<string, LocalEditorSnapshot>; onSelect: DocumentTabsProps["onSelect"]; onClose: DocumentTabsProps["onClose"]; onDiscardLocalEdit: DocumentTabsProps["onDiscardLocalEdit"] }) {
  const dirty = hasDirtyEdit(document, localEdits);
  return <div className={`${styles.tab} ${document.document_id === activeDocumentId ? styles.tabActive : ""}`}>
    <button aria-current={document.document_id === activeDocumentId ? "page" : undefined} className={`btn quiet tiny ${styles.tabButton}`} type="button" onClick={() => onSelect(document.document_id)}><strong>{document.title}</strong><span className={styles.tabMeta}>{lifecycleLabel(document)}{dirty ? <span className={styles.tabDirty}>· Unsaved</span> : " · Saved"}</span></button>
    <button aria-label={`Close ${document.title}. ${dirty ? "Local edits will be retained." : ""}`} className="btn quiet tiny" type="button" onClick={() => onClose(document.document_id)}>Close</button>
    {dirty ? <button className={`btn quiet tiny ${styles.tabButton} ${styles.tabDiscard}`} type="button" onClick={() => onDiscardLocalEdit(document.document_id)}>Discard local edits</button> : null}
  </div>;
}

export default function DocumentTabs({ documents, activeDocumentId, localEdits, onSelect, onClose, onDiscardLocalEdit }: DocumentTabsProps) {
  const { visible, overflow } = visibleDocumentTabs(documents, activeDocumentId);
  if (!documents.length) return <p className={styles.emptyTabs}>No documents are open.</p>;
  return <nav aria-label="Open documents" className={styles.tabs}>
    {visible.map((document) => <OpenTab activeDocumentId={activeDocumentId} document={document} key={document.document_id} localEdits={localEdits} onClose={onClose} onDiscardLocalEdit={onDiscardLocalEdit} onSelect={onSelect} />)}
    {overflow.length ? <details className={styles.tabOverflow}><summary className="btn quiet tiny">More open documents ({overflow.length})</summary><div className={styles.tabOverflowList}>{overflow.map((document) => <OpenTab activeDocumentId={activeDocumentId} document={document} key={document.document_id} localEdits={localEdits} onClose={onClose} onDiscardLocalEdit={onDiscardLocalEdit} onSelect={onSelect} />)}</div></details> : null}
  </nav>;
}

