"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import type { InteractionReceipt, WorkspaceClaim, Scenario, ScenarioAdoptCommand, ScenarioAnalyzeCommand, ScenarioCreateCommand, ScenarioFactChange, ScenarioInteractionProps, ScenarioPanelProps, WorkspaceActionResult } from "@/lib/workspaceTypes";
import styles from "./MatterExplore.module.css";

const keyFor = (prefix: string) => `${prefix}:${crypto.randomUUID()}`;
type Notice = { tone: "healthy" | "agent" | "attention" | "failure"; word: string; message: string };
const LONG_ANALYSIS_CHARACTER_LIMIT = 1200;

function longAnalysisPreview(analysis: string) {
  if (analysis.length <= LONG_ANALYSIS_CHARACTER_LIMIT) return analysis;
  if (/!?\[[^\]]+\]\[[^\]]*\]|^\s*\[[^\]]+\]:/m.test(analysis)) return analysis;
  let fence: { character: string; length: number } | null = null;
  let position = 0;
  let previewEnd = 0;
  for (const line of analysis.split(/(?<=\n)/)) {
    position += line.length;
    const marker = line.match(/^\s*(`{3,}|~{3,})/);
    if (marker) {
      const nextFence = marker[1];
      if (!fence) fence = { character: nextFence[0], length: nextFence.length };
      else if (fence.character === nextFence[0] && nextFence.length >= fence.length) fence = null;
    }
    if (!fence && /^\s*\n$/.test(line) && position <= LONG_ANALYSIS_CHARACTER_LIMIT) previewEnd = position;
  }
  return previewEnd ? analysis.slice(0, previewEnd).trimEnd() : analysis;
}

const analysisMarkdownComponents = {
  table: ({ children }: { children?: ReactNode }) => <div className="scenario-analysis__table"><table>{children}</table></div>,
  pre: ({ children }: { children?: ReactNode }) => <pre className="scenario-analysis__code">{children}</pre>,
};

function hasScenarioCitations(claimIds: string[], claims: WorkspaceClaim[]) {
  return claimIds.some((id) => {
    const matches = claims.filter((claim) => claim.claim_id === id);
    return matches.length === 1 && matches[0].evidence.some((item) =>
      Boolean(item.available_excerpt && item.source_id && (item.path || item.url)));
  });
}

function staleDetails(scenario: Scenario, current: Record<string, string>) {
  const paths = new Set([...Object.keys(scenario.baseline_revisions), ...Object.keys(current)]);
  return [...paths].filter((path) => scenario.baseline_revisions[path] !== current[path]);
}

function receiptNotice(receipt: InteractionReceipt, saved: string): Notice {
  if (receipt.state === "applied") return { tone: "healthy", word: "Saved", message: saved };
  if (receipt.state === "proposed") return { tone: "attention", word: "Proposed", message: "It is not applied." };
  return { tone: "failure", word: "Not saved", message: receipt.failure_detail || "The change was not saved." };
}

function actionNotice(state: string, saved: string): Notice {
  if (state === "saved") return { tone: "healthy", word: "Saved", message: saved };
  if (state === "proposed") return { tone: "attention", word: "Proposed", message: "It is not applied." };
  if (state === "failed" || state === "not_saved") return { tone: "failure", word: "Not saved", message: `Analysis ${state}.` };
  return { tone: "agent", word: state === "queued" ? "Queued" : "Working", message: `Analysis ${state}.` };
}

function hasCompleteBaseline(scenario: Scenario, current: Record<string, string>) {
  return Object.keys(scenario.baseline_revisions).length > 0 && staleDetails(scenario, current).length === 0;
}

function sourceLabel(path: string) {
  try { const url = new URL(path); return `${url.hostname}${url.pathname === "/" ? "" : url.pathname}`; } catch { return path.split("/").at(-1)?.replaceAll("_", " ") || path; }
}

function isExternalSource(path: string) { return /^https?:\/\//i.test(path); }
function isInternalSource(path: string) {
  return Boolean(path.trim()) && !/^[a-z][a-z0-9+.-]*:/i.test(path) && !path.includes("\\") && !path.split("/").includes("..");
}

type ScenarioPanelInteractionProps = Omit<ScenarioPanelProps, "onCreate" | "onAnalyze" | "onAdopt"> & {
  initialIssueId?: ScenarioInteractionProps["initialIssueId"];
  initialFactId?: ScenarioInteractionProps["initialFactId"];
  onCreate: (command: ScenarioCreateCommand) => Promise<Scenario>;
  onAnalyze: ((scenarioId: string, command: ScenarioAnalyzeCommand) => Promise<WorkspaceActionResult>)
    | ScenarioPanelProps["onAnalyze"];
  onAdopt: ((scenarioId: string, command: ScenarioAdoptCommand) => Promise<InteractionReceipt>)
    | ScenarioPanelProps["onAdopt"];
  onOpenClaim?: ScenarioInteractionProps["onOpenClaim"];
  onOpenDocument?: ScenarioInteractionProps["onOpenDocument"];
  /** C6 supplies the existing POST /scenarios update wrapper for naming an analyzed baseline. */
  onSaveScenario?: (scenario: Scenario, title: string, expectedRevision: string, sourceActionKey: string) => Promise<Scenario>;
};

function scenarioFactChanges(changesText: string, hypotheticalFactId: string, sourceKey: string): ScenarioFactChange[] {
  return changesText.split("\n").map((text) => text.trim()).filter(Boolean)
    .map((text, index) => ({ change_id: `change-${index + 1}-${sourceKey}`, fact_id: hypotheticalFactId || null, text }));
}

async function runScenarioAnalysis(input: {
  selected: Scenario | null;
  createNew: boolean;
  changesText: string;
  hypotheticalFactId: string;
  currentRevisions: Record<string, string>;
  facts: Array<{ fact_id: string; text: string }>;
  initialIssueId?: string | null;
  instruction: string;
  getCreateSourceKey: () => string;
  getAnalysisSourceKey: (target: Scenario) => string;
  onCreate: ScenarioPanelInteractionProps["onCreate"];
  onAnalyze: ScenarioPanelInteractionProps["onAnalyze"];
  onSelect: ScenarioPanelInteractionProps["onSelect"];
}): Promise<{ target: Scenario; result: WorkspaceActionResult }> {
  let target = input.createNew ? null : input.selected;
  if (!target) {
    const createSourceKey = input.getCreateSourceKey();
    const factLabel = input.facts.find((fact) => fact.fact_id === input.hypotheticalFactId)?.text;
    target = await input.onCreate({
      title: `Working scenario — ${(factLabel || input.changesText.trim().split("\n")[0]).slice(0, 80)}`,
      baseline_revisions: input.currentRevisions,
      issue_ids: input.initialIssueId ? [input.initialIssueId] : [],
      proposed_fact_changes: scenarioFactChanges(input.changesText, input.hypotheticalFactId, createSourceKey),
      source_action_key: createSourceKey,
    });
    input.onSelect(target.scenario_id);
  }
  const sourceActionKey = input.getAnalysisSourceKey(target);
  const command: ScenarioAnalyzeCommand = { instruction: input.instruction, expected_scenario_revision: target.revision ?? "", baseline_revisions: { ...target.baseline_revisions }, source_action_key: sourceActionKey };
  // Legacy seam: onAnalyze(selected.scenario_id, analysisInstruction.trim(), sourceActionKey).
  const result = input.onAnalyze.length >= 3
    ? await (input.onAnalyze as ScenarioPanelProps["onAnalyze"])(target.scenario_id, command.instruction, command.source_action_key)
    : await (input.onAnalyze as ScenarioInteractionProps["onAnalyze"])(target.scenario_id, command);
  return { target, result };
}

export default function ScenarioPanel({
  scenarios,
  selectedScenarioId,
  currentRevisions,
  busy = false,
  error,
  onSelect,
  onCreate,
  onAnalyze,
  onAdopt,
  onCorrectFact,
  onOpenArtifact,
  onOpenClaim,
  facts = [],
  claims = [],
  initialIssueId,
  initialFactId,
  onSaveScenario,
}: ScenarioPanelInteractionProps) {
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState("");
  const [changesText, setChangesText] = useState("");
  const [hypotheticalFactId, setHypotheticalFactId] = useState(initialFactId ?? "");
  const [analysisInstruction, setAnalysisInstruction] = useState("");
  const [expandedAnalysisId, setExpandedAnalysisId] = useState<string | null>(null);
  const [selectedChanges, setSelectedChanges] = useState<string[]>([]);
  const [correctionFactId, setCorrectionFactId] = useState("");
  const [correctionText, setCorrectionText] = useState("");
  const [notice, setNotice] = useState<Notice | null>(null);
  const [localError, setLocalError] = useState("");
  const [pending, setPending] = useState<"create" | "analyze" | "adopt" | "correct" | null>(null);
  const createKey = useRef({ signature: "", key: "" });
  const analysisKey = useRef({ signature: "", key: "" });
  const adoptionKey = useRef({ signature: "", key: "" });
  const correctionKey = useRef({ signature: "", key: "" });
  const saveNameKey = useRef({ signature: "", key: "" });
  const analysisGeneration = useRef(0);
  const [correctionRevisions, setCorrectionRevisions] = useState<Record<string, string> | null>(null);

  const selected = useMemo(
    () => scenarios.find((scenario) => scenario.scenario_id === selectedScenarioId) ?? null,
    [scenarios, selectedScenarioId],
  );
  const selectedStale = selected ? staleDetails(selected, currentRevisions) : [];
  const savedAnalysis = selected?.analysis ?? "";
  const analysisExpanded = selected?.scenario_id === expandedAnalysisId;
  const analysisIsLong = savedAnalysis.length > LONG_ANALYSIS_CHARACTER_LIMIT;
  const visibleAnalysis = analysisExpanded || !analysisIsLong ? savedAnalysis : longAnalysisPreview(savedAnalysis);
  const previewIsOneLongBlock = analysisIsLong && !analysisExpanded && visibleAnalysis === savedAnalysis;
  const savedAnalysisId = useId();
  const correctionStale = correctionRevisions && JSON.stringify(correctionRevisions) !== JSON.stringify(currentRevisions);
  const locked = busy || pending !== null;

  useEffect(() => {
    if (initialFactId === undefined) return;
    analysisGeneration.current += 1;
    setCreating(true);
    setHypotheticalFactId(initialFactId ?? "");
    setSelectedChanges([]);
    setExpandedAnalysisId(null);
    onSelect(null);
  }, [initialFactId, initialIssueId, onSelect]);

  const makeStableKey = (ref: { current: { signature: string; key: string } }, prefix: string, signature: string) => {
    if (ref.current.signature !== signature) ref.current = { signature, key: keyFor(prefix) };
    return ref.current.key;
  };

  function toggleNewScenario() {
    if (creating) {
      setCreating(false);
      return;
    }
    analysisGeneration.current += 1;
    setSelectedChanges([]);
    setExpandedAnalysisId(null);
    setLocalError("");
    onSelect(null);
    setCreating(true);
  }

  async function analyzeScenario() {
    if (!analysisInstruction.trim()) {
      setLocalError("Describe the question to explore before analysis starts.");
      return;
    }
    const selectedForAnalysis = creating ? null : selected;
    if (!selectedForAnalysis && !changesText.trim()) {
      setLocalError("Enter at least one hypothetical fact before analysis starts.");
      return;
    }
    setPending("analyze"); setLocalError(""); setNotice(null);
    const generation = ++analysisGeneration.current;
    try {
      const { result } = await runScenarioAnalysis({
        selected: selectedForAnalysis,
        createNew: creating,
        changesText,
        hypotheticalFactId,
        currentRevisions,
        facts,
        initialIssueId,
        instruction: analysisInstruction.trim(),
        getCreateSourceKey: () => {
          const signature = `baseline:${hypotheticalFactId}:${changesText.trim()}:${JSON.stringify(currentRevisions)}`;
          return makeStableKey(createKey, "scenario-baseline", signature);
        },
        getAnalysisSourceKey: (target) => {
          const signature = `${target.scenario_id}:${target.revision ?? ""}:${analysisInstruction.trim()}:${JSON.stringify(target.baseline_revisions)}`;
          return makeStableKey(analysisKey, "scenario-analysis", signature);
        },
        onCreate,
        onAnalyze,
        onSelect,
      });
      if (generation === analysisGeneration.current) setNotice(actionNotice(result.state, "Scenario analysis saved against its original baseline."));
    } catch (cause) {
      if (generation === analysisGeneration.current) setLocalError(cause instanceof Error ? cause.message : "Analysis did not complete. Your question is retained for retry.");
    } finally { if (generation === analysisGeneration.current) setPending(null); }
  }

  async function adoptSelected() {
    if (!selected || !selectedChanges.length) {
      setLocalError("Choose the specific scenario facts to adopt.");
      return;
    }
    setPending("adopt"); setLocalError(""); setNotice(null);
    const signature = `${selected.scenario_id}:${selectedChanges.slice().sort().join(",")}:${JSON.stringify(currentRevisions)}`;
    try {
      const command: ScenarioAdoptCommand = { change_ids: selectedChanges, expected_revisions: { ...currentRevisions }, source_action_key: makeStableKey(adoptionKey, "scenario-adopt", signature) };
      // Legacy seam: onAdopt(selected.scenario_id, selectedChanges, currentRevisions, sourceActionKey).
      const receipt = onAdopt.length >= 4
        ? await (onAdopt as ScenarioPanelProps["onAdopt"])(selected.scenario_id, command.change_ids, command.expected_revisions, command.source_action_key)
        : await (onAdopt as ScenarioInteractionProps["onAdopt"])(selected.scenario_id, command);
      const nextNotice = receiptNotice(receipt, "Selected facts were applied. The saved scenario remains historical.");
      setNotice(nextNotice);
      if (receipt.state === "applied") setSelectedChanges([]);
    } catch (cause) {
      setLocalError(cause instanceof Error ? cause.message : "The selected facts were not adopted. Your selection is retained.");
    } finally { setPending(null); }
  }

  async function saveScenarioName() {
    if (!selected || !title.trim()) {
      setLocalError("Add a name for this scenario.");
      return;
    }
    if (!onSaveScenario) {
      setLocalError("Saving a name is not connected yet. The analyzed baseline is still available.");
      return;
    }
    setPending("create"); setLocalError(""); setNotice(null);
    const signature = `${selected.scenario_id}:${selected.revision ?? ""}:${title.trim()}`;
    try {
      const saved = await onSaveScenario(selected, title.trim(), selected.revision ?? "", makeStableKey(saveNameKey, "scenario-name", signature));
      onSelect(saved.scenario_id);
      setTitle("");
      setNotice({ tone: "healthy", word: "Saved", message: "Named scenario saved. Actual matter facts and decisions are unchanged." });
    } catch (cause) {
      setLocalError(cause instanceof Error ? cause.message : "The scenario name was not saved. Your name is retained.");
    } finally { setPending(null); }
  }

  async function correctFact() {
    if (!onCorrectFact) {
      setLocalError("Fact correction is not connected yet.");
      return;
    }
    if (!correctionText.trim()) {
      setLocalError("Enter the corrected fact.");
      return;
    }
    setPending("correct"); setLocalError(""); setNotice(null);
    const expectedRevisions = correctionRevisions ?? currentRevisions;
    const signature = `${correctionFactId}:${correctionText.trim()}:${JSON.stringify(expectedRevisions)}`;
    try {
      const receipt = await onCorrectFact({
        factId: correctionFactId.trim() || null,
        replacement: correctionText.trim(),
        expectedRevisions,
        sourceActionKey: makeStableKey(correctionKey, "fact-correction", signature),
      });
      setNotice(receiptNotice(receipt, "Fact corrected. This did not change a saved scenario or draft."));
      if (receipt.state === "applied") { setCorrectionFactId(""); setCorrectionText(""); setCorrectionRevisions(null); }
    } catch (cause) {
      setLocalError(cause instanceof Error ? cause.message : "The fact was not corrected. Your text is retained.");
    } finally { setPending(null); }
  }

  return (
    <section aria-labelledby="scenario-title" className={`${styles.scenarioPanel} exploration-panel`}>
      <div className="exploration-panel__header">
        <div><p className="eyebrow">Explore</p><h2 id="scenario-title">Saved scenarios</h2></div>
        <button className="btn agent compact" type="button" onClick={toggleNewScenario} aria-expanded={creating} disabled={locked}>Try a different assumption</button>
      </div>
      <p className="exploration-panel__intro">A scenario tests changed assumptions. It does not change actual facts, decisions, or drafts.</p>
      {error ? <p className="exploration-state exploration-state--failure" role="status">Failed: {error}</p> : null}
      {notice ? <p className={`exploration-state exploration-state--${notice.tone}`} role="status">{notice.word}: {notice.message}</p> : null}
      {localError ? <p className="exploration-state exploration-state--failure" role="alert">Failed: {localError}</p> : null}

      {creating ? <div className="exploration-form wash-agent">
        <label className="label" htmlFor="scenario-fact">Current reported fact</label>
        <select className="select-input" id="scenario-fact" value={hypotheticalFactId} onChange={(event) => setHypotheticalFactId(event.target.value)} disabled={locked}><option value="">No linked fact</option>{facts.map((fact) => <option key={fact.fact_id} value={fact.fact_id}>{fact.text}</option>)}</select>
        {hypotheticalFactId ? <p className="small muted">Current: {facts.find((fact) => fact.fact_id === hypotheticalFactId)?.text}</p> : null}
        <label className="label" htmlFor="scenario-changes">Hypothetical value, one change per line</label>
        <textarea className="text-input prose" id="scenario-changes" value={changesText} onChange={(event) => setChangesText(event.target.value)} placeholder="Funds remain in the account for two days" disabled={locked} />
        <label className="label" htmlFor="new-scenario-analysis">Question for the analysis</label>
        <textarea className="text-input" id="new-scenario-analysis" value={analysisInstruction} onChange={(event) => setAnalysisInstruction(event.target.value)} placeholder="How would this change the current analysis?" disabled={locked} />
        <p className="small muted">Analyze creates a temporary baseline record. It does not save a named user scenario. Actual matter facts are unchanged.</p>
        <div className="btn-row"><button className="btn agent" type="button" onClick={() => void analyzeScenario()} disabled={locked}>{pending === "analyze" ? "Analyzing…" : "Analyze scenario"}</button><button className="btn quiet" type="button" onClick={() => setCreating(false)} disabled={locked}>Cancel</button></div>
      </div> : null}

      <div className="exploration-layout">
        <div className="scenario-list" aria-label="Saved scenarios">
          {scenarios.length ? scenarios.map((scenario) => {
            const stale = staleDetails(scenario, currentRevisions);
            const active = scenario.scenario_id === selectedScenarioId;
            const complete = hasCompleteBaseline(scenario, currentRevisions);
            return <button key={scenario.scenario_id} className={`scenario-list__item${active ? " is-selected" : ""}`} type="button" aria-pressed={active} disabled={locked} onClick={() => { analysisGeneration.current += 1; setSelectedChanges([]); setExpandedAnalysisId(null); onSelect(active ? null : scenario.scenario_id); }}>
              <span>{scenario.title}</span><small className={scenario.analysis_state === "failed" ? "state-failure" : complete && !scenario.stale?.is_stale ? "state-healthy" : "state-attention"}>{scenario.analysis_state === "failed" ? "Analysis failed" : scenario.stale?.is_stale || stale.length ? "Earlier baseline" : complete ? "Baseline complete" : "Baseline unavailable"}</small>
            </button>;
          }) : <p className="muted small">No saved scenarios. Try a changed assumption to keep the exploration available for later.</p>}
        </div>
        {selected ? <article className="scenario-detail">
          <div className="exploration-panel__header"><h3>{selected.title}</h3><span className={hasCompleteBaseline(selected, currentRevisions) ? "state-healthy" : "state-attention"}>{hasCompleteBaseline(selected, currentRevisions) ? "Baseline complete" : selectedStale.length ? "Baseline needs review" : "Baseline unavailable"}</span></div>
          <p className="small muted">Saved {selected.created_at}. {selectedStale.length ? `${selectedStale.length} source or fact revision${selectedStale.length === 1 ? " has" : "s have"} changed.` : hasCompleteBaseline(selected, currentRevisions) ? "The saved baseline matches the current matter." : "This scenario has no complete saved baseline."}</p>
          {selected.analysis_run_id ? <p className="record-meta">Run {selected.analysis_run_id}</p> : null}
          {selected.analysis_state ? <p className={`exploration-state exploration-state--${selected.analysis_state === "failed" ? "failure" : selected.analysis_state === "completed" ? "healthy" : "agent"}`}>{selected.analysis_state === "failed" ? "Failed" : selected.analysis_state === "completed" ? "Completed" : selected.analysis_state === "not_started" ? "Not analyzed" : selected.analysis_state === "queued" ? "Queued" : "Running"}: Hypothetical analysis{selected.failure_detail ? ` · ${selected.failure_detail}` : ""}</p> : null}
          <details><summary>Baseline revisions</summary><ul className="exploration-list">{Object.entries(selected.baseline_revisions).map(([path, revision]) => <li key={path}><code>{path}</code><span>{revision === currentRevisions[path] ? "Current" : "Changed"}</span></li>)}</ul></details>
          {selected.analysis_baseline_revisions && Object.keys(selected.analysis_baseline_revisions).length ? <details><summary>Analysis baseline</summary><ul className="exploration-list">{Object.entries(selected.analysis_baseline_revisions).map(([path, revision]) => <li key={path}><code>{path}</code><span>{revision === currentRevisions[path] ? "Current" : "Earlier version"}</span></li>)}</ul></details> : null}
          <h4>Current baseline facts</h4>
          {facts.length ? <ul className="exploration-list">{facts.map((fact) => <li key={fact.fact_id}><span>{fact.text}</span><code>{fact.fact_id}</code></li>)}</ul> : <p className="muted small">No current facts are available in this view.</p>}
          <h4>Changed assumptions</h4>
          {selected.proposed_fact_changes?.length ? <div className="scenario-facts">{selected.proposed_fact_changes.map((change) => <label className="checkbox-row" key={change.change_id}><input type="checkbox" checked={selectedChanges.includes(change.change_id)} disabled={locked} onChange={() => setSelectedChanges((current) => current.includes(change.change_id) ? current.filter((id) => id !== change.change_id) : [...current, change.change_id])} /><span>{change.text}</span></label>)}</div> : <p className="muted small">No changed assumptions were saved.</p>}
          <div className="exploration-form wash-agent"><label className="label" htmlFor="scenario-analysis">Explore this scenario</label><textarea className="text-input" id="scenario-analysis" value={analysisInstruction} onChange={(event) => setAnalysisInstruction(event.target.value)} placeholder="How would this affect the current answer?" disabled={locked} /><div className="btn-row"><button className="btn agent" type="button" onClick={() => void analyzeScenario()} disabled={locked}>{pending === "analyze" ? "Analyzing…" : "Analyze scenario"}</button><button className="btn review" type="button" onClick={() => void adoptSelected()} disabled={locked || !selectedChanges.length}>{pending === "adopt" ? "Adopting…" : "Adopt selected facts"}</button></div></div>
          <div className="exploration-form"><label className="label" htmlFor="scenario-name">Scenario name</label><input className="text-input" id="scenario-name" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Two-day funds hold" disabled={locked} /><button className="btn primary" type="button" onClick={() => void saveScenarioName()} disabled={locked || !title.trim()}>{pending === "create" ? "Saving scenario…" : "Save scenario"}</button></div>
          {selected.analysis ? <div className="scenario-analysis"><h4>Hypothetical · Agent analysis</h4>{selected.stale?.is_stale ? <p className="exploration-state exploration-state--attention">Earlier facts: This result stays attached to its original baseline.</p> : null}<div className="reading scenario-analysis__content" id={savedAnalysisId} style={previewIsOneLongBlock ? { maxHeight: "30rem", overflow: "hidden" } : undefined}><ReactMarkdown components={analysisMarkdownComponents} remarkPlugins={[remarkGfm]}>{visibleAnalysis}</ReactMarkdown></div>{analysisIsLong ? <><p className="muted small">{analysisExpanded ? "The full saved analysis is shown." : previewIsOneLongBlock ? "This saved analysis starts with one long Markdown block." : "Showing complete opening blocks from this saved analysis."}</p><button aria-controls={savedAnalysisId} aria-expanded={analysisExpanded} className="btn quiet tiny" onClick={() => setExpandedAnalysisId(analysisExpanded ? null : selected.scenario_id)} type="button">{analysisExpanded ? "Show less" : "Read full analysis"}</button></> : null}</div> : <p className="muted small">No saved analysis yet. A failed attempt does not remove an earlier result.</p>}
          {selected.affected_issue_ids?.length ? <><h4>Affected issues</h4><ul className="exploration-list">{selected.affected_issue_ids.map((id) => <li key={id}><span>{id}</span></li>)}</ul></> : null}
          {selected.affected_branch_ids?.length ? <><h4>Affected branches</h4><ul className="exploration-list">{selected.affected_branch_ids.map((id) => <li key={id}><span>{id}</span></li>)}</ul></> : null}
          {selected.analysis && !hasScenarioCitations(selected.claim_ids ?? [], claims) ? <p className="exploration-state exploration-state--attention" role="status">No claim-level citations saved. The analysis remains available; source links alone do not establish that its conclusions apply.</p> : null}
          {selected.claim_ids?.length ? <><h4>Supporting claims</h4><ul className="exploration-list">{selected.claim_ids.map((id) => <li key={id}>{onOpenClaim ? <button className="quiet-link" type="button" onClick={() => onOpenClaim(id)}>{id}</button> : <span>{id}</span>}</li>)}</ul></> : null}
          {selected.proposed_outcomes?.length ? <><h4>Proposed outcomes</h4><ul className="exploration-list">{selected.proposed_outcomes.map((outcome) => <li key={outcome.outcome_id}><span>{outcome.label}{outcome.condition ? ` · ${outcome.condition}` : ""}</span></li>)}</ul></> : null}
          {selected.unresolved_conditions?.length ? <><h4>Still uncertain</h4><ul className="exploration-list">{selected.unresolved_conditions.map((condition) => <li key={condition}>{condition}</li>)}</ul></> : null}
          {selected.source_links?.length ? <><h4>Source links</h4><ul className="exploration-list">{selected.source_links.map((path) => <li key={path}>{isExternalSource(path) ? <a className="quiet-link" href={path} target="_blank" rel="noreferrer">{sourceLabel(path)}</a> : isInternalSource(path) && onOpenArtifact ? <button className="quiet-link" type="button" onClick={() => onOpenArtifact(path)}>{sourceLabel(path)}</button> : <code>{sourceLabel(path)}</code>}</li>)}</ul></> : null}
          {selected.adopted_fact_ids?.length ? <p className="exploration-state exploration-state--healthy">Saved: {selected.adopted_fact_ids.length} selected fact{selected.adopted_fact_ids.length === 1 ? "" : "s"} adopted. This scenario remains historical.</p> : null}
        </article> : <div className="scenario-detail scenario-detail--empty"><p className="muted">Select a saved scenario to compare it with the current matter.</p></div>}
      </div>

      <details className="correction-panel"><summary>Correct a fact</summary><p className="small muted">Use this for an actual reported fact. It is separate from adopting a hypothetical scenario.</p><label className="label" htmlFor="correct-fact-id">Fact to replace</label><select className="select-input" id="correct-fact-id" value={correctionFactId} disabled={locked} onChange={(event) => { if (!correctionRevisions) setCorrectionRevisions({ ...currentRevisions }); setCorrectionFactId(event.target.value); }}><option value="">Add a new reported fact</option>{facts.map((fact) => <option key={fact.fact_id} value={fact.fact_id}>{fact.text}</option>)}</select><label className="label" htmlFor="correct-fact-text">Corrected fact</label><textarea className="text-input prose" id="correct-fact-text" value={correctionText} disabled={locked} onChange={(event) => { if (!correctionRevisions) setCorrectionRevisions({ ...currentRevisions }); setCorrectionText(event.target.value); }} placeholder="Funds remained in the account for two days." />{correctionStale ? <div className="exploration-state exploration-state--attention">Needs attention: Matter facts changed. Your correction text is retained. <button className="quiet-link" type="button" onClick={() => setCorrectionRevisions({ ...currentRevisions })} disabled={locked}>Use latest matter facts</button></div> : null}<button className="btn review" type="button" onClick={() => void correctFact()} disabled={locked}>{pending === "correct" ? "Correcting fact…" : "Correct a fact"}</button></details>
    </section>
  );
}

frontend/components/workspace/ChangeImpa:
"use client";

import { useEffect, useRef, useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import type {
  ChangeImpactPanelProps,
  ComparisonCommand,
  ContinuityRunCommand,
  ImpactUpdateCommand,
  ReferenceSelection,
  SpecComparison,
} from "@/lib/continuityTypes";
import {
  differencePresentation,
  findingEffectLabel,
  findingPassageEvidence,
  findingSupportLabel,
  frozenImpactCommand,
  impactAnalysisScope,
  impactContextChanged,
  impactOffer,
  impactRetryDraftKey,
  impactState,
  passageEvidence,
  passagesForFinding,
  selectedReferenceIds,
  selectedReferences,
  targetForFinding,
  type ImpactStatePresentation,
} from "@/lib/impactPresentation";
import styles from "./MatterContinuity.module.css";

function actionKey(slot: string): string {
  return `${slot}:${crypto.randomUUID()}`;
}

function candidateLabel(reference: Pick<ReferenceSelection, "path" | "title">): string {
  return reference.title?.trim() || reference.path;
}

function targetKind(kind: ReferenceSelection["kind"]): string {
  if (kind === "advice") return "Earlier advice";
  if (kind === "recommendation") return "Recommendation";
  if (kind === "decision") return "Recorded decision";
  if (kind === "draft") return "Draft work product";
  return kind.replaceAll("_", " ");
}

const impactMarkdownComponents = {
  table: ({ children }: { children?: React.ReactNode }) => <div style={{ maxWidth: "100%", overflowX: "auto", margin: "10px 0" }}><table>{children}</table></div>,
  pre: ({ children }: { children?: React.ReactNode }) => <pre style={{ maxWidth: "100%", overflowX: "auto", padding: "10px 12px", background: "var(--paper)", border: "1px solid var(--line-faint)", borderRadius: "var(--radius)" }}>{children}</pre>,
  code: ({ children }: { children?: React.ReactNode }) => <code style={{ overflowWrap: "anywhere" }}>{children}</code>,
};

export default function ChangeImpactPanel(props: ChangeImpactPanelProps) {
  const { drafts, busy = false, error, onDraftChange } = props;
  const [pending, setPending] = useState("");
  const [notice, setNotice] = useState<ImpactStatePresentation | null>(null);
  const [localError, setLocalError] = useState("");
  const [showAllPassages, setShowAllPassages] = useState(false);
  const activeContext = useRef(props.contextKey);
  activeContext.current = props.contextKey;
  const renderedContext = useRef(props.contextKey);
  const retryOverlay = useRef<{ contextKey: string; values: Record<string, string> }>({ contextKey: props.contextKey, values: {} });
  if (retryOverlay.current.contextKey !== props.contextKey) retryOverlay.current = { contextKey: props.contextKey, values: {} };
  const locked = busy || Boolean(pending);
  const value = (field: string, fallback = "") => Object.hasOwn(drafts, field) ? drafts[field] : fallback;
  const selected = props.comparisons.find((item) => item.comparison_id === props.selectedComparisonId) ?? null;
  const chosenTargetIds = selectedReferenceIds(value("impact.targets"));

  useEffect(() => {
    if (!impactContextChanged(renderedContext.current, props.contextKey)) return;
    renderedContext.current = props.contextKey;
    setPending("");
    setNotice(null);
    setLocalError("");
    setShowAllPassages(false);
  }, [props.contextKey]);

  function setFrozen<T extends { source_action_key: string }>(slot: string, intent: unknown, create: () => T): T {
    const key = impactRetryDraftKey(slot);
    const stored = retryOverlay.current.values[key] ?? value(key);
    const frozen = frozenImpactCommand(stored, intent, create);
    retryOverlay.current.values[key] = frozen.draft;
    if (!frozen.reused) onDraftChange(key, frozen.draft);
    return frozen.command;
  }

  function clearFrozen(slot: string) {
    const key = impactRetryDraftKey(slot);
    delete retryOverlay.current.values[key];
    onDraftChange(key, "");
  }

  async function perform(slot: string, work: () => Promise<unknown>, success: string, clearRetry = true) {
    const startedIn = props.contextKey;
    setPending(slot); setNotice(null); setLocalError("");
    try {
      const result = await work();
      if (activeContext.current !== startedIn) return;
      const resultState = result && typeof result === "object" && "state" in result ? String(result.state) : "";
      if (["failed", "interrupted", "not_saved"].includes(resultState)) {
        setLocalError(`The run is ${resultState.replaceAll("_", " ")}. The original command is retained for retry.`);
        return;
      }
      if (resultState === "queued") setNotice({ word: "Queued", tone: "agent", detail: success });
      else if (resultState === "running") setNotice({ word: "Agent work", tone: "agent", detail: success });
      else if (resultState === "completed" || resultState === "complete") setNotice({ word: "Complete", tone: "healthy", detail: success });
      else setNotice({ word: "Saved", tone: "healthy", detail: success });
      if (clearRetry) clearFrozen(slot);
    } catch (cause) {
      if (activeContext.current === startedIn) setLocalError(cause instanceof Error ? cause.message : "The action did not finish. Your selection is retained for retry.");
    } finally {
      if (activeContext.current === startedIn) setPending("");
    }
  }

  function toggleTarget(referenceId: string) {
    const next = chosenTargetIds.includes(referenceId) ? chosenTargetIds.filter((id) => id !== referenceId) : [...chosenTargetIds, referenceId];
    onDraftChange("impact.targets", JSON.stringify(next));
  }

  async function prepare() {
    const before = props.sources.find((item) => item.reference_id === value("impact.before")) ?? null;
    const after = props.sources.find((item) => item.reference_id === value("impact.after"));
    const targets = selectedReferences(props.targets, value("impact.targets"));
    if (!after) { setLocalError("Choose the current supplied version."); return; }
    const commandBase = { before, after, targets, business_question_revision: props.businessQuestionRevision };
    const intent = { before_id: before?.reference_id ?? null, after_id: after.reference_id, target_ids: targets.map((target) => target.reference_id) };
    const command = setFrozen<ComparisonCommand>("prepare", intent, () => ({ ...commandBase, source_action_key: actionKey("impact.prepare") }));
    const startedIn = props.contextKey;
    setPending("prepare"); setNotice(null); setLocalError("");
    try {
      const comparison = await props.onPrepare(command);
      if (activeContext.current !== startedIn) return;
      props.onSelectComparison(comparison.comparison_id);
      if (comparison.state === "partial") {
        setNotice({ word: "Partly saved", tone: "attention", detail: "The comparison record exists, but its evidence snapshots are incomplete. Your original command is retained for retry." });
      } else {
        clearFrozen("prepare");
        setNotice({ word: "Prepared", tone: "agent", detail: "Exact source versions and selected work were frozen. No advice, decision, or draft changed." });
      }
    } catch (cause) {
      if (activeContext.current === startedIn) setLocalError(cause instanceof Error ? cause.message : "The comparison was not prepared. Your selections are retained for retry.");
    } finally {
      if (activeContext.current === startedIn) setPending("");
    }
  }

  async function analyze(comparison: SpecComparison) {
    const slot = `analyze:${comparison.comparison_id}`;
    const instruction = value("impact.instruction").trim();
    const intent = { comparison_id: comparison.comparison_id, instruction };
    const command = setFrozen<ContinuityRunCommand>(slot, intent, () => ({ source_action_key: actionKey("impact.analyze"), instruction: instruction || undefined }));
    await perform(slot, () => props.onAnalyze(comparison.comparison_id, command), "The request uses the existing matter conversation. Earlier work remains unchanged.");
  }

  async function requestUpdate(comparison: SpecComparison, targetId: string, artifactRevision: string) {
    const slot = `update:${comparison.comparison_id}:${targetId}`;
    const intent = { comparison_id: comparison.comparison_id, target_id: targetId };
    const command = setFrozen<ImpactUpdateCommand>(slot, intent, () => ({ target_id: targetId, expected_comparison_revision: comparison.revision, expected_artifact_revision: artifactRevision, source_action_key: actionKey("impact.update") }));
    await perform(slot, () => props.onRequestUpdate(comparison.comparison_id, command), "The request uses the existing document editor. The saved draft has not been replaced.");
  }

  async function actOnOffer(offerId: string, action: "accept" | "decline", expectedRevision: string) {
    const slot = `offer:${action}:${offerId}`;
    await perform(slot, () => props.onOfferAction(offerId, action, expectedRevision), action === "decline" ? "Update offer declined. The existing draft is retained." : "Update offer accepted. Review the proposed edits in the existing editor.", false);
  }

  return <section className={`${styles.impactPanel} impact-panel`} aria-labelledby="impact-panel-title">
    <header><div><p className="eyebrow">Change impact</p><h2 id="impact-panel-title">Compare supplied versions</h2></div>{selected ? <span className={`impact-state ${impactState(selected).tone}`}>{impactState(selected).word}</span> : null}</header>
    <p className="impact-panel__intro">Read what changed first. Then assess what remains supported, what changes, and what may need review. This analysis does not edit earlier work.</p>
    {error ? <Notice word="Failed" tone="failure" detail={error} /> : null}{notice ? <Notice {...notice} /> : null}{localError ? <Notice word="Failed" tone="failure" detail={localError} alert /> : null}

    {props.comparisons.length ? <div className="impact-history" aria-label="Saved comparisons">{props.comparisons.map((comparison) => <button aria-pressed={comparison.comparison_id === selected?.comparison_id} className={comparison.comparison_id === selected?.comparison_id ? "selected" : ""} key={comparison.comparison_id} onClick={() => { setShowAllPassages(false); props.onSelectComparison(comparison.comparison_id); }} type="button"><span>{comparison.after.title}</span><small>{impactState(comparison).word} · {differencePresentation(comparison.difference).word}</small></button>)}</div> : null}

    <details className="impact-prepare" open={!props.comparisons.length}>
      <summary>Choose versions and earlier work</summary>
      <div className="impact-prepare__grid">
        <label><span className="label">Earlier version (optional)</span><select className="select-input" disabled={locked} value={value("impact.before")} onChange={(event) => onDraftChange("impact.before", event.target.value)}><option value="">Earlier text not supplied</option>{props.sources.map((source) => <option key={`before:${source.reference_id}`} value={source.reference_id}>{candidateLabel(source)}</option>)}</select></label>
        <label><span className="label">Current supplied version</span><select className="select-input" disabled={locked} value={value("impact.after")} onChange={(event) => onDraftChange("impact.after", event.target.value)}><option value="">Choose current version</option>{props.sources.map((source) => <option key={`after:${source.reference_id}`} value={source.reference_id}>{candidateLabel(source)}</option>)}</select></label>
      </div>
      <fieldset className="impact-targets"><legend>Earlier saved work to assess (optional)</legend>{props.targets.length ? props.targets.map((target) => <label key={target.reference_id}><input checked={chosenTargetIds.includes(target.reference_id)} disabled={locked} onChange={() => toggleTarget(target.reference_id)} type="checkbox" /><span><strong>{candidateLabel(target)}</strong><small>{targetKind(target.kind)} · revision {target.expected_revision}</small></span></label>) : <p className="muted">No earlier saved work is available. You can still compare the supplied source versions.</p>}{!props.targets.some((target) => target.kind === "draft") ? <p className="small muted">To assess a future draft, use Draft to create it. Then prepare a new comparison and select that draft.</p> : null}</fieldset>
      {!chosenTargetIds.length ? <p className="small muted"><strong>Source-only scope:</strong> No earlier advice, recommendation, decision, or draft will be assessed.</p> : null}
      <button className="btn primary" disabled={locked || !value("impact.after")} onClick={() => void prepare()} type="button">{pending === "prepare" ? "Preparing comparison…" : "Prepare comparison"}</button>
    </details>

    {selected ? <ComparisonReading comparison={selected} offers={props.updateOffers} locked={locked} pending={pending} showAllPassages={showAllPassages} instruction={value("impact.instruction")} onInstruction={(next) => onDraftChange("impact.instruction", next)} onShowAll={() => setShowAllPassages(true)} onAnalyze={analyze} onRequestUpdate={requestUpdate} onOfferAction={actOnOffer} onOpenTarget={props.onOpenTarget} onOpenEvidence={props.onOpenEvidence} /> : <div className="impact-empty"><span className="state-label state-quiet">No comparison selected</span><p>Prepare a comparison or open a saved one to read its exact passages and effects.</p></div>}
  </section>;
}

function ComparisonReading({ comparison, offers, locked, pending, showAllPassages, instruction, onInstruction, onShowAll, onAnalyze, onRequestUpdate, onOfferAction, onOpenTarget, onOpenEvidence }: {
  comparison: SpecComparison; offers: ChangeImpactPanelProps["updateOffers"]; locked: boolean; pending: string; showAllPassages: boolean; instruction: string;
  onInstruction: (value: string) => void; onShowAll: () => void; onAnalyze: (comparison: SpecComparison) => Promise<void>;
  onRequestUpdate: (comparison: SpecComparison, targetId: string, revision: string) => Promise<void>;
  onOfferAction: (offerId: string, action: "accept" | "decline", revision: string) => Promise<void>;
  onOpenTarget: ChangeImpactPanelProps["onOpenTarget"]; onOpenEvidence: ChangeImpactPanelProps["onOpenEvidence"];
}) {
  const state = impactState(comparison); const difference = differencePresentation(comparison.difference);
  const passages = comparison.passages ?? []; const shown = showAllPassages ? passages : passages.slice(0, 3);
  const draftTargets = (comparison.targets ?? []).filter((target) => target.kind === "draft");
  return <div className="impact-reading">
    <div className="impact-reading__head"><div><h3>{comparison.before?.title || "Earlier version unavailable"} → {comparison.after.title}</h3><p className="record-meta">Saved comparison · {comparison.comparison_id}</p></div><button className="btn quiet tiny" onClick={() => onOpenTarget({ matter_id: comparison.matter_id, kind: "impact", target_id: comparison.comparison_id, path: comparison.path, revision: comparison.revision })} type="button">Open comparison record</button></div>
    <Notice {...state} /><Notice {...difference} /><Notice {...impactAnalysisScope(comparison.targets)} />
    {shown.length ? <section className="impact-passages" aria-labelledby="impact-passages-title"><h3 id="impact-passages-title">Exact changed passages</h3>{shown.map((passage) => <article className="impact-passage" key={passage.passage_id}><div className="impact-passage__label"><strong>{passage.kind === "formatting" ? "Formatting difference" : passage.kind === "added" ? "Added text" : passage.kind === "deleted" ? "Deleted text" : "Changed text"}</strong><span className="mono">{passage.passage_id}</span></div><div className="impact-passage__columns"><section><div><span>Before · {passage.before_locator || "Location unavailable"}</span>{comparison.before ? <button className="btn quiet tiny" onClick={() => onOpenEvidence(passageEvidence(comparison, passage, "before"))} type="button">Open evidence</button> : null}</div><pre>{passage.before_text || (comparison.before ? "No text in this passage" : "Earlier text unavailable")}</pre></section><section><div><span>After · {passage.after_locator || "Location unavailable"}</span><button className="btn quiet tiny" onClick={() => onOpenEvidence(passageEvidence(comparison, passage, "after"))} type="button">Open evidence</button></div><pre>{passage.after_text || "No text in this passage"}</pre></section></div></article>)}{passages.length > shown.length ? <button className="btn quiet" onClick={onShowAll} type="button">Show all {passages.length} passages</button> : null}</section> : <section className="impact-no-passages"><h3>No exact changed passages</h3><p>{comparison.difference === "unchanged" ? "The available text is unchanged." : comparison.difference === "unavailable" ? "An exact before/after reading is unavailable." : "No passage detail was saved."}</p></section>}
    {comparison.analysis?.trim() ? <section className="impact-analysis"><span className="state-label state-agent">Themis.ai · Generated analysis</span><h3>Effect summary</h3><div className="impact-analysis__markdown"><ReactMarkdown components={impactMarkdownComponents} remarkPlugins={[remarkGfm]}>{comparison.analysis}</ReactMarkdown></div></section> : <section className="impact-analysis empty"><span className="state-label state-agent">Analysis not started</span><label><span className="label">Focus for this analysis (optional)</span><textarea className="text-input" disabled={locked || comparison.state === "stale"} onChange={(event) => onInstruction(event.target.value)} placeholder="For example: Focus on the notice section of the draft." value={instruction} /></label><button className="btn agent" disabled={locked || comparison.state === "stale"} onClick={() => void onAnalyze(comparison)} type="button">{pending === `analyze:${comparison.comparison_id}` ? "Starting analysis…" : "Analyze effect on selected work"}</button></section>}
    {(comparison.findings ?? []).length ? <section className="impact-findings" aria-labelledby="impact-findings-title"><h3 id="impact-findings-title">Effect on earlier work</h3>{comparison.findings!.map((finding) => { const target = targetForFinding(comparison, finding); const linkedPassages = passagesForFinding(comparison, finding); return <article key={finding.finding_id}><div className="impact-finding__head"><div><span className={`impact-effect effect-${finding.effect}`}>{findingEffectLabel(finding.effect)}</span><span className={`impact-support support-${finding.support}`}>{findingSupportLabel(finding.support)}</span></div>{target ? <button className="btn quiet tiny" onClick={() => onOpenTarget({ matter_id: comparison.matter_id, kind: "artifact", target_id: target.reference_id, path: target.path, revision: target.revision, view: target.kind === "draft" ? "draft" : "understand" })} type="button">Open {targetKind(target.kind).toLowerCase()}</button> : null}</div><h4>{target?.title || "Affected work unavailable"}{finding.affected_section ? ` · ${finding.affected_section}` : ""}</h4>{target ? <p className="record-meta">{targetKind(target.kind)} · frozen revision {target.revision}</p> : null}<p>{finding.explanation}</p>{linkedPassages.length ? <div className="impact-evidence-links"><span>Exact evidence:</span>{linkedPassages.map((passage) => { const evidence = findingPassageEvidence(comparison, passage); return <button className="btn quiet tiny" key={passage.passage_id} onClick={() => onOpenEvidence(evidence)} type="button">{evidence.locator || passage.passage_id}</button>; })}</div> : <p className="small muted">No exact passage link was saved for this finding.</p>}{target?.kind === "decision" ? <p className="small muted">Analysis only. The recorded decision is unchanged.</p> : null}</article>; })}</section> : comparison.analysis?.trim() ? <section className="impact-no-passages"><h3>No structured affected-work links</h3><p>The useful analysis remains available. No precise saved-work link was recorded.</p></section> : null}
    {draftTargets.length ? <section className="impact-draft-updates" aria-labelledby="impact-draft-updates-title"><h3 id="impact-draft-updates-title">Update selected drafts</h3>{draftTargets.map((target) => <article key={target.reference_id}><div><h4>{candidateLabel(target)}</h4><p className="record-meta">Draft work product · frozen revision {target.revision}</p></div><button className="btn agent" disabled={locked || comparison.state === "stale" || !comparison.analysis?.trim()} onClick={() => void onRequestUpdate(comparison, target.reference_id, target.revision)} type="button">{pending === `update:${comparison.comparison_id}:${target.reference_id}` ? "Requesting update…" : "Request draft update"}</button></article>)}</section> : null}
    {(comparison.offer_ids ?? []).length ? <section className="impact-offers" aria-labelledby="impact-offers-title"><h3 id="impact-offers-title">Existing draft update offers</h3>{comparison.offer_ids!.map((offerId) => { const offer = impactOffer(comparison, offers, offerId); const offerState = offer?.state ?? "unavailable"; return <article key={offerId}><div><span className={`state-label ${offerState === "stale" ? "state-attention" : offerState === "unavailable" ? "state-quiet" : "state-agent"}`}>Update offer · {offerState}</span><p>{offer?.reason || "The saved offer state is not available in this view."}</p></div>{offerState === "declined" ? <span className="impact-offer__retained">Declined · Existing draft retained</span> : offerState === "accepted" ? <span className="impact-offer__retained">Accepted · Open the existing editor to review changes</span> : offerState === "stale" ? <span className="impact-offer__retained">Stale · Prepare a current comparison</span> : offerState === "unavailable" ? <span className="impact-offer__retained">State unavailable · No action taken</span> : <div className="btn-row"><button className="btn tiny" disabled={locked} onClick={() => void onOfferAction(offerId, "accept", offer!.base_revision)} type="button">Accept update offer</button><button className="btn quiet tiny" disabled={locked} onClick={() => void onOfferAction(offerId, "decline", offer!.base_revision)} type="button">Decline offer</button></div>}</article>; })}</section> : null}
    {(comparison.coverage_limits ?? []).length ? <details className="impact-limits" open={comparison.state === "partial" || comparison.state === "unavailable" || comparison.state === "stale"}><summary>Coverage and limits</summary><ul>{comparison.coverage_limits!.map((limit, index) => <li key={`${limit}:${index}`}>{limit}</li>)}</ul></details> : null}
  </div>;
}

function Notice({ word, tone, detail, alert = false }: ImpactStatePresentation & { alert?: boolean }) {
  return <p className={`impact-notice ${tone}`} role={alert ? "alert" : "status"}><strong>{word}:</strong> {detail}</p>;
}

frontend/components/workspace/BusinessFl:
"use client";

import { useEffect, useRef, useState } from "react";
import type { BusinessFlowProps, Flow, FlowActor, FlowEdge, InteractionReceipt } from "@/lib/workspaceTypes";
import styles from "./MatterExplore.module.css";

const newId = (prefix: string) => `${prefix}-${crypto.randomUUID()}`;
const cloneFlow = (flow: Flow): Flow => ({ ...flow, actors: [...(flow.actors ?? [])], edges: [...(flow.edges ?? [])] });
type Notice = { tone: "healthy" | "agent" | "attention" | "failure"; word: string; message: string };

function normalizeEdges(edges: FlowEdge[]) {
  return edges.map((edge, index) => ({ ...edge, order: index + 1 }));
}

function receiptNotice(receipt: InteractionReceipt): Notice {
  if (receipt.state === "applied") return { tone: "healthy", word: "Saved", message: "Selected facts were saved to the matter record." };
  if (receipt.state === "proposed") return { tone: "attention", word: "Proposed", message: "It is not applied." };
  return { tone: "failure", word: "Not saved", message: receipt.failure_detail || "The selected facts were not saved." };
}

export default function BusinessFlow({
  flow,
  busy = false,
  currentRevisions = {},
  proposedFactChanges = [],
  onAcceptFactChanges,
  onSave,
  onSelectFact,
  onRefresh,
}: BusinessFlowProps) {
  const [draft, setDraft] = useState<Flow>(() => cloneFlow(flow));
  const [baseRevision, setBaseRevision] = useState(flow.revision);
  const [dirty, setDirty] = useState(false);
  const [selectedChanges, setSelectedChanges] = useState<string[]>([]);
  const [notice, setNotice] = useState<Notice | null>(null);
  const [error, setError] = useState("");
  const [pending, setPending] = useState<"save" | "accept" | null>(null);
  const acceptanceKey = useRef({ signature: "", key: "" });
  const [conflict, setConflict] = useState(false);
  const [refreshedFlow, setRefreshedFlow] = useState<Flow | null>(null);
  const locked = busy || pending !== null;

  // A background refresh must never erase a lawyer's unsaved flow edits.
  useEffect(() => {
    if (dirty || flow.revision === baseRevision) return;
    setDraft(cloneFlow(flow));
    setBaseRevision(flow.revision);
    setSelectedChanges([]);
  }, [baseRevision, dirty, flow]);

  const update = (next: Flow) => { setDraft({ ...next, edges: normalizeEdges(next.edges ?? []) }); setDirty(true); setConflict(false); };
  const actors = draft.actors ?? [];
  const edges = draft.edges ?? [];
  const actorLabels = new Map(actors.map((actor) => [actor.actor_id, actor.label.trim() || "Unnamed actor"]));

  function addActor() {
    const actor: FlowActor = { actor_id: newId("actor"), label: "New actor" };
    update({ ...draft, actors: [...actors, actor] });
  }

  function updateActor(actorId: string, label: string) {
    update({ ...draft, actors: actors.map((actor) => actor.actor_id === actorId ? { ...actor, label } : actor) });
  }

  function removeActor(actorId: string) {
    update({ ...draft, actors: actors.filter((actor) => actor.actor_id !== actorId), edges: edges.filter((edge) => edge.from_actor_id !== actorId && edge.to_actor_id !== actorId) });
  }

  function addEdge() {
    if (actors.length < 2) { setError("Add at least two actors before adding a relationship."); return; }
    const edge: FlowEdge = {
      edge_id: newId("edge"), from_actor_id: actors[0].actor_id, to_actor_id: actors[1].actor_id,
      label: "New relationship", order: edges.length + 1, timing: "", custody: "", ownership: "", fact_ids: [], uncertainty: "",
    };
    update({ ...draft, edges: [...edges, edge] });
  }

  function updateEdge(edgeId: string, patch: Partial<FlowEdge>) {
    update({ ...draft, edges: edges.map((edge) => edge.edge_id === edgeId ? { ...edge, ...patch } : edge) });
  }

  function moveEdge(edgeId: string, direction: -1 | 1) {
    const from = edges.findIndex((edge) => edge.edge_id === edgeId);
    const to = from + direction;
    if (from < 0 || to < 0 || to >= edges.length) return;
    const next = [...edges]; [next[from], next[to]] = [next[to], next[from]];
    update({ ...draft, edges: next });
  }

  async function save() {
    const unnamedActor = actors.some((actor) => !actor.label.trim());
    const unnamedEdge = edges.some((edge) => !edge.label.trim());
    if (unnamedActor || unnamedEdge) { setError("Name each actor and relationship before saving."); return; }
    setPending("save"); setError(""); setNotice(null); setConflict(false);
    try {
      const saved = await onSave({ ...draft, revision: baseRevision, actors, edges: normalizeEdges(edges) }, baseRevision);
      setDraft(cloneFlow(saved)); setBaseRevision(saved.revision); setDirty(false);
      setNotice({ tone: "healthy", word: "Saved", message: "Business flow saved." });
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The flow was not saved. Your edits are retained so you can refresh or retry.");
      setConflict(true);
    } finally { setPending(null); }
  }

  async function acceptSelectedFacts() {
    if (!onAcceptFactChanges) { setError("Flow fact acceptance is not connected yet."); return; }
    if (!selectedChanges.length) { setError("Choose the specific proposed facts to accept."); return; }
    setPending("accept"); setError(""); setNotice(null);
    const signature = `${selectedChanges.slice().sort().join(",")}:${JSON.stringify(currentRevisions)}`;
    if (acceptanceKey.current.signature !== signature) acceptanceKey.current = { signature, key: newId("flow-accept") };
    try {
      const receipt = await onAcceptFactChanges(selectedChanges, currentRevisions, acceptanceKey.current.key);
      setNotice(receiptNotice(receipt));
      if (receipt.state === "applied") setSelectedChanges([]);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The selected facts were not accepted. Your selection is retained.");
    } finally { setPending(null); }
  }

  async function refreshCurrentFlow() {
    if (!onRefresh) return;
    setError("");
    try {
      const latest = await onRefresh();
      setRefreshedFlow(cloneFlow(latest));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The current saved flow could not be read. Your edits are retained.");
    }
  }

  function rebaseLocalEdits() {
    if (!refreshedFlow) return;
    setBaseRevision(refreshedFlow.revision);
    setConflict(false);
    setError("");
    setNotice({ tone: "attention", word: "Rebased", message: "Your local flow edits are retained against the latest saved revision. Review them before saving." });
  }

  async function copyLocalFlow() {
    try {
      await navigator.clipboard.writeText(JSON.stringify({ ...draft, revision: baseRevision }, null, 2));
      setNotice({ tone: "agent", word: "Copied", message: "Local flow edits copied." });
    } catch {
      setError("The local flow could not be copied. Your edits remain in this form.");
    }
  }

  const initialUnsaved = !flow.revision && !dirty;

  return <section aria-labelledby="business-flow-title" className={`${styles.businessFlow} business-flow`}>
    <div className="business-flow__header"><div><p className="eyebrow">Explore</p><h2 id="business-flow-title">Business flow</h2></div><span className={dirty || initialUnsaved ? "state-attention" : "state-healthy"}>{dirty ? "Needs save" : initialUnsaved ? "Not saved" : "Saved"}</span></div>
    <p className="business-flow__intro">Map the people and ordered relationships. This sketch does not reach a legal conclusion by itself.</p>
    {notice ? <p className={`business-flow__state business-flow__state--${notice.tone}`} role="status">{notice.word}: {notice.message}</p> : null}
    {error ? <p className="business-flow__state business-flow__state--failure" role="alert">Failed: {error}</p> : null}
    <section className="business-flow__sketch" aria-labelledby="business-flow-sketch-title">
      <div className="business-flow__section-heading"><div><h3 id="business-flow-sketch-title">Flow sketch</h3><p className="small muted">This diagram mirrors the editable ordered relationship list below.</p></div></div>
      {edges.length ? <ol className="business-flow__sketch-list">{edges.map((edge, index) => {
        const edgeDetails = [
          { label: "Timing", value: edge.timing?.trim() },
          { label: "Custody", value: edge.custody?.trim() },
          { label: "Ownership", value: edge.ownership?.trim() },
          { label: "Uncertainty", value: edge.uncertainty?.trim() },
        ].filter((detail): detail is { label: string; value: string } => Boolean(detail.value));
        return <li className="business-flow__sketch-step" key={edge.edge_id}>
          <span className="business-flow__sketch-order">Step {index + 1}</span>
          <div className="business-flow__sketch-route">
            <div className="business-flow__sketch-node"><span>From</span><strong>{actorLabels.get(edge.from_actor_id) ?? "Unknown actor"}</strong></div>
            <span className="business-flow__sketch-arrow" aria-hidden="true">→</span>
            <div className="business-flow__sketch-node business-flow__sketch-node--relationship"><span>Relationship</span><strong>{edge.label.trim() || "Unnamed relationship"}</strong></div>
            <span className="business-flow__sketch-arrow" aria-hidden="true">→</span>
            <div className="business-flow__sketch-node"><span>To</span><strong>{actorLabels.get(edge.to_actor_id) ?? "Unknown actor"}</strong></div>
          </div>
          {edgeDetails.length ? <dl className="business-flow__sketch-details">{edgeDetails.map((detail) => <div key={detail.label}><dt>{detail.label}</dt><dd>{detail.value}</dd></div>)}</dl> : <p className="small muted">No timing, custody, ownership, or uncertainty recorded for this step.</p>}
        </li>;
      })}</ol> : <p className="muted small">Add an ordered relationship to see the flow sketch.</p>}
    </section>
    <div className="business-flow__actors"><div className="business-flow__section-heading"><h3>Actors</h3><button className="btn tiny" type="button" onClick={addActor} disabled={locked}>Add actor</button></div>{actors.length ? actors.map((actor) => <div className="business-flow__actor" key={actor.actor_id}><input className="text-input" aria-label="Actor name" value={actor.label} disabled={locked} onChange={(event) => updateActor(actor.actor_id, event.target.value)} /><button className="btn tiny quiet" type="button" onClick={() => removeActor(actor.actor_id)} disabled={locked}>Remove</button></div>) : <p className="muted small">Add the people or organizations in this flow.</p>}</div>
    <div className="business-flow__edges"><div className="business-flow__section-heading"><h3>Ordered relationships</h3><button className="btn tiny" type="button" onClick={addEdge} disabled={locked}>Add relationship</button></div>{edges.length ? edges.map((edge, index) => <article className="business-flow__edge" key={edge.edge_id}><div className="business-flow__edge-order"><span>Step {index + 1}</span><div className="btn-row"><button className="btn tiny quiet" type="button" onClick={() => moveEdge(edge.edge_id, -1)} disabled={index === 0 || locked}>Earlier</button><button className="btn tiny quiet" type="button" onClick={() => moveEdge(edge.edge_id, 1)} disabled={index === edges.length - 1 || locked}>Later</button><button className="btn tiny quiet" type="button" onClick={() => update({ ...draft, edges: edges.filter((item) => item.edge_id !== edge.edge_id) })} disabled={locked}>Remove</button></div></div><div className="business-flow__edge-grid"><label><span>From</span><select className="select-input" value={edge.from_actor_id} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { from_actor_id: event.target.value })}>{actors.map((actor) => <option key={actor.actor_id} value={actor.actor_id}>{actor.label || "Unnamed actor"}</option>)}</select></label><label><span>To</span><select className="select-input" value={edge.to_actor_id} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { to_actor_id: event.target.value })}>{actors.map((actor) => <option key={actor.actor_id} value={actor.actor_id}>{actor.label || "Unnamed actor"}</option>)}</select></label><label className="business-flow__wide"><span>Relationship</span><input className="text-input" value={edge.label} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { label: event.target.value })} /></label><label><span>Timing</span><input className="text-input" value={edge.timing ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { timing: event.target.value })} /></label><label><span>Custody</span><input className="text-input" value={edge.custody ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { custody: event.target.value })} /></label><label><span>Ownership</span><input className="text-input" value={edge.ownership ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { ownership: event.target.value })} /></label><label className="business-flow__wide"><span>Uncertainty</span><input className="text-input" value={edge.uncertainty ?? ""} disabled={locked} onChange={(event) => updateEdge(edge.edge_id, { uncertainty: event.target.value })} /></label></div>{edge.fact_ids?.length ? <div className="business-flow__facts"><span>Linked facts</span>{edge.fact_ids.map((factId) => <button className="chip" type="button" key={factId} onClick={() => onSelectFact(factId)} disabled={locked}>{factId}</button>)}</div> : <p className="small muted">No linked facts.</p>}</article>) : <p className="muted small">Add an ordered relationship after you add actors.</p>}</div>
    <div className="btn-row"><button className="btn primary" type="button" onClick={() => void save()} disabled={locked}>{pending === "save" ? "Saving flow…" : "Save flow"}</button><span className="small muted">Saved means the flow record was written.</span></div>
    {conflict ? <div className="business-flow__conflict"><strong>Needs attention: flow changed while you were editing.</strong><p className="small">Your local edits are still here. Refresh reads the current saved flow without replacing them. Rebase uses that current revision only after you choose it.</p><div className="btn-row"><button className="btn review" type="button" onClick={() => void refreshCurrentFlow()} disabled={locked || !onRefresh}>Refresh current flow</button><button className="btn quiet" type="button" onClick={() => void copyLocalFlow()} disabled={locked}>Copy local edits</button>{refreshedFlow ? <button className="btn primary" type="button" onClick={rebaseLocalEdits} disabled={locked}>Rebase my edits</button> : null}</div></div> : null}
    <div className="business-flow__acceptance"><h3>Accept selected facts</h3><p className="small muted">A flow edit can propose facts. Choose only the facts you want to add to the matter.</p>{proposedFactChanges.filter((change) => change.state === "proposed" || !change.state).length ? proposedFactChanges.filter((change) => change.state === "proposed" || !change.state).map((change) => <label className="checkbox-row" key={change.change_id}><input type="checkbox" checked={selectedChanges.includes(change.change_id)} disabled={locked} onChange={() => setSelectedChanges((current) => current.includes(change.change_id) ? current.filter((id) => id !== change.change_id) : [...current, change.change_id])} /><span>{change.text}</span></label>) : <p className="small muted">No proposed facts are ready to accept.</p>}<button className="btn review" type="button" onClick={() => void acceptSelectedFacts()} disabled={locked || !selectedChanges.length}>{pending === "accept" ? "Accepting facts…" : "Accept selected facts"}</button></div>
  </section>;
}

frontend/components/workspace/ContextTra:
"use client";

import { useEffect, useState } from "react";
import type { ContextSelection, ContextTrayProps } from "@/lib/workspaceTypes";
import styles from "./MatterTools.module.css";

function title(item: Pick<ContextSelection, "reference_id" | "role">) {
  const known: Record<string, string> = {
    business_question: "Business question", current_facts: "Current facts", company: "Company context",
    company_context: "Company context", selected_passage: "Selected passage", applied_note: "Applied note",
    conversation_history: "Relevant conversation history", contribution: "Lawyer contribution", matter_record: "Matter record",
    tool_read: "Material read by a tool",
  };
  return known[item.role] ?? known[item.reference_id] ?? item.role.replace(/[_-]+/g, " ").replace(/^./, (letter) => letter.toUpperCase());
}

function manifestState(state: string) {
  return ({ included: "Included in this run", truncated: "Included in part", omitted: "Omitted from this run", unavailable: "Unavailable for this run" } as Record<string, string>)[state] ?? "State unknown";
}

export default function ContextTray({ selections, manifest, onChange, busy = false }: ContextTrayProps) {
  const [draft, setDraft] = useState(selections);
  const [saving, setSaving] = useState<string | null>(null);
  const [error, setError] = useState("");
  const [dirty, setDirty] = useState(false);
  useEffect(() => { if (!saving && !dirty) setDraft(selections); }, [selections, saving, dirty]);

  async function toggle(referenceId: string) {
    const next = draft.map((item) => item.reference_id === referenceId ? { ...item, selected: item.selected === false } : item);
    setDraft(next); setDirty(true); setSaving(referenceId); setError("");
    try { await onChange(next); setDirty(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Context selection was not saved. Your choices are retained so you can retry."); }
    finally { setSaving(null); }
  }
  async function retry() {
    setSaving("retry"); setError("");
    try { await onChange(draft); setDirty(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Context selection was not saved. Your choices are retained so you can retry."); }
    finally { setSaving(null); }
  }

  return <section aria-label="Inquiry context" className={styles.context}>
    <div><h2 className={styles.contextTitle}>Next inquiry</h2><p className={styles.contextCopy}>These choices apply to the next inquiry. Removing a choice does not delete the saved file or change an earlier run.</p></div>
    {error ? <div className="warning-callout" role="status"><strong>Not saved.</strong> {error} <button className="btn quiet tiny" disabled={Boolean(saving)} onClick={() => void retry()} type="button">Retry</button></div> : null}
    <div className={styles.contextList}>
      {draft.length ? draft.map((item) => <label className={`${styles.contextItem} ${item.mandatory ? styles.contextItemMandatory : ""}`} key={item.reference_id}>
        <input checked={item.mandatory || item.selected !== false} disabled={busy || Boolean(saving) || item.mandatory} onChange={() => void toggle(item.reference_id)} type="checkbox" />
        <span><strong>{title(item)}</strong><span className={`record-meta ${styles.contextMetadata}`}>{item.mandatory ? "Mandatory" : item.selected !== false ? dirty ? "Selected · Not saved" : "Selected" : dirty ? "Available · Not saved" : "Available"}</span>{item.path ? <span className={styles.contextCopy}>{item.path}</span> : null}<span className={styles.contextCopy}>{item.mandatory ? "This matter record is always supplied because the inquiry cannot be understood without it." : item.selected !== false ? "Chosen for the next inquiry." : "Saved and available. It will not be supplied directly to the next inquiry."}</span>{saving === item.reference_id ? <span className="state-label state-agent" role="status">Saving selection…</span> : null}</span>
      </label>) : <p className={styles.contextCopy}>No optional context is available. The current question and saved matter facts still travel with the inquiry.</p>}
    </div>

    <div><h2 className={styles.contextTitle}>{manifest ? "Submitted context" : "No submitted inquiry selected"}</h2><p className={styles.contextCopy}>{manifest ? "This is the saved context record for the selected inquiry. Later selection changes do not alter it." : "After an inquiry starts, its actual included, partial, omitted, unavailable, and later-read material appears here."}</p></div>
    {manifest ? <div className={styles.manifestList}>{(manifest.entries ?? []).length ? (manifest.entries ?? []).map((item, index) => <article className={styles.manifestItem} key={`${item.reference_id}:${index}`}>
      <div className={styles.fileHeading}><strong>{title(item)}</strong><span className={`state-label ${item.state === "included" ? "state-healthy" : item.state === "truncated" ? "state-attention" : item.state === "unavailable" ? "state-failure" : "state-agent"}`}>{manifestState(item.state)}</span></div>
      {item.path ? <p className={styles.contextCopy}>{item.path}</p> : null}<p className={styles.contextCopy}>{item.reason || "No reason was stored."}</p>
      {item.tool_read_evidence?.length ? <details className={styles.technicalRecord}><summary className="faint">Technical read record</summary><p className={styles.contextCopy}>{item.tool_read_evidence.join(", ")}</p></details> : item.role === "tool_read" ? <p className="warning-callout">No saved proof of this later read is available.</p> : null}
    </article>) : <p className={styles.contextCopy}>This run stored an empty context manifest.</p>}</div> : null}
  </section>;
}

frontend/components/workspace/IssueRevie:
"use client";

import { useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import type {
  ConversationTarget,
  IssueDispositionCommand,
  IssueDispositionState,
  IssueReviewDetailProps,
  IssueUpdate,
  SupportingQuestionCommand,
  WorkspaceQuestion,
  WorkspaceClaim,
} from "@/lib/workspaceTypes";
import styles from "./MatterReview.module.css";

type DetailActionKeys =
  | "onIssueUpdate"
  | "onQuestionAnswer"
  | "onDisposition"
  | "onOpenEvidence"
  | "onOpenDocument"
  | "onResearchLegalBasis"
  | "onCreateMitigation"
  | "onRecordDecision"
  | "onDiscuss"
  | "onOpenDecisionMap";

export interface IssueResponseOption {
  option_id: string;
  title: string;
  condition?: string | null;
  state?: string | null;
}

export interface SupportedTextRenderInput {
  text: string;
  surface: "current_answer" | "issue_claim";
  claim?: WorkspaceClaim;
  claims: WorkspaceClaim[];
}

export type IssueReviewDetailComponentProps = Omit<IssueReviewDetailProps, DetailActionKeys> & Partial<Pick<IssueReviewDetailProps, DetailActionKeys>> & {
  responseOptions?: IssueResponseOption[];
  renderSupportedText?: (input: SupportedTextRenderInput) => ReactNode;
};

type IssueDraft = { title: string; parentIssueId: string; whyItMatters: string; baseRevision: string };

const reading: CSSProperties = { color: "var(--ink-2)", font: "400 16px/1.65 var(--serif)", margin: "7px 0", overflowWrap: "anywhere", whiteSpace: "pre-wrap" };
const muted: CSSProperties = { color: "var(--ink-3)", font: "400 15px/1.5 var(--sans)", margin: "5px 0", overflowWrap: "anywhere" };
const actionStyle: CSSProperties = { maxWidth: "100%", whiteSpace: "normal", overflowWrap: "anywhere", textAlign: "left" };

export function dispositionLabel(disposition?: IssueDispositionState | null) {
  if (disposition === "mitigation_in_progress") return "Mitigation in progress";
  if (disposition === "resolved") return "Resolved";
  if (disposition === "risk_accepted") return "Risk accepted";
  if (disposition === "not_applicable") return "Not applicable";
  return disposition === "unresolved" ? "Unresolved" : "No disposition recorded";
}

function dispositionClass(disposition?: IssueDispositionState | null) {
  return disposition === "resolved" || disposition === "not_applicable" ? "state-healthy" : "state-attention";
}

function questionLabel(question: WorkspaceQuestion) {
  if (question.state === "answered") return "Answered";
  if (question.state === "left_open") return "Left open";
  return "Open";
}

function uniqueActionKey(prefix: string) {
  return `${prefix}:${globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random()}`}`;
}

export default function IssueReviewDetail(props: IssueReviewDetailComponentProps) {
  const { issue, issuesRevision, questions, claims, workItems, decisions, busy = false, error } = props;
  const [issueDraft, setIssueDraft] = useState<IssueDraft | null>(null);
  const [answerDrafts, setAnswerDrafts] = useState<Record<string, string>>({});
  const [disposition, setDisposition] = useState<IssueDispositionState>("unresolved");
  const [reason, setReason] = useState("");
  const [decisionIds, setDecisionIds] = useState<string[]>([]);
  const [dispositionFormOpen, setDispositionFormOpen] = useState(false);
  const [dispositionBaseRevision, setDispositionBaseRevision] = useState<string | null>(null);
  const [localBusy, setLocalBusy] = useState("");
  const [localError, setLocalError] = useState("");
  const actionKeys = useRef(new Map<string, string>());
  const actionKey = (signature: string) => {
    const saved = actionKeys.current.get(signature);
    if (saved) return saved;
    const next = uniqueActionKey(`issue:${issue.issue_id}`);
    actionKeys.current.set(signature, next);
    return next;
  };
  const unavailable = "This action will be available after the matter page finishes loading its review controls.";
  const target: ConversationTarget = { matter_id: props.matterId, issue_id: issue.issue_id };
  const currentDisposition = dispositionLabel(issue.disposition);
  const hasCitedEvidence = claims.some((claim) => claim.evidence.length > 0);
  const isReopen = Boolean(issue.disposition && issue.disposition !== "unresolved" && disposition === "unresolved");
  const riskNeedsDecision = disposition === "risk_accepted" && decisionIds.length === 0;

  function openDispositionForm() {
    setDisposition(issue.disposition === "unresolved" ? "mitigation_in_progress" : "unresolved");
    setReason("");
    setDecisionIds(issue.linked_decision_ids ?? []);
    setDispositionBaseRevision(issuesRevision);
    setDispositionFormOpen(true);
    setLocalError("");
  }

  function cancelDispositionForm() {
    setDispositionFormOpen(false);
    setDispositionBaseRevision(null);
    setReason("");
    setDecisionIds([]);
    setLocalError("");
  }

  async function saveIssue() {
    if (!issueDraft || !props.onIssueUpdate) return;
    if (issueDraft.baseRevision !== issuesRevision) {
      setLocalError("The issue changed while you were editing. Use the latest issue before you save.");
      return;
    }
    const command: IssueUpdate = {
      expected_revision: issueDraft.baseRevision,
      title: issueDraft.title.trim(),
      parent_issue_id: issueDraft.parentIssueId.trim() || null,
      why_it_matters: issueDraft.whyItMatters.trim() || null,
    };
    setLocalBusy("issue"); setLocalError("");
    try { await props.onIssueUpdate(issue.issue_id, command); setIssueDraft(null); }
    catch (cause) { setLocalError(cause instanceof Error ? cause.message : "The issue change was not saved. Your text is retained."); }
    finally { setLocalBusy(""); }
  }

  async function answerQuestion(question: WorkspaceQuestion, state: SupportingQuestionCommand["state"]) {
    if (!props.onQuestionAnswer) return;
    const answer = answerDrafts[question.question_id]?.trim();
    if (state === "answered" && !answer) return;
    const answerKind = question.question_kind === "legal" ? "legal_analysis" : "reported_fact";
    const signature = `question:${question.question_id}:${question.source_revision ?? ""}:${state}:${answerKind}:${answer ?? ""}`;
    setLocalBusy(`question:${question.question_id}`); setLocalError("");
    try {
      await props.onQuestionAnswer(question.question_id, {
        state,
        answer: state === "answered" ? answer : undefined,
        answer_kind: state === "answered" ? answerKind : undefined,
        expected_revision: question.source_revision ?? "",
        source_action_key: actionKey(signature),
      });
      setAnswerDrafts((current) => { const next = { ...current }; delete next[question.question_id]; return next; });
    } catch (cause) { setLocalError(cause instanceof Error ? cause.message : "The answer was not saved. Your text is retained."); }
    finally { setLocalBusy(""); }
  }

  async function recordDisposition() {
    if (!props.onDisposition || !reason.trim() || riskNeedsDecision) return;
    if (!dispositionBaseRevision || dispositionBaseRevision !== issuesRevision) {
      setLocalError("The issue changed while you were choosing a disposition. Cancel and open the form again to use the latest issue.");
      return;
    }
    const command: IssueDispositionCommand = {
      disposition,
      reason: reason.trim(),
      expected_revision: dispositionBaseRevision,
      source_action_key: actionKey(`disposition:${dispositionBaseRevision}:${disposition}:${reason.trim()}:${decisionIds.join(",")}`),
      linked_work_item_ids: issue.linked_work_item_ids ?? [],
      linked_decision_ids: decisionIds,
    };
    setLocalBusy("disposition"); setLocalError("");
    try { await props.onDisposition(issue.issue_id, command); cancelDispositionForm(); }
    catch (cause) { setLocalError(cause instanceof Error ? cause.message : "The disposition was not recorded. Your reason is retained."); }
    finally { setLocalBusy(""); }
  }

  return <article aria-label={`Issue review: ${issue.title}`} className={`${styles.detail} ${styles.card}`}>
    <header className={styles.detailHead}>
      <div><span className="record-meta">What needs your judgment</span><h2 className={styles.questionTitle}>{issue.title || "Untitled issue"}</h2>
        <span className={`state-label ${dispositionClass(issue.disposition)}`}>{currentDisposition}</span>
      </div>
      <div className={styles.detailActions}>
        <p className={styles.copy}><strong>Next action:</strong> {issue.next_action || "Review the saved analysis and record the next position."}</p>
        <p className={styles.copy}><strong>Owner:</strong> {issue.action_owner || "Unassigned"}</p>
        <button className="btn tiny" disabled={!props.onOpenDecisionMap} onClick={() => props.onOpenDecisionMap?.(issue.issue_id)} style={actionStyle} title={!props.onOpenDecisionMap ? unavailable : undefined} type="button">Open decision map</button>
        <button className="btn quiet tiny" disabled={!props.onDiscuss} onClick={() => props.onDiscuss?.(target)} style={actionStyle} title={!props.onDiscuss ? unavailable : undefined} type="button">Discuss this issue</button>
        <details className={styles.details}>
        <summary>Edit issue details</summary>
        {!props.onIssueUpdate ? <p style={muted}>{unavailable}</p> : <div style={{ display: "grid", gap: 9, marginTop: 10 }}>
          <label className="field-block"><span className="field-label">Issue title</span><input className="text-input" disabled={busy || localBusy === "issue"} onChange={(event) => setIssueDraft((current) => ({ title: event.target.value, parentIssueId: current?.parentIssueId ?? issue.parent_issue_id ?? "", whyItMatters: current?.whyItMatters ?? issue.why_it_matters ?? "", baseRevision: current?.baseRevision ?? issuesRevision }))} value={issueDraft?.title ?? issue.title} /></label>
          <label className="field-block"><span className="field-label">Parent issue ID</span><input className="text-input" disabled={busy || localBusy === "issue"} onChange={(event) => setIssueDraft((current) => ({ title: current?.title ?? issue.title, parentIssueId: event.target.value, whyItMatters: current?.whyItMatters ?? issue.why_it_matters ?? "", baseRevision: current?.baseRevision ?? issuesRevision }))} value={issueDraft?.parentIssueId ?? issue.parent_issue_id ?? ""} /></label>
          <label className="field-block"><span className="field-label">Why this matters</span><textarea className="text-input prose" disabled={busy || localBusy === "issue"} onChange={(event) => setIssueDraft((current) => ({ title: current?.title ?? issue.title, parentIssueId: current?.parentIssueId ?? issue.parent_issue_id ?? "", whyItMatters: event.target.value, baseRevision: current?.baseRevision ?? issuesRevision }))} value={issueDraft?.whyItMatters ?? issue.why_it_matters ?? ""} /></label>
          <div className="btn-row"><button className="btn tiny" disabled={!issueDraft || !issueDraft.title.trim() || issueDraft.baseRevision !== issuesRevision || busy || Boolean(localBusy)} onClick={() => void saveIssue()} type="button">{localBusy === "issue" ? "Saving…" : "Save issue details"}</button><button className="btn quiet tiny" disabled={!issueDraft || Boolean(localBusy)} onClick={() => setIssueDraft(null)} type="button">Cancel</button></div>
        </div>}
        </details>
      </div>
    </header>

    <div className={styles.detailGrid}>
    <section aria-labelledby={`why-${issue.issue_id}`}><span className="record-meta">Why this matters</span><h3 className="section-heading" id={`why-${issue.issue_id}`} style={{ margin: "5px 0" }}>Business effect</h3><p style={reading}>{issue.why_it_matters || "No business consequence is saved for this issue."}</p></section>

    <section aria-labelledby={`law-${issue.issue_id}`}>
      <span className="record-meta">Legal basis</span><h3 className="section-heading" id={`law-${issue.issue_id}`} style={{ margin: "5px 0" }}>Claims and applicability</h3>
      {!claims.length ? <div className="warning-callout" role="status"><strong>No cited sources.</strong><p style={{ margin: "4px 0" }}>Useful issue analysis remains available. Research can add claim-level support.</p><button className="btn agent tiny" disabled={!props.onResearchLegalBasis} onClick={() => props.onResearchLegalBasis?.(issue.issue_id)} title={!props.onResearchLegalBasis ? unavailable : undefined} type="button">Research legal basis</button></div> : <div style={{ display: "grid", gap: 10 }}>
        {!hasCitedEvidence ? <div className="warning-callout" role="status"><strong>No cited sources.</strong><p style={{ margin: "4px 0" }}>The saved claims remain visible. Research can add claim-level support.</p><button className="btn agent tiny" disabled={!props.onResearchLegalBasis} onClick={() => props.onResearchLegalBasis?.(issue.issue_id)} title={!props.onResearchLegalBasis ? unavailable : undefined} type="button">Research legal basis</button></div> : null}
        {claims.map((claim) => <article className="wash-agent" key={`${claim.claim_id}:${claim.claim_revision ?? "legacy"}`} style={{ border: "1px dashed var(--agent-edge)", borderRadius: "var(--radius)", padding: 13, minWidth: 0 }}>
          <span className="state-label state-agent">Agent claim</span>{props.renderSupportedText ? <div style={reading}>{props.renderSupportedText({ text: claim.text, surface: "issue_claim", claim, claims: [claim] })}</div> : <p style={reading}>{claim.text}</p>}
          <dl style={{ display: "grid", gridTemplateColumns: "max-content minmax(0, 1fr)", gap: "5px 10px", fontSize: 13 }}><dt>Regulated actor</dt><dd style={{ margin: 0 }}>{claim.applicability?.regulated_actor || "Not stated"}</dd><dt>Jurisdiction</dt><dd style={{ margin: 0 }}>{claim.applicability?.jurisdiction || "Not stated"}</dd><dt>Application</dt><dd style={{ margin: 0 }}>{claim.applicability?.explanation || "Applicability is not explained."}</dd></dl>
          {claim.applicability?.fact_ids?.length ? <p style={muted}>Facts used: {claim.applicability.fact_ids.join(", ")}</p> : null}{claim.applicability?.assumption_ids?.length ? <p style={muted}>Assumptions used: {claim.applicability.assumption_ids.join(", ")}</p> : null}
          {claim.support_gap ? <p className="warning-callout" role="status"><strong>Support gap:</strong> {claim.support_gap}</p> : null}
          {claim.evidence.length ? <div style={{ display: "grid", gap: 7 }}>{claim.evidence.map((evidence, index) => <button className="btn quiet tiny" disabled={!props.onOpenEvidence} key={`${evidence.source_id}:${evidence.locator ?? "no-locator"}:${index}`} onClick={() => props.onOpenEvidence?.(evidence)} style={actionStyle} title={!props.onOpenEvidence ? unavailable : undefined} type="button">{evidence.source_label || evidence.source_id} · {evidence.locator || "Location unavailable"} · {evidence.support_state === "verified" ? "Verified" : evidence.support_state === "retrieved" ? "Retrieved" : evidence.support_state === "supplied" ? "Supplied" : "Support needs review"}</button>)}</div> : <p style={muted}><strong>No claim-level evidence is saved.</strong> This claim remains visible with its support gap.</p>}
        </article>)}
      </div>}
    </section></div>

    <section aria-labelledby={`questions-${issue.issue_id}`} className={styles.detailSection}>
      <span className="record-meta">Questions that change the answer</span><h3 className="section-heading" id={`questions-${issue.issue_id}`} style={{ margin: "5px 0" }}>Facts and legal questions</h3>
      {!questions.length ? <p style={muted}>No linked questions are saved for this issue.</p> : <div style={{ display: "grid", gap: 10 }}>{questions.map((question) => {
        const isLegal = question.question_kind === "legal";
        const saving = localBusy === `question:${question.question_id}`;
        return <article className={question.state === "answered" ? undefined : "wash-attention"} key={question.question_id} style={{ border: "1px solid var(--line-faint)", borderRadius: "var(--radius)", padding: 12 }}>
          <div className="btn-row"><span className={`state-label ${question.state === "answered" ? "state-healthy" : "state-attention"}`}>{questionLabel(question)}</span><span className="record-meta">{isLegal ? "Legal question" : "Factual question"}</span>{(question.issue_ids?.length ?? 0) > 1 ? <span className="record-meta">Shared with {question.issue_ids!.length} issues</span> : null}</div>
          <p style={reading}>{question.text}</p>{question.consequence ? <p style={muted}>{question.consequence}</p> : null}
          {question.answer ? <div><span className="record-meta">{question.answer_kind === "legal_analysis" || isLegal ? "Legal analysis" : "Reported fact"}</span><p style={reading}>{question.answer}</p></div> : null}
          {question.state !== "answered" ? <div style={{ display: "grid", gap: 8 }}><label className="field-block"><span className="field-label">{isLegal ? "Legal analysis" : "Reported fact"}</span><textarea className="text-input prose" disabled={busy || saving || !props.onQuestionAnswer} onChange={(event) => setAnswerDrafts((current) => ({ ...current, [question.question_id]: event.target.value }))} placeholder={isLegal ? "Record legal analysis. This will not create a reported fact." : "Record the answer as a reported fact."} value={answerDrafts[question.question_id] ?? ""} /></label><div className="btn-row"><button className="btn tiny" disabled={busy || saving || !props.onQuestionAnswer || !(answerDrafts[question.question_id] ?? "").trim()} onClick={() => void answerQuestion(question, "answered")} type="button">{saving ? "Saving…" : isLegal ? "Save legal analysis" : "Save reported fact"}</button><button className="btn quiet tiny" disabled={busy || saving || !props.onQuestionAnswer} onClick={() => void answerQuestion(question, "left_open")} type="button">Leave open</button></div>{!props.onQuestionAnswer ? <p style={muted}>{unavailable}</p> : null}</div> : null}
        </article>;
      })}</div>}
    </section>

    <section aria-labelledby={`ways-${issue.issue_id}`} className={styles.detailSection}>
      <span className="record-meta">Ways forward</span><h3 className="section-heading" id={`ways-${issue.issue_id}`} style={{ margin: "5px 0" }}>Options and mitigation</h3>
      {props.responseOptions?.length ? <div style={{ display: "grid", gap: 8, marginBottom: 10 }}>{props.responseOptions.map((option) => <article className="wash-agent" key={option.option_id} style={{ border: "1px dashed var(--agent-edge)", borderRadius: "var(--radius)", padding: 11 }}><div className="btn-row"><span className={`state-label ${option.state === "selected" ? "state-healthy" : option.state === "unknown" || !option.state ? "state-attention" : "state-agent"}`}>{option.state || "Unknown"}</span><span className="record-meta">{option.option_id}</span></div><h4 style={{ font: "600 16px/1.35 var(--serif)", margin: "6px 0" }}>{option.title}</h4><p style={muted}><strong>Condition:</strong> {option.condition?.trim() || "Unknown condition"}</p></article>)}</div> : <p style={muted}>No saved response options are linked to this issue.</p>}
      {workItems.length ? <div style={{ display: "grid", gap: 8 }}>{workItems.map((work) => <article key={work.work_item_id} style={{ border: "1px solid var(--line-faint)", borderRadius: "var(--radius)", padding: 11 }}><strong>{work.title}</strong><div className="btn-row" style={{ marginTop: 5 }}><span className={`state-label ${work.state === "done" || work.state === "complete" || work.state === "completed" ? "state-healthy" : "state-attention"}`}>{work.state === "done" || work.state === "complete" || work.state === "completed" ? "Completed" : work.state || "State unknown"}</span><span style={muted}>Owner: {work.owner || "Unassigned"}</span>{work.required ? <span className="state-label state-attention">Required</span> : null}</div></article>)}</div> : <p style={muted}>No mitigation work is linked to this issue.</p>}
      <div className="btn-row" style={{ marginTop: 10 }}><button className="btn tiny" disabled={!props.onCreateMitigation} onClick={() => props.onCreateMitigation?.(issue.issue_id)} title={!props.onCreateMitigation ? unavailable : undefined} type="button">Create mitigation work</button><button className="btn quiet tiny" disabled={!props.onRecordDecision} onClick={() => props.onRecordDecision?.(issue.issue_id)} title={!props.onRecordDecision ? unavailable : undefined} type="button">Record formal decision</button></div>
      {!props.onCreateMitigation && !props.onRecordDecision ? <p style={muted}>{unavailable}</p> : null}
    </section>

    <section aria-labelledby={`position-${issue.issue_id}`} className={styles.detailSection}>
      <span className="record-meta">Your recorded position</span><h3 className="section-heading" id={`position-${issue.issue_id}`} style={{ margin: "5px 0" }}>{currentDisposition}</h3>
      {issue.disposition_reason ? <p style={reading}>{issue.disposition_reason}</p> : <p style={muted}>No disposition reason is recorded.</p>}
      {decisions.length ? <div style={{ display: "grid", gap: 8 }}>{decisions.map((decision) => <article key={decision.decision_id} style={{ border: "1px solid var(--line-faint)", borderRadius: "var(--radius)", padding: 11 }}><span className="state-label state-healthy">Recorded</span><h4 style={{ font: "600 16px/1.35 var(--serif)", margin: "6px 0" }}>{decision.title}</h4><p style={reading}>{decision.chosen_path}</p><p style={muted}>{decision.rationale} · {decision.decision_maker || "Unknown decision maker"}{decision.decided_at ? ` · ${decision.decided_at}` : ""}</p></article>)}</div> : <p style={muted}>No formal decision is linked to this issue.</p>}
      {!dispositionFormOpen ? <button className="btn tiny" disabled={!props.onDisposition || busy || Boolean(localBusy)} onClick={openDispositionForm} style={{ ...actionStyle, marginTop: 12 }} title={!props.onDisposition ? unavailable : undefined} type="button">{issue.disposition && issue.disposition !== "unresolved" ? "Change or reopen disposition" : "Record disposition"}</button> : <fieldset disabled={busy || Boolean(localBusy)} style={{ border: "1px solid var(--line-faint)", borderRadius: "var(--radius)", margin: "14px 0 0", padding: 12 }}><legend className="field-label">Record issue disposition</legend>{dispositionBaseRevision !== issuesRevision ? <p className="warning-callout" role="status"><strong>The issue changed while this form was open.</strong> Cancel and open it again before you record a disposition.</p> : null}<label className="field-block"><span className="field-label">Disposition</span><select className="select-input" onChange={(event) => setDisposition(event.target.value as IssueDispositionState)} value={disposition}><option value="unresolved">Unresolved / reopen</option><option value="mitigation_in_progress">Mitigation in progress</option><option value="resolved">Resolved</option><option value="risk_accepted">Risk accepted</option><option value="not_applicable">Not applicable</option></select></label><label className="field-block"><span className="field-label">Reason</span><textarea className="text-input prose" onChange={(event) => setReason(event.target.value)} placeholder="Give the reason for this recorded position." value={reason} /></label>{disposition === "risk_accepted" ? <fieldset style={{ border: "1px solid var(--line-faint)", borderRadius: "var(--radius)", margin: "8px 0", padding: 10 }}><legend className="field-label">Decision that records risk acceptance</legend>{decisions.length ? decisions.map((decision) => <label key={decision.decision_id} style={{ display: "block", margin: "6px 0" }}><input checked={decisionIds.includes(decision.decision_id)} onChange={(event) => setDecisionIds((current) => event.target.checked ? [...new Set([...current, decision.decision_id])] : current.filter((id) => id !== decision.decision_id))} type="checkbox" /> {decision.title}</label>) : <p style={muted}>Record a formal decision before you accept risk.</p>}</fieldset> : null}<div className="btn-row"><button className="btn tiny" disabled={!reason.trim() || riskNeedsDecision || dispositionBaseRevision !== issuesRevision || busy || Boolean(localBusy)} onClick={() => void recordDisposition()} style={actionStyle} type="button">{localBusy === "disposition" ? "Recording…" : isReopen ? "Reopen issue" : "Record disposition"}</button><button className="btn quiet tiny" disabled={busy || Boolean(localBusy)} onClick={cancelDispositionForm} type="button">Cancel</button></div></fieldset>}
      {!props.onDisposition ? <p style={muted}>{unavailable}</p> : null}
      <details style={{ marginTop: 12 }}><summary>Disposition history ({issue.disposition_history?.length ?? 0})</summary>{issue.disposition_history?.length ? <ol style={{ ...muted, paddingLeft: 20 }}>{issue.disposition_history.map((record) => <li key={record.disposition_id} style={{ margin: "8px 0" }}><strong>{record.action === "reopened" ? "Reopened" : dispositionLabel(record.disposition)}</strong> · {record.actor_name || "Unknown actor"} · {record.recorded_at || "Date unavailable"}<br />{record.reason}</li>)}</ol> : <p style={muted}>No disposition history is saved.</p>}</details>
    </section>
    {(error || localError) ? <p className="warning-callout" role="status">{localError || error}</p> : null}
  </article>;
}

